// Comprobar si ya existe sesión iniciada
function checkSession() {
  const savedUser = sessionStorage.getItem(SESSION_KEY);
  if (savedUser) {
    showApp();
  } else {
    showLogin();
  }
}

// Configurar escuchadores de eventos
function setupEventListeners() {
  // Envío del formulario de Login
  loginForm.addEventListener("submit", (e) => {
    e.preventDefault();
    handleLogin();
  });

  // Botón de Cerrar Sesión
  btnLogout.addEventListener("click", () => {
    handleLogout();
  });

  // Navegación entre las 6 pestañas
  navTabs.forEach((tab) => {
    tab.addEventListener("click", () => {
      const sectionName = tab.getAttribute("data-section");
      switchSection(sectionName);
    });
  });

  // Botón Actualizar Dashboard
  const btnRefreshDashboard = document.getElementById("btn-refresh-dashboard");
  if (btnRefreshDashboard) {
    btnRefreshDashboard.addEventListener("click", () => {
      renderDashboardSection();
    });
  }
}

// Procesar inicio de sesión
function handleLogin() {
  const enteredUser = usernameInput.value.trim();
  const enteredPass = passwordInput.value;

  if (
    enteredUser === AUTH_CREDENTIALS.username &&
    enteredPass === AUTH_CREDENTIALS.password
  ) {
    // Credenciales correctas
    loginError.style.display = "none";
    sessionStorage.setItem(SESSION_KEY, enteredUser);
    loginForm.reset();
    showApp();
  } else {
    // Credenciales incorrectas
    loginError.style.display = "block";
    passwordInput.value = "";
    passwordInput.focus();
  }
}

// Procesar cierre de sesión
function handleLogout() {
  sessionStorage.removeItem(SESSION_KEY);
  showLogin();
}

// Mostrar pantalla de Login
function showLogin() {
  appView.classList.add("hidden");
  loginView.classList.remove("hidden");
  loginError.style.display = "none";
  usernameInput.focus();
}

// Mostrar pantalla de la App
function showApp() {
  loginView.classList.add("hidden");
  appView.classList.remove("hidden");
  // Iniciar por defecto en el primer módulo (Dashboard)
  switchSection("dashboard");
}

// Cambiar de sección activa
function switchSection(sectionName) {
  // Actualizar pestañas del menú
  navTabs.forEach((tab) => {
    if (tab.getAttribute("data-section") === sectionName) {
      tab.classList.add("active");
    } else {
      tab.classList.remove("active");
    }
  });

  // Actualizar paneles de contenido
  sectionPanels.forEach((panel) => {
    if (panel.id === `panel-${sectionName}`) {
      panel.classList.add("active");
    } else {
      panel.classList.remove("active");
    }
  });

  if (sectionName === "dashboard") {
    renderDashboardSection();
  }
  if (sectionName === "productos") {
    renderProducts();
  }
  if (sectionName === "clientes") {
    renderClients();
  }
  if (sectionName === "creditos") {
    renderCredits();
  }
  if (sectionName === "pagos") {
    renderPagosSection();
  }
  if (sectionName === "ventas") {
    renderVentasSection();
  }
  if (sectionName === "proveedores") {
    renderProveedoresSection();
  }
  if (sectionName === "facturacion") {
    renderFacturacionSection();
  }
  if (sectionName === "backup") {
    renderBackupSection();
  }
}

