  const btnCloseEditPay = document.getElementById("btn-close-edit-payment");
  const btnCancelEditPay = document.getElementById("btn-cancel-edit-payment");
  const editPayCurrency = document.getElementById("edit-pay-currency");
  const editPayAmountInput = document.getElementById("edit-pay-amount-usd");
  const editPayRateInput = document.getElementById("edit-pay-rate-bcv");

  if (editPayForm) editPayForm.addEventListener("submit", handleEditPaymentSubmit);
  if (btnCloseEditPay) btnCloseEditPay.addEventListener("click", closeEditPaymentModal);
  if (btnCancelEditPay) btnCancelEditPay.addEventListener("click", closeEditPaymentModal);

  const editPayBsInput = document.getElementById("edit-pay-amount-bs");

  if (editPayCurrency) {
    editPayCurrency.addEventListener("change", updateEditPaymentCalculations);
  }
  if (editPayAmountInput) {
    editPayAmountInput.addEventListener("input", () => {
      if (editPayCurrency && editPayCurrency.value === "BS") {
        const rateVal = parseFloat(editPayRateInput ? editPayRateInput.value : 0) || 0;
        const usdVal = parseFloat(editPayAmountInput.value) || 0;
        if (rateVal > 0 && editPayBsInput && document.activeElement !== editPayBsInput) {
          editPayBsInput.value = (usdVal * rateVal).toFixed(2);
        }
      }
      updateEditPaymentCalculations();
    });
  }
  if (editPayBsInput) {
    editPayBsInput.addEventListener("input", () => {
      const rateVal = parseFloat(editPayRateInput ? editPayRateInput.value : 0) || 0;
      const bsVal = parseFloat(editPayBsInput.value) || 0;
      if (rateVal > 0 && editPayAmountInput) {
        editPayAmountInput.value = (bsVal / rateVal).toFixed(2);
      }
      updateEditPaymentCalculations();
    });
  }
  if (editPayRateInput) {
    editPayRateInput.addEventListener("input", () => {
      const rateVal = parseFloat(editPayRateInput.value) || 0;
      if (rateVal > 0) {
        if (document.activeElement === editPayBsInput || (editPayBsInput && editPayBsInput.value && !editPayAmountInput.value)) {
          const bsVal = parseFloat(editPayBsInput.value) || 0;
          if (editPayAmountInput) editPayAmountInput.value = (bsVal / rateVal).toFixed(2);
        } else if (editPayAmountInput && editPayAmountInput.value) {
          const usdVal = parseFloat(editPayAmountInput.value) || 0;
          if (editPayBsInput) editPayBsInput.value = (usdVal * rateVal).toFixed(2);
        }
      }
      updateEditPaymentCalculations();
    });
  }

