// Utilidad para compresión y lectura de comprobante desde dispositivo
function handleReceiptPhotoUpload(file, callback, maxDim = 450) {
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(event) {
    const img = new Image();
    img.onload = function() {
      let width = img.width;
      let height = img.height;

      if (width > height && width > maxDim) {
        height = Math.round((height * maxDim) / width);
        width = maxDim;
      } else if (height > maxDim) {
        width = Math.round((width * maxDim) / height);
        height = maxDim;
      }

      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, width, height);

      const base64 = canvas.toDataURL("image/jpeg", 0.78);
      callback(base64);
    };
    img.src = event.target.result;
  };
  reader.readAsDataURL(file);
}

// ============================================================
// FASE 6: MÓDULO DE VENTAS DIRECTAS (VENTAS DE CONTADO)
// ============================================================
const SALES_STORAGE_KEY = "hogarflex_ventas_directas";
let currentSaleItems = [];
let currentSaleReceiptBase64 = null;
let currentSaleSearchQuery = "";
let salePendingDeleteId = null;
let currentEditingSaleId = null;

function getStoredSales() {
  try {
    const data = localStorage.getItem(SALES_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (err) {
    console.error("Error al cargar ventas directas de localStorage:", err);
    return [];
  }
}

function saveSalesToStorage(sales) {
  try {
    localStorage.setItem(SALES_STORAGE_KEY, JSON.stringify(sales));
    triggerAutoCloudBackup("ventas_directas");
  } catch (err) {
    console.error("Error al guardar ventas directas en localStorage:", err);
    alert("No se pudo guardar la venta directa. Espacio de almacenamiento lleno.");
  }
}

function initVentasModule() {
  const btnOpenAddSale = document.getElementById("btn-open-add-sale");
  const btnCloseSaleModal = document.getElementById("btn-close-sale-modal");
  const btnCancelSale = document.getElementById("btn-cancel-sale");
  const saleForm = document.getElementById("sale-form");
  const searchInput = document.getElementById("ventas-search-input");
  const btnAddProduct = document.getElementById("btn-add-product-to-sale");
  const paymentMethodSelect = document.getElementById("sale-payment-method");
  const salePriceUsdInput = document.getElementById("sale-price-usd");
  const saleRateBcvInput = document.getElementById("sale-rate-bcv");
  const saleAmountBsInput = document.getElementById("sale-amount-bs");
  const saleReceiptFile = document.getElementById("sale-receipt-file");
  const btnRemoveReceipt = document.getElementById("btn-remove-sale-receipt");

  // Modal Ver Detalle
  const btnCloseSaleDetail = document.getElementById("btn-close-sale-detail");
  const btnCloseSaleDetailFooter = document.getElementById("btn-close-sale-detail-footer");

  // Modal Confirmar Eliminar
  const btnCloseDeleteSaleModal = document.getElementById("btn-close-delete-sale-modal");
  const btnCancelDeleteSale = document.getElementById("btn-cancel-delete-sale");
  const btnConfirmDeleteSale = document.getElementById("btn-confirm-delete-sale");

  if (btnOpenAddSale) btnOpenAddSale.addEventListener("click", openAddSaleModal);
  if (btnCloseSaleModal) btnCloseSaleModal.addEventListener("click", closeSaleModal);
  if (btnCancelSale) btnCancelSale.addEventListener("click", closeSaleModal);
  if (saleForm) saleForm.addEventListener("submit", handleSaleFormSubmit);

  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      currentSaleSearchQuery = e.target.value.trim().toLowerCase();
      renderVentasSection();
    });
  }

  if (btnAddProduct) btnAddProduct.addEventListener("click", handleAddProductToSale);

  // Delegación para remover items de la venta en modal
  const itemsTbody = document.getElementById("sale-items-tbody");
  if (itemsTbody) {
    itemsTbody.addEventListener("click", (e) => {
      const removeBtn = e.target.closest(".btn-remove-item");
      if (removeBtn) {
        const idx = parseInt(removeBtn.getAttribute("data-index"), 10);
        if (!isNaN(idx) && idx >= 0 && idx < currentSaleItems.length) {
          currentSaleItems.splice(idx, 1);
          renderSaleItemsTable();
          // Actualizar sugerencia de precio si no hay precio personalizado
          updateSuggestedSalePrice();
        }
      }
    });
  }

  // Cambio de método de pago
  if (paymentMethodSelect) {
    paymentMethodSelect.addEventListener("change", () => {
      const isBs = paymentMethodSelect.value === "BS";
      const bsBox = document.getElementById("sale-bs-box");
      if (bsBox) {
        if (isBs) {
          bsBox.classList.remove("hidden");
        } else {
          bsBox.classList.add("hidden");
        }
      }
      updateSaleBsCalculations("usd");
    });
  }

  // Cálculos bidireccionales en Bolívares
  if (salePriceUsdInput) {
    salePriceUsdInput.addEventListener("input", () => {
      if (paymentMethodSelect && paymentMethodSelect.value === "BS") {
        updateSaleBsCalculations("usd");
      }
    });
  }
  if (saleRateBcvInput) {
    saleRateBcvInput.addEventListener("input", () => {
      if (paymentMethodSelect && paymentMethodSelect.value === "BS") {
        updateSaleBsCalculations("rate");
      }
    });
  }
  if (saleAmountBsInput) {
    saleAmountBsInput.addEventListener("input", () => {
      if (paymentMethodSelect && paymentMethodSelect.value === "BS") {
        updateSaleBsCalculations("bs");
      }
    });
  }

  // Subida y remoción de comprobante
  if (saleReceiptFile) {
    saleReceiptFile.addEventListener("change", (e) => {
      const file = e.target.files[0];
      if (file) {
        handleReceiptPhotoUpload(file, (base64) => {
          currentSaleReceiptBase64 = base64;
          const img = document.getElementById("sale-receipt-preview-img");
          const placeholder = document.getElementById("sale-receipt-placeholder");
          if (img) { img.src = base64; img.classList.remove("hidden"); }
          if (placeholder) placeholder.classList.add("hidden");
          if (btnRemoveReceipt) btnRemoveReceipt.classList.remove("hidden");
        });
      }
    });
  }
  if (btnRemoveReceipt) {
    btnRemoveReceipt.addEventListener("click", () => {
      currentSaleReceiptBase64 = null;
      if (saleReceiptFile) saleReceiptFile.value = "";
      const img = document.getElementById("sale-receipt-preview-img");
      const placeholder = document.getElementById("sale-receipt-placeholder");
      if (img) { img.src = ""; img.classList.add("hidden"); }
      if (placeholder) placeholder.classList.remove("hidden");
      btnRemoveReceipt.classList.add("hidden");
    });
  }

  // Cerrar modal de detalle
  if (btnCloseSaleDetail) btnCloseSaleDetail.addEventListener("click", closeSaleDetailModal);
  if (btnCloseSaleDetailFooter) btnCloseSaleDetailFooter.addEventListener("click", closeSaleDetailModal);

  // Modal eliminar
  if (btnCloseDeleteSaleModal) btnCloseDeleteSaleModal.addEventListener("click", closeDeleteSaleModal);
  if (btnCancelDeleteSale) btnCancelDeleteSale.addEventListener("click", closeDeleteSaleModal);
  if (btnConfirmDeleteSale) btnConfirmDeleteSale.addEventListener("click", executeDeleteSale);

  // Delegación de eventos en tabla de ventas (Ver, Editar, Eliminar, Lightbox comprobante)
  const ventasTbody = document.getElementById("ventas-tbody");
  if (ventasTbody) {
    ventasTbody.addEventListener("click", (e) => {
      const viewBtn = e.target.closest(".btn-action-view-sale");
      if (viewBtn) {
        e.preventDefault();
        const id = viewBtn.getAttribute("data-id");
        if (id) openSaleDetailModal(id);
        return;
      }

      const editBtn = e.target.closest(".btn-action-edit-sale");
      if (editBtn) {
        e.preventDefault();
        const id = editBtn.getAttribute("data-id");
        if (id) openEditSaleModal(id);
        return;
      }

      const deleteBtn = e.target.closest(".btn-action-delete-sale");
      if (deleteBtn) {
        e.preventDefault();
        const id = deleteBtn.getAttribute("data-id");
        if (id) openDeleteSaleModal(id);
        return;
      }

      const receiptThumb = e.target.closest(".receipt-thumbnail");
      if (receiptThumb) {
        e.preventDefault();
        const src = receiptThumb.getAttribute("data-receipt") || receiptThumb.src;
        if (src) openReceiptLightbox(src, "Comprobante de Venta");
        return;
      }
    });
  }

  // Render inicial de la vista
  renderVentasSection();
}

// Actualizar cálculos de Bolívares en el modal de venta
function updateSaleBsCalculations(source) {
  const priceInput = document.getElementById("sale-price-usd");
  const rateInput = document.getElementById("sale-rate-bcv");
  const bsInput = document.getElementById("sale-amount-bs");
  if (!priceInput || !rateInput || !bsInput) return;

  const rate = parseFloat(rateInput.value) || 0;

  if (source === "usd" || source === "rate") {
    const usd = parseFloat(priceInput.value) || 0;
    if (rate > 0 && usd > 0 && document.activeElement !== bsInput) {
      bsInput.value = (usd * rate).toFixed(2);
    }
  } else if (source === "bs") {
    const bs = parseFloat(bsInput.value) || 0;
    if (rate > 0 && bs > 0) {
      priceInput.value = (bs / rate).toFixed(2);
    }
  }
}

// Renderizar tabla principal de Ventas Directas
function renderVentasSection() {
  const tbody = document.getElementById("ventas-tbody");
  const emptyMsg = document.getElementById("empty-ventas-msg");
  if (!tbody || !emptyMsg) return;

  const sales = getStoredSales();

  // Ordenar cronológicamente (más recientes primero)
  sales.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  // Filtrar por búsqueda
  const filtered = sales.filter((s) => {
    if (!currentSaleSearchQuery) return true;
    const clientName = (s.client && s.client.name ? s.client.name : "").toLowerCase();
    const clientDni = (s.client && s.client.dni ? s.client.dni : "").toLowerCase();
    return clientName.includes(currentSaleSearchQuery) || clientDni.includes(currentSaleSearchQuery);
  });

  if (filtered.length === 0) {
    tbody.innerHTML = "";
    emptyMsg.classList.remove("hidden");
    return;
  }

  emptyMsg.classList.add("hidden");

  tbody.innerHTML = filtered.map((s) => {
    const dateObj = new Date(s.date + (String(s.date).includes("T") ? "" : "T00:00:00"));
    const dateStr = formatDateDisplay(dateObj);
    const clientName = escapeHtml(s.client ? s.client.name : "Sin nombre");
    const clientDni = escapeHtml(s.client ? s.client.dni : "-");

    // Resumen de productos
    const productsSummary = s.items && s.items.length > 0
      ? s.items.map((it) => `${escapeHtml(it.name)} (${it.quantity})`).join(", ")
      : "Sin productos";

    // Precio de venta
    const priceUSD = `$${parseFloat(s.salePriceUSD || 0).toFixed(2)} USD`;

    // Badge método de pago
    let methodHtml = "";
    if (s.paymentMethod === "BS") {
      methodHtml = `
        <span class="badge-method-bs">Bolívares (Bs)</span>
        <small style="display: block; color: #1e40af; font-weight: 600; font-size: 0.76rem; margin-top: 2px;">
          Bs. ${formatBs(s.amountBs || 0)} <br><span style="color: var(--color-text-muted);">(Tasa: ${parseFloat(s.rateBCVToday || 0).toFixed(2)})</span>
        </small>
      `;
    } else if (s.paymentMethod === "ZELLE") {
      methodHtml = '<span class="badge-method-zelle">Zelle</span>';
    } else if (s.paymentMethod === "TRANSFERENCIA") {
      methodHtml = '<span class="badge-method-transfer">Transferencia</span>';
    } else {
      methodHtml = '<span class="badge-method-usd">Divisas ($)</span>';
    }

    // Estado del comprobante
    const receiptBadge = s.receiptUrl
      ? `<span class="badge-receipt-yes receipt-thumbnail" data-receipt="${s.receiptUrl}" style="cursor: pointer;" title="Clic para ampliar comprobante">✓ Sí 🖼️</span>`
      : '<span class="badge-receipt-no">— No</span>';

    return `
      <tr>
        <td><strong style="color: var(--color-primary);">${dateStr}</strong></td>
        <td>
          <div style="font-weight: 700; color: var(--color-text);">${clientName}</div>
          <small style="color: var(--color-text-muted);">C.I: ${clientDni}</small>
        </td>
        <td>
          <div style="font-size: 0.88rem; max-width: 240px; white-space: normal; line-height: 1.35;">
            ${productsSummary}
          </div>
        </td>
        <td>
          <strong style="color: #15803d; font-size: 0.95rem;">${priceUSD}</strong>
        </td>
        <td>${methodHtml}</td>
        <td style="text-align: center;">${receiptBadge}</td>
        <td>
          <div style="display: flex; gap: 4px; flex-wrap: wrap;">
            <button type="button" class="btn-action-view-sale" data-id="${s.id}" title="Ver detalle de la venta">👁️ Ver</button>
            <button type="button" class="btn-action-edit-sale" data-id="${s.id}" title="Editar venta">✏️ Editar</button>
            <button type="button" class="btn-action-delete-sale" data-id="${s.id}" title="Eliminar venta">🗑️ Eliminar</button>
          </div>
        </td>
      </tr>
    `;
  }).join("");
}

// Abrir modal para crear nueva Venta Directa
function openAddSaleModal() {
  currentEditingSaleId = null;
  currentSaleItems = [];
  currentSaleReceiptBase64 = null;

  const modal = document.getElementById("modal-sale");
  const form = document.getElementById("sale-form");
  const title = document.getElementById("sale-modal-title");
  const editIdInput = document.getElementById("sale-edit-id");
  const errorMsg = document.getElementById("sale-form-error");

  if (form) form.reset();
  if (editIdInput) editIdInput.value = "";
  if (title) title.textContent = "Registrar Venta Directa";
  if (errorMsg) {
    errorMsg.style.display = "none";
    errorMsg.textContent = "";
  }

  // Poblar clientes
  populateSaleClientSelect();
  // Poblar productos
  populateSaleProductSelect();

  // Fecha por defecto hoy
  const dateInput = document.getElementById("sale-date");
  if (dateInput) dateInput.value = new Date().toISOString().split("T")[0];

  // Método por defecto Divisas
  const methodSelect = document.getElementById("sale-payment-method");
  if (methodSelect) methodSelect.value = "USD";
  const bsBox = document.getElementById("sale-bs-box");
  if (bsBox) bsBox.classList.add("hidden");

  // Reset comprobante
  resetSaleReceiptPreview();

  renderSaleItemsTable();
  updateSuggestedSalePrice();

  if (modal) modal.classList.remove("hidden");
}

// Abrir modal para editar Venta Directa existente
function openEditSaleModal(saleId) {
  const sales = getStoredSales();
  const sale = sales.find((s) => String(s.id) === String(saleId));
  if (!sale) return;

  currentEditingSaleId = saleId;
  currentSaleItems = sale.items ? JSON.parse(JSON.stringify(sale.items)) : [];
  currentSaleReceiptBase64 = sale.receiptUrl || null;

  const modal = document.getElementById("modal-sale");
  const form = document.getElementById("sale-form");
  const title = document.getElementById("sale-modal-title");
  const editIdInput = document.getElementById("sale-edit-id");
  const errorMsg = document.getElementById("sale-form-error");

  if (form) form.reset();
  if (editIdInput) editIdInput.value = sale.id;
  if (title) title.textContent = "Editar Venta Directa";
  if (errorMsg) {
    errorMsg.style.display = "none";
    errorMsg.textContent = "";
  }

  // Poblar clientes y productos
  populateSaleClientSelect();
  populateSaleProductSelect();

  // Seleccionar cliente
  const clientSelect = document.getElementById("sale-client-select");
  if (clientSelect) clientSelect.value = sale.clientId || (sale.client ? sale.client.id : "");

  // Fecha
  const dateInput = document.getElementById("sale-date");
  if (dateInput) dateInput.value = sale.date ? String(sale.date).split("T")[0] : new Date().toISOString().split("T")[0];

  // Precio en USD
  const priceInput = document.getElementById("sale-price-usd");
  if (priceInput) priceInput.value = parseFloat(sale.salePriceUSD || 0).toFixed(2);

  // Método de pago
  const methodSelect = document.getElementById("sale-payment-method");
  if (methodSelect) methodSelect.value = sale.paymentMethod || "USD";

  const bsBox = document.getElementById("sale-bs-box");
  const rateInput = document.getElementById("sale-rate-bcv");
  const bsInput = document.getElementById("sale-amount-bs");

  if (sale.paymentMethod === "BS") {
    if (bsBox) bsBox.classList.remove("hidden");
    if (rateInput) rateInput.value = sale.rateBCVToday || "";
    if (bsInput) bsInput.value = sale.amountBs ? parseFloat(sale.amountBs).toFixed(2) : "";
  } else {
    if (bsBox) bsBox.classList.add("hidden");
    if (rateInput) rateInput.value = "";
    if (bsInput) bsInput.value = "";
  }

  // Referencia y Notas
  const refInput = document.getElementById("sale-reference");
  if (refInput) refInput.value = sale.referenceNumber || "";

  const notesInput = document.getElementById("sale-notes");
  if (notesInput) notesInput.value = sale.notes || "";

  // Comprobante
  const img = document.getElementById("sale-receipt-preview-img");
  const placeholder = document.getElementById("sale-receipt-placeholder");
  const btnRemove = document.getElementById("btn-remove-sale-receipt");

  if (sale.receiptUrl) {
    if (img) { img.src = sale.receiptUrl; img.classList.remove("hidden"); }
    if (placeholder) placeholder.classList.add("hidden");
    if (btnRemove) btnRemove.classList.remove("hidden");
  } else {
    resetSaleReceiptPreview();
  }

  renderSaleItemsTable();
  updateSuggestedSalePrice(false);

  if (modal) modal.classList.remove("hidden");
}

function closeSaleModal() {
  const modal = document.getElementById("modal-sale");
  if (modal) modal.classList.add("hidden");
  currentEditingSaleId = null;
  currentSaleItems = [];
  currentSaleReceiptBase64 = null;
}

function resetSaleReceiptPreview() {
  const fileInput = document.getElementById("sale-receipt-file");
  const img = document.getElementById("sale-receipt-preview-img");
  const placeholder = document.getElementById("sale-receipt-placeholder");
  const btnRemove = document.getElementById("btn-remove-sale-receipt");

  if (fileInput) fileInput.value = "";
  if (img) { img.src = ""; img.classList.add("hidden"); }
  if (placeholder) placeholder.classList.remove("hidden");
  if (btnRemove) btnRemove.classList.add("hidden");
}

function populateSaleClientSelect() {
  const select = document.getElementById("sale-client-select");
  if (!select) return;
  const clients = getStoredClients();
  select.innerHTML = '<option value="">-- Seleccionar cliente registrado --</option>' +
    clients.map((c) => `<option value="${c.id}">${escapeHtml(c.name)} (${escapeHtml(c.dni)})</option>`).join("");
}

function populateSaleProductSelect() {
  const select = document.getElementById("sale-product-select");
  if (!select) return;
  const products = getStoredProducts();
  select.innerHTML = '<option value="">-- Seleccionar producto --</option>' +
    products.map((p) => {
      const hasQty = p.quantity !== null && p.quantity !== undefined && p.quantity !== "";
      const stockInfo = hasQty ? ` (Disponibles: ${p.quantity})` : "";
      return `<option value="${p.id}" data-price="${p.price}" data-name="${escapeHtml(p.name)}">${escapeHtml(p.name)} - $${parseFloat(p.price).toFixed(2)}${stockInfo}</option>`;
    }).join("");
}

// Añadir producto a la lista temporal de la venta directa
function handleAddProductToSale() {
  const select = document.getElementById("sale-product-select");
  const qtyInput = document.getElementById("sale-product-qty");
  const errorMsg = document.getElementById("sale-form-error");

  const productId = select.value;
  const qty = parseInt(qtyInput.value, 10);

  if (!productId) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor selecciona un producto para añadir.";
      errorMsg.style.display = "block";
    }
    return;
  }
  if (isNaN(qty) || qty <= 0) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor indica una cantidad válida mayor a cero.";
      errorMsg.style.display = "block";
    }
    return;
  }

  const selectedOption = select.options[select.selectedIndex];
  const productName = selectedOption.getAttribute("data-name");
  const productPrice = parseFloat(selectedOption.getAttribute("data-price"));

  if (errorMsg) errorMsg.style.display = "none";

  // Si ya existía, sumar cantidad sin bloquear venta
  const existingIdx = currentSaleItems.findIndex((item) => String(item.productId) === String(productId));
  if (existingIdx !== -1) {
    currentSaleItems[existingIdx].quantity += qty;
    currentSaleItems[existingIdx].qty = currentSaleItems[existingIdx].quantity;
    currentSaleItems[existingIdx].cantidad = currentSaleItems[existingIdx].quantity;
    currentSaleItems[existingIdx].subtotal = parseFloat((currentSaleItems[existingIdx].quantity * currentSaleItems[existingIdx].price).toFixed(2));
    currentSaleItems[existingIdx].totalLinea = currentSaleItems[existingIdx].subtotal;
  } else {
    const lineTotal = parseFloat((qty * productPrice).toFixed(2));
    currentSaleItems.push({
      id: "item_sale_" + Date.now() + "_" + Math.random().toString(36).substr(2, 4),
      productId,
      name: productName,
      nombre: productName,
      price: productPrice,
      priceUSD: productPrice,
      precioUnitario: productPrice,
      unitPrice: productPrice,
      quantity: qty,
      qty: qty,
      cantidad: qty,
      subtotal: lineTotal,
      totalLinea: lineTotal
    });
  }

  select.value = "";
  qtyInput.value = "1";

  renderSaleItemsTable();
  updateSuggestedSalePrice(true);
}

// Renderizar tabla de productos en el modal de venta
function renderSaleItemsTable() {
  const tbody = document.getElementById("sale-items-tbody");
  const emptyMsg = document.getElementById("empty-sale-items-msg");
  const table = document.getElementById("sale-items-table");
  const catalogSubtotalEl = document.getElementById("sale-catalog-subtotal");

  if (!tbody || !emptyMsg || !table) return;

  const catalogTotal = currentSaleItems.reduce((acc, it) => acc + it.subtotal, 0);
  if (catalogSubtotalEl) catalogSubtotalEl.textContent = `$${catalogTotal.toFixed(2)}`;

  if (currentSaleItems.length === 0) {
    table.classList.add("hidden");
    emptyMsg.classList.remove("hidden");
    tbody.innerHTML = "";
    return;
  }

  table.classList.remove("hidden");
  emptyMsg.classList.add("hidden");

  tbody.innerHTML = currentSaleItems.map((item, idx) => `
    <tr>
      <td><strong>${escapeHtml(item.name)}</strong></td>
      <td>${item.quantity}</td>
      <td>$${item.price.toFixed(2)}</td>
      <td><strong>$${item.subtotal.toFixed(2)}</strong></td>
      <td style="text-align: right;">
        <button type="button" class="btn-remove-item" data-index="${idx}" title="Quitar">✕</button>
      </td>
    </tr>
  `).join("");
}

// Sugerir el valor total del catálogo en el campo de precio de venta USD
function updateSuggestedSalePrice(forceUpdate = false) {
  const priceInput = document.getElementById("sale-price-usd");
  if (!priceInput) return;

  const catalogTotal = currentSaleItems.reduce((acc, it) => acc + it.subtotal, 0);

  // Si está creando nueva venta o forceUpdate o está vacío, actualizar con el catálogo
  if (forceUpdate || !priceInput.value || parseFloat(priceInput.value) === 0 || !currentEditingSaleId) {
    priceInput.value = catalogTotal > 0 ? catalogTotal.toFixed(2) : "";
  }

  // Recalcular monto en Bs si aplica
  const methodSelect = document.getElementById("sale-payment-method");
  if (methodSelect && methodSelect.value === "BS") {
    updateSaleBsCalculations("usd");
  }
}

// Guardar registro de Venta Directa (Crear o Editar)
function handleSaleFormSubmit(e) {
  e.preventDefault();

  const errorMsg = document.getElementById("sale-form-error");
  const clientSelect = document.getElementById("sale-client-select");
  const priceInput = document.getElementById("sale-price-usd");
  const methodSelect = document.getElementById("sale-payment-method");
  const rateInput = document.getElementById("sale-rate-bcv");
  const bsInput = document.getElementById("sale-amount-bs");
  const dateInput = document.getElementById("sale-date");
  const refInput = document.getElementById("sale-reference");
  const notesInput = document.getElementById("sale-notes");

  const clientId = clientSelect.value;
  if (!clientId) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor selecciona un cliente registrado.";
      errorMsg.style.display = "block";
    }
    clientSelect.focus();
    return;
  }

  if (currentSaleItems.length === 0) {
    if (errorMsg) {
      errorMsg.textContent = "Debes añadir al menos un producto a la venta.";
      errorMsg.style.display = "block";
    }
    return;
  }

  const salePriceUSD = parseFloat(priceInput.value);
  if (isNaN(salePriceUSD) || salePriceUSD <= 0) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor ingresa un precio de venta válido mayor a cero.";
      errorMsg.style.display = "block";
    }
    priceInput.focus();
    return;
  }

  const paymentMethod = methodSelect ? methodSelect.value : "USD";
  let rateBCVToday = null;
  let amountBs = 0;

  if (paymentMethod === "BS") {
    rateBCVToday = parseFloat(rateInput ? rateInput.value : 0) || 0;
    amountBs = parseFloat(bsInput ? bsInput.value : 0) || 0;

    if (rateBCVToday <= 0) {
      if (errorMsg) {
        errorMsg.textContent = "Por favor ingresa la Tasa BCV de hoy para ventas en Bolívares.";
        errorMsg.style.display = "block";
      }
      if (rateInput) rateInput.focus();
      return;
    }
    if (amountBs <= 0) {
      amountBs = salePriceUSD * rateBCVToday;
    }
  }

  const clients = getStoredClients();
  const clientObj = clients.find((c) => String(c.id) === String(clientId));
  if (!clientObj) {
    if (errorMsg) {
      errorMsg.textContent = "Cliente no encontrado en el sistema.";
      errorMsg.style.display = "block";
    }
    return;
  }

  const saleDate = dateInput && dateInput.value ? dateInput.value : new Date().toISOString().split("T")[0];
  const referenceNumber = refInput ? refInput.value.trim() : "";
  const notes = notesInput ? notesInput.value.trim() : "";
  const catalogTotalUSD = currentSaleItems.reduce((acc, it) => acc + it.subtotal, 0);

  const storedProducts = getStoredProducts();
  const sales = getStoredSales();

  if (currentEditingSaleId) {
    // Modo Edición: restaurar inventario previo y restar el nuevo
    const existingSaleIdx = sales.findIndex((s) => String(s.id) === String(currentEditingSaleId));
    if (existingSaleIdx !== -1) {
      const oldSale = sales[existingSaleIdx];

      // Restaurar unidades del inventario antiguo
      (oldSale.items || []).forEach((oldItem) => {
        const prod = storedProducts.find((p) => String(p.id) === String(oldItem.productId));
        if (prod && prod.quantity !== null && prod.quantity !== undefined && prod.quantity !== "") {
          const currentStock = parseInt(prod.quantity, 10) || 0;
          prod.quantity = currentStock + oldItem.quantity;
        }
      });

      // Restar nuevas unidades (informativo: si llega a 0 no bloquea)
      currentSaleItems.forEach((newItem) => {
        const prod = storedProducts.find((p) => String(p.id) === String(newItem.productId));
        if (prod && prod.quantity !== null && prod.quantity !== undefined && prod.quantity !== "") {
          const currentStock = parseInt(prod.quantity, 10) || 0;
          prod.quantity = currentStock - newItem.quantity;
        }
      });

      // Actualizar objeto de venta
      sales[existingSaleIdx] = {
        ...oldSale,
        clientId: clientObj.id,
        client: {
          id: clientObj.id,
          name: clientObj.name,
          dni: clientObj.dni,
          phone: clientObj.phone,
          address: clientObj.address
        },
        items: [...currentSaleItems],
        salePriceUSD,
        catalogTotalUSD,
        paymentMethod,
        rateBCVToday: paymentMethod === "BS" ? rateBCVToday : null,
        amountBs: paymentMethod === "BS" ? amountBs : 0,
        date: saleDate,
        referenceNumber,
        receiptUrl: currentSaleReceiptBase64 || null,
        notes,
        updatedAt: new Date().toISOString()
      };
    }
  } else {
    // Modo Creación: descontar unidades automáticamente (informativo: si llega a 0 no bloquea)
    currentSaleItems.forEach((item) => {
      const prod = storedProducts.find((p) => String(p.id) === String(item.productId));
      if (prod && prod.quantity !== null && prod.quantity !== undefined && prod.quantity !== "") {
        const currentStock = parseInt(prod.quantity, 10) || 0;
        prod.quantity = currentStock - item.quantity;
      }
    });

    const newSale = {
      id: "sale_" + Date.now(),
      clientId: clientObj.id,
      client: {
        id: clientObj.id,
        name: clientObj.name,
        dni: clientObj.dni,
        phone: clientObj.phone,
        address: clientObj.address
      },
      items: [...currentSaleItems],
      salePriceUSD,
      catalogTotalUSD,
      paymentMethod,
      rateBCVToday: paymentMethod === "BS" ? rateBCVToday : null,
      amountBs: paymentMethod === "BS" ? amountBs : 0,
      date: saleDate,
      referenceNumber,
      receiptUrl: currentSaleReceiptBase64 || null,
      notes,
      createdAt: new Date().toISOString()
    };

    sales.unshift(newSale);
  }

  // Guardar productos con stock actualizado
  saveProductsToStorage(storedProducts);
  renderProducts();

  // Guardar ventas
  saveSalesToStorage(sales);

  closeSaleModal();
  renderVentasSection();

  alert(currentEditingSaleId ? "¡Venta directa actualizada con éxito!" : "¡Venta directa registrada exitosamente y stock de productos actualizado!");
}

// Abrir modal de detalle completo de una venta directa
function openSaleDetailModal(saleId) {
  const sales = getStoredSales();
  const sale = sales.find((s) => String(s.id) === String(saleId));
  if (!sale) return;

  const modal = document.getElementById("modal-sale-detail");
  const nameEl = document.getElementById("detail-sale-client-name");
  const dniEl = document.getElementById("detail-sale-client-dni");
  const phoneEl = document.getElementById("detail-sale-client-phone");
  const dateEl = document.getElementById("detail-sale-date");
  const itemsTbody = document.getElementById("detail-sale-items-tbody");
  const priceEl = document.getElementById("detail-sale-price-usd");
  const methodBadge = document.getElementById("detail-sale-method-badge");
  const bsRow = document.getElementById("detail-sale-bs-row");
  const bsText = document.getElementById("detail-sale-bs-text");
  const refEl = document.getElementById("detail-sale-reference");
  const notesEl = document.getElementById("detail-sale-notes");
  const receiptContainer = document.getElementById("detail-sale-receipt-container");

  if (nameEl) nameEl.textContent = sale.client ? sale.client.name : "Sin nombre";
  if (dniEl) dniEl.textContent = sale.client ? sale.client.dni : "-";
  if (phoneEl) phoneEl.textContent = sale.client ? (sale.client.phone || "-") : "-";

  const dateObj = new Date(sale.date + (String(sale.date).includes("T") ? "" : "T00:00:00"));
  if (dateEl) dateEl.textContent = formatDateDisplay(dateObj);

  // Lista de productos
  if (itemsTbody) {
    itemsTbody.innerHTML = (sale.items || []).map((it) => `
      <tr>
        <td><strong>${escapeHtml(it.name)}</strong></td>
        <td>${it.quantity}</td>
        <td>$${parseFloat(it.price || 0).toFixed(2)} USD</td>
        <td><strong>$${parseFloat(it.subtotal || 0).toFixed(2)} USD</strong></td>
      </tr>
    `).join("");
  }

  // Precios y método
  if (priceEl) priceEl.textContent = `$${parseFloat(sale.salePriceUSD || 0).toFixed(2)} USD`;

  if (methodBadge) {
    if (sale.paymentMethod === "BS") {
      methodBadge.className = "badge-method-bs";
      methodBadge.textContent = "Bolívares (Bs.)";
    } else if (sale.paymentMethod === "ZELLE") {
      methodBadge.className = "badge-method-zelle";
      methodBadge.textContent = "Zelle";
    } else if (sale.paymentMethod === "TRANSFERENCIA") {
      methodBadge.className = "badge-method-transfer";
      methodBadge.textContent = "Transferencia";
    } else {
      methodBadge.className = "badge-method-usd";
      methodBadge.textContent = "Divisas ($ USD)";
    }
  }

  if (sale.paymentMethod === "BS") {
    if (bsRow) bsRow.classList.remove("hidden");
    if (bsText) bsText.textContent = `Bs. ${formatBs(sale.amountBs || 0)} (Tasa BCV: ${parseFloat(sale.rateBCVToday || 0).toFixed(2)} Bs/$)`;
  } else {
    if (bsRow) bsRow.classList.add("hidden");
  }

  if (refEl) refEl.textContent = sale.referenceNumber ? `#${sale.referenceNumber}` : "—";
  if (notesEl) notesEl.textContent = sale.notes ? sale.notes : "Sin notas adicionales.";

  // Comprobante
  if (receiptContainer) {
    if (sale.receiptUrl) {
      receiptContainer.innerHTML = `
        <img src="${sale.receiptUrl}" alt="Comprobante" class="receipt-thumbnail" style="width: 70px; height: 70px; object-fit: cover; border-radius: 6px; cursor: pointer; border: 1.5px solid var(--color-primary);" title="Clic para ver ampliado">
        <div>
          <strong style="display: block; font-size: 0.88rem; color: var(--color-primary);">Comprobante adjunto</strong>
          <small style="color: var(--color-text-muted);">Haz clic en la imagen para ampliar en pantalla completa.</small>
        </div>
      `;
      const thumb = receiptContainer.querySelector(".receipt-thumbnail");
      if (thumb) {
        thumb.addEventListener("click", () => {
          openReceiptLightbox(sale.receiptUrl, `Comprobante de Venta - ${sale.client ? sale.client.name : ''}`);
        });
      }
    } else {
      receiptContainer.innerHTML = '<span style="color: var(--color-text-muted); font-size: 0.88rem;">🧾 No se adjuntó comprobante para esta venta.</span>';
    }
  }

  if (modal) modal.classList.remove("hidden");
}

function closeSaleDetailModal() {
  const modal = document.getElementById("modal-sale-detail");
  if (modal) modal.classList.add("hidden");
}

// Modal para confirmar eliminación
function openDeleteSaleModal(saleId) {
  salePendingDeleteId = saleId;
  const modal = document.getElementById("modal-confirm-delete-sale");
  if (modal) modal.classList.remove("hidden");
}

function closeDeleteSaleModal() {
  const modal = document.getElementById("modal-confirm-delete-sale");
  if (modal) modal.classList.add("hidden");
  salePendingDeleteId = null;
}

// Ejecutar eliminación restaurando inventario
function executeDeleteSale() {
  if (!salePendingDeleteId) return;

  const sales = getStoredSales();
  const sale = sales.find((s) => String(s.id) === String(salePendingDeleteId));
  if (!sale) return;

  // Restaurar unidades al inventario
  const storedProducts = getStoredProducts();
  (sale.items || []).forEach((item) => {
    const prod = storedProducts.find((p) => String(p.id) === String(item.productId));
    if (prod && prod.quantity !== null && prod.quantity !== undefined && prod.quantity !== "") {
      const currentStock = parseInt(prod.quantity, 10) || 0;
      prod.quantity = currentStock + item.quantity;
    }
  });

  saveProductsToStorage(storedProducts);
  renderProducts();

  // Filtrar y guardar ventas
  const updatedSales = sales.filter((s) => String(s.id) !== String(salePendingDeleteId));
  saveSalesToStorage(updatedSales);

  closeDeleteSaleModal();
  renderVentasSection();

  alert("¡Venta directa eliminada correctamente y unidades restauradas al inventario!");
}

