// FASE 7: MÓDULO DE PROVEEDORES, COSTOS Y GASTOS OPERATIVOS
// ============================================================
const SUPPLIERS_STORAGE_KEY = "hogarflex_suppliers";
const EXPENSES_STORAGE_KEY = "hogarflex_expenses";

let currentSupplierSearchQuery = "";
let currentExpenseSearchQuery = "";
let currentActiveSupplierId = null;
let supplierPendingDeleteId = null;
let expensePendingDeleteId = null;
let currentCostEditingProductId = null;
let currentActiveSubtab = "directorio";

function getStoredSuppliers() {
  try {
    const data = localStorage.getItem(SUPPLIERS_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (err) {
    console.error("Error al cargar proveedores de localStorage:", err);
    return [];
  }
}

function saveSuppliersToStorage(suppliers) {
  try {
    localStorage.setItem(SUPPLIERS_STORAGE_KEY, JSON.stringify(suppliers));
    triggerAutoCloudBackup("proveedores");
  } catch (err) {
    console.error("Error al guardar proveedores en localStorage:", err);
    alert("No se pudo guardar la información del proveedor. Almacenamiento lleno.");
  }
}

function getStoredExpenses() {
  try {
    const data = localStorage.getItem(EXPENSES_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (err) {
    console.error("Error al cargar gastos de localStorage:", err);
    return [];
  }
}

function saveExpensesToStorage(expenses) {
  try {
    localStorage.setItem(EXPENSES_STORAGE_KEY, JSON.stringify(expenses));
    triggerAutoCloudBackup("gastos");
  } catch (err) {
    console.error("Error al guardar gastos en localStorage:", err);
    alert("No se pudo guardar el gasto. Almacenamiento lleno.");
  }
}

function initProveedoresModule() {
  // Subtabs internas de Proveedores
  const subtabBtns = document.querySelectorAll(".subnav-tab");
  subtabBtns.forEach((btn) => {
    btn.addEventListener("click", () => {
      const targetSubtab = btn.getAttribute("data-subtab");
      switchProveedoresSubtab(targetSubtab);
    });
  });

  // Búsqueda en directorio
  const supSearchInput = document.getElementById("suppliers-search-input");
  if (supSearchInput) {
    supSearchInput.addEventListener("input", (e) => {
      currentSupplierSearchQuery = e.target.value.trim().toLowerCase();
      renderSuppliersTable();
    });
  }

  // Búsqueda en gastos
  const expSearchInput = document.getElementById("expenses-search-input");
  if (expSearchInput) {
    expSearchInput.addEventListener("input", (e) => {
      currentExpenseSearchQuery = e.target.value.trim().toLowerCase();
      renderExpensesSection();
    });
  }

  // Botón Nuevo Proveedor
  const btnOpenAddSupplier = document.getElementById("btn-open-add-supplier");
  const btnCloseSupplierModal = document.getElementById("btn-close-supplier-modal");
  const btnCancelSupplier = document.getElementById("btn-cancel-supplier");
  const supplierForm = document.getElementById("supplier-form");

  if (btnOpenAddSupplier) btnOpenAddSupplier.addEventListener("click", openAddSupplierModal);
  if (btnCloseSupplierModal) btnCloseSupplierModal.addEventListener("click", closeSupplierModal);
  if (btnCancelSupplier) btnCancelSupplier.addEventListener("click", closeSupplierModal);
  if (supplierForm) supplierForm.addEventListener("submit", handleSupplierFormSubmit);

  // Modal Confirmar Eliminar Proveedor
  const btnCloseDeleteSupplier = document.getElementById("btn-close-delete-supplier-modal");
  const btnCancelDeleteSupplier = document.getElementById("btn-cancel-delete-supplier");
  const btnConfirmDeleteSupplier = document.getElementById("btn-confirm-delete-supplier");
  if (btnCloseDeleteSupplier) btnCloseDeleteSupplier.addEventListener("click", closeDeleteSupplierModal);
  if (btnCancelDeleteSupplier) btnCancelDeleteSupplier.addEventListener("click", closeDeleteSupplierModal);
  if (btnConfirmDeleteSupplier) btnConfirmDeleteSupplier.addEventListener("click", executeDeleteSupplier);

  // Modal Perfil Proveedor
  const btnCloseProfile = document.getElementById("btn-close-supplier-profile");
  const btnCloseProfileFooter = document.getElementById("btn-close-supplier-profile-footer");
  if (btnCloseProfile) btnCloseProfile.addEventListener("click", closeSupplierProfileModal);
  if (btnCloseProfileFooter) btnCloseProfileFooter.addEventListener("click", closeSupplierProfileModal);

  // Botón Asignar Costo
  const btnOpenAddCost = document.getElementById("btn-open-add-cost");
  const btnCloseCostModal = document.getElementById("btn-close-cost-modal");
  const btnCancelCost = document.getElementById("btn-cancel-cost");
  const costForm = document.getElementById("cost-form");
  const costProductSelect = document.getElementById("cost-product-select");
  const costCurrency = document.getElementById("cost-currency");
  const costPriceUsdInput = document.getElementById("cost-price-usd");
  const costSalePriceUsdInput = document.getElementById("cost-sale-price-usd");
  const costSupplierDiscountInput = document.getElementById("cost-supplier-discount");
  const costSupplierDiscountMethod = document.getElementById("cost-supplier-discount-method");
  const costAmountBsInput = document.getElementById("cost-amount-bs");
  const costRateBcvInput = document.getElementById("cost-rate-bcv");

  if (btnOpenAddCost) btnOpenAddCost.addEventListener("click", () => openAddCostModal());
  if (btnCloseCostModal) btnCloseCostModal.addEventListener("click", closeCostModal);
  if (btnCancelCost) btnCancelCost.addEventListener("click", closeCostModal);
  if (costForm) costForm.addEventListener("submit", handleCostFormSubmit);

  if (costProductSelect) {
    costProductSelect.addEventListener("change", () => {
      const selectedOption = costProductSelect.options[costProductSelect.selectedIndex];
      if (selectedOption && selectedOption.value) {
        const catPrice = parseFloat(selectedOption.getAttribute("data-price")) || 0;
        if (costSalePriceUsdInput && (!costSalePriceUsdInput.value || parseFloat(costSalePriceUsdInput.value) === 0 || !currentCostEditingProductId)) {
          costSalePriceUsdInput.value = catPrice.toFixed(2);
        }
      }
      updateCostCalculations();
    });
  }

  if (costCurrency) {
    costCurrency.addEventListener("change", () => {
      const bsBox = document.getElementById("cost-bs-fields-box");
      if (bsBox) {
        if (costCurrency.value === "BS") {
          bsBox.classList.remove("hidden");
        } else {
          bsBox.classList.add("hidden");
        }
      }
      updateCostBsConversion();
    });
  }

  if (costPriceUsdInput) costPriceUsdInput.addEventListener("input", updateCostCalculations);
  if (costSalePriceUsdInput) costSalePriceUsdInput.addEventListener("input", updateCostCalculations);
  if (costSupplierDiscountInput) costSupplierDiscountInput.addEventListener("input", updateCostCalculations);
  if (costSupplierDiscountMethod) costSupplierDiscountMethod.addEventListener("change", updateCostCalculations);

  if (costAmountBsInput) {
    costAmountBsInput.addEventListener("input", () => {
      const bsVal = parseFloat(costAmountBsInput.value) || 0;
      const rateVal = parseFloat(costRateBcvInput ? costRateBcvInput.value : 0) || 0;
      if (rateVal > 0 && bsVal > 0 && costPriceUsdInput) {
        costPriceUsdInput.value = (bsVal / rateVal).toFixed(2);
        updateCostCalculations();
      }
    });
  }
  if (costRateBcvInput) {
    costRateBcvInput.addEventListener("input", () => {
      const bsVal = parseFloat(costAmountBsInput ? costAmountBsInput.value : 0) || 0;
      const rateVal = parseFloat(costRateBcvInput.value) || 0;
      if (rateVal > 0 && bsVal > 0 && costPriceUsdInput) {
        costPriceUsdInput.value = (bsVal / rateVal).toFixed(2);
        updateCostCalculations();
      }
    });
  }

  // Calculadora Comparativa Divisas vs Bolívares
  const calcCmpBs = document.getElementById("calc-cmp-bs");
  const calcCmpUsd = document.getElementById("calc-cmp-usd");
  const calcCmpRate = document.getElementById("calc-cmp-rate");
  const calcCmpDiscount = document.getElementById("calc-cmp-usd-discount");
  if (calcCmpBs) calcCmpBs.addEventListener("input", updateCurrencyComparisonResult);
  if (calcCmpUsd) calcCmpUsd.addEventListener("input", updateCurrencyComparisonResult);
  if (calcCmpRate) calcCmpRate.addEventListener("input", updateCurrencyComparisonResult);
  if (calcCmpDiscount) calcCmpDiscount.addEventListener("input", updateCurrencyComparisonResult);

  // Selector comparativa entre proveedores
  const compareProdSelect = document.getElementById("compare-product-select");
  if (compareProdSelect) {
    compareProdSelect.addEventListener("change", handleCompareProductChange);
  }

  // Gastos Operativos: Botones y formulario
  const btnOpenAddExpense = document.getElementById("btn-open-add-expense");
  const btnCloseExpenseModal = document.getElementById("btn-close-expense-modal");
  const btnCancelExpense = document.getElementById("btn-cancel-expense");
  const expenseForm = document.getElementById("expense-form");
  const expenseCurrency = document.getElementById("expense-currency");

  if (btnOpenAddExpense) btnOpenAddExpense.addEventListener("click", openAddExpenseModal);
  if (btnCloseExpenseModal) btnCloseExpenseModal.addEventListener("click", closeExpenseModal);
  if (btnCancelExpense) btnCancelExpense.addEventListener("click", closeExpenseModal);
  if (expenseForm) expenseForm.addEventListener("submit", handleExpenseFormSubmit);

  if (expenseCurrency) {
    expenseCurrency.addEventListener("change", () => {
      const bsBox = document.getElementById("expense-bs-box");
      const sym = document.getElementById("expense-currency-symbol");
      if (expenseCurrency.value === "BS") {
        if (bsBox) bsBox.classList.remove("hidden");
        if (sym) sym.textContent = "Bs.";
      } else {
        if (bsBox) bsBox.classList.add("hidden");
        if (sym) sym.textContent = "$";
      }
    });
  }

  // Confirmar Eliminar Gasto
  const btnCloseDeleteExpense = document.getElementById("btn-close-delete-expense-modal");
  const btnCancelDeleteExpense = document.getElementById("btn-cancel-delete-expense");
  const btnConfirmDeleteExpense = document.getElementById("btn-confirm-delete-expense");
  if (btnCloseDeleteExpense) btnCloseDeleteExpense.addEventListener("click", closeDeleteExpenseModal);
  if (btnCancelDeleteExpense) btnCancelDeleteExpense.addEventListener("click", closeDeleteExpenseModal);
  if (btnConfirmDeleteExpense) btnConfirmDeleteExpense.addEventListener("click", executeDeleteExpense);

  // Delegación tabla proveedores
  const suppliersTbody = document.getElementById("suppliers-tbody");
  if (suppliersTbody) {
    suppliersTbody.addEventListener("click", (e) => {
      const viewBtn = e.target.closest(".btn-action-view-supplier");
      if (viewBtn) {
        e.preventDefault();
        const id = viewBtn.getAttribute("data-id");
        if (id) openSupplierProfileModal(id);
        return;
      }
      const editBtn = e.target.closest(".btn-action-edit-supplier");
      if (editBtn) {
        e.preventDefault();
        const id = editBtn.getAttribute("data-id");
        if (id) openEditSupplierModal(id);
        return;
      }
      const deleteBtn = e.target.closest(".btn-action-delete-supplier");
      if (deleteBtn) {
        e.preventDefault();
        const id = deleteBtn.getAttribute("data-id");
        if (id) openDeleteSupplierModal(id);
        return;
      }
    });
  }

  // Delegación tabla costos del proveedor
  const costsTbody = document.getElementById("supplier-costs-tbody");
  if (costsTbody) {
    costsTbody.addEventListener("click", (e) => {
      const editCostBtn = e.target.closest(".btn-action-edit-cost");
      if (editCostBtn) {
        e.preventDefault();
        const prodId = editCostBtn.getAttribute("data-product-id");
        if (prodId) openAddCostModal(prodId);
        return;
      }
      const deleteCostBtn = e.target.closest(".btn-action-delete-cost");
      if (deleteCostBtn) {
        e.preventDefault();
        const prodId = deleteCostBtn.getAttribute("data-product-id");
        if (prodId) removeCostFromSupplier(prodId);
        return;
      }
    });
  }

  // Delegación tabla gastos
  const expensesTbody = document.getElementById("expenses-tbody");
  if (expensesTbody) {
    expensesTbody.addEventListener("click", (e) => {
      const editBtn = e.target.closest(".btn-action-edit-expense");
      if (editBtn) {
        e.preventDefault();
        const id = editBtn.getAttribute("data-id");
        if (id) openEditExpenseModal(id);
        return;
      }
      const deleteBtn = e.target.closest(".btn-action-delete-expense");
      if (deleteBtn) {
        e.preventDefault();
        const id = deleteBtn.getAttribute("data-id");
        if (id) openDeleteExpenseModal(id);
        return;
      }
    });
  }

  renderProveedoresSection();
}

// Cambiar de subpestaña dentro de Proveedores
function switchProveedoresSubtab(subtabName) {
  currentActiveSubtab = subtabName;
  const subtabBtns = document.querySelectorAll(".subnav-tab");
  subtabBtns.forEach((btn) => {
    if (btn.getAttribute("data-subtab") === subtabName) {
      btn.classList.add("active");
    } else {
      btn.classList.remove("active");
    }
  });

  const views = document.querySelectorAll(".proveedores-subtab-view");
  views.forEach((v) => {
    if (v.id === `subtab-content-${subtabName}`) {
      v.classList.remove("hidden");
    } else {
      v.classList.add("hidden");
    }
  });

  if (subtabName === "directorio") {
    renderSuppliersTable();
  } else if (subtabName === "comparativa") {
    populateCompareProductSelect();
    handleCompareProductChange();
  } else if (subtabName === "gastos") {
    renderExpensesSection();
  }
}

// Render principal de la sección Proveedores
function renderProveedoresSection() {
  switchProveedoresSubtab(currentActiveSubtab || "directorio");
}

// Renderizar tabla del directorio de proveedores
function renderSuppliersTable() {
  const tbody = document.getElementById("suppliers-tbody");
  const emptyMsg = document.getElementById("empty-suppliers-msg");
  if (!tbody || !emptyMsg) return;

  const suppliers = getStoredSuppliers();

  // Filtrar según búsqueda
  const filtered = suppliers.filter((s) => {
    if (!currentSupplierSearchQuery) return true;
    const name = (s.name || "").toLowerCase();
    const loc = (s.location || "").toLowerCase();
    return name.includes(currentSupplierSearchQuery) || loc.includes(currentSupplierSearchQuery);
  });

  if (filtered.length === 0) {
    tbody.innerHTML = "";
    emptyMsg.classList.remove("hidden");
    return;
  }

  emptyMsg.classList.add("hidden");

  tbody.innerHTML = filtered.map((s) => {
    const methods = Array.isArray(s.paymentMethods) && s.paymentMethods.length > 0
      ? s.paymentMethods.map((m) => `<span class="badge-supplier-method">${escapeHtml(m)}</span>`).join(" ")
      : '<span style="color: var(--color-text-muted); font-size: 0.8rem;">Sin métodos especificados</span>';

    const costsCount = Array.isArray(s.productsCost) ? s.productsCost.length : 0;
    const countBadge = costsCount > 0
      ? `<span style="font-weight: 700; background: #e0f2fe; color: #0369a1; padding: 2px 8px; border-radius: 4px; font-size: 0.82rem;">${costsCount} producto(s)</span>`
      : '<span style="color: var(--color-text-muted); font-size: 0.82rem;">0 productos</span>';

    const phoneStr = s.phone ? `<small style="color: var(--color-text-muted); display: block;">📞 ${escapeHtml(s.phone)}</small>` : "";

    return `
      <tr>
        <td>
          <div style="font-weight: 700; color: var(--color-primary);">${escapeHtml(s.name)}</div>
          ${phoneStr}
        </td>
        <td>
          <span style="font-size: 0.9rem;">📍 ${escapeHtml(s.location || "No especificada")}</span>
        </td>
        <td>
          <div style="display: flex; gap: 4px; flex-wrap: wrap; max-width: 280px;">
            ${methods}
          </div>
        </td>
        <td>${countBadge}</td>
        <td>
          <div style="display: flex; gap: 4px; flex-wrap: wrap;">
            <button type="button" class="btn-action-view-supplier" data-id="${s.id}" title="Ver perfil y costos">👁️ Ver / Costos</button>
            <button type="button" class="btn-action-edit-supplier" data-id="${s.id}" title="Editar proveedor">✏️ Editar</button>
            <button type="button" class="btn-action-delete-supplier" data-id="${s.id}" title="Eliminar proveedor">🗑️ Eliminar</button>
          </div>
        </td>
      </tr>
    `;
  }).join("");
}

// Abrir modal para crear nuevo proveedor
function openAddSupplierModal() {
  const modal = document.getElementById("modal-supplier");
  const form = document.getElementById("supplier-form");
  const title = document.getElementById("supplier-modal-title");
  const editIdInput = document.getElementById("supplier-edit-id");
  const errorMsg = document.getElementById("supplier-form-error");

  if (form) form.reset();
  if (editIdInput) editIdInput.value = "";
  if (title) title.textContent = "Registrar Proveedor";
  if (errorMsg) {
    errorMsg.style.display = "none";
    errorMsg.textContent = "";
  }

  // Desmarcar checkboxes
  const checkboxes = document.querySelectorAll('input[name="supplier_payment_methods"]');
  checkboxes.forEach((cb) => (cb.checked = false));

  if (modal) modal.classList.remove("hidden");
}

// Abrir modal para editar proveedor
function openEditSupplierModal(supplierId) {
  const suppliers = getStoredSuppliers();
  const supplier = suppliers.find((s) => String(s.id) === String(supplierId));
  if (!supplier) return;

  const modal = document.getElementById("modal-supplier");
  const form = document.getElementById("supplier-form");
  const title = document.getElementById("supplier-modal-title");
  const editIdInput = document.getElementById("supplier-edit-id");
  const errorMsg = document.getElementById("supplier-form-error");

  if (form) form.reset();
  if (editIdInput) editIdInput.value = supplier.id;
  if (title) title.textContent = "Editar Proveedor";
  if (errorMsg) {
    errorMsg.style.display = "none";
    errorMsg.textContent = "";
  }

  document.getElementById("supplier-name").value = supplier.name || "";
  document.getElementById("supplier-location").value = supplier.location || "";
  document.getElementById("supplier-phone").value = supplier.phone || "";
  document.getElementById("supplier-notes").value = supplier.notes || "";

  const savedMethods = supplier.paymentMethods || [];
  const checkboxes = document.querySelectorAll('input[name="supplier_payment_methods"]');
  checkboxes.forEach((cb) => {
    cb.checked = savedMethods.includes(cb.value);
  });

  if (modal) modal.classList.remove("hidden");
}

function closeSupplierModal() {
  const modal = document.getElementById("modal-supplier");
  if (modal) modal.classList.add("hidden");
}

// Guardar proveedor (Crear o Editar)
function handleSupplierFormSubmit(e) {
  e.preventDefault();

  const nameInput = document.getElementById("supplier-name");
  const locInput = document.getElementById("supplier-location");
  const phoneInput = document.getElementById("supplier-phone");
  const notesInput = document.getElementById("supplier-notes");
  const editIdInput = document.getElementById("supplier-edit-id");
  const errorMsg = document.getElementById("supplier-form-error");

  const name = nameInput ? nameInput.value.trim() : "";
  const location = locInput ? locInput.value.trim() : "";
  const phone = phoneInput ? phoneInput.value.trim() : "";
  const notes = notesInput ? notesInput.value.trim() : "";
  const editId = editIdInput ? editIdInput.value.trim() : "";

  if (!name) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor ingresa el nombre del proveedor.";
      errorMsg.style.display = "block";
    }
    nameInput.focus();
    return;
  }
  if (!location) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor ingresa la ubicación o ciudad del proveedor.";
      errorMsg.style.display = "block";
    }
    locInput.focus();
    return;
  }

  // Métodos de pago seleccionados
  const paymentMethods = [];
  const checkboxes = document.querySelectorAll('input[name="supplier_payment_methods"]:checked');
  checkboxes.forEach((cb) => paymentMethods.push(cb.value));

  const suppliers = getStoredSuppliers();

  if (editId) {
    const idx = suppliers.findIndex((s) => String(s.id) === String(editId));
    if (idx !== -1) {
      suppliers[idx] = {
        ...suppliers[idx],
        name,
        location,
        phone,
        notes,
        paymentMethods,
        updatedAt: new Date().toISOString()
      };
    }
  } else {
    const newSupplier = {
      id: "sup_" + Date.now(),
      name,
      location,
      phone,
      notes,
      paymentMethods,
      productsCost: [],
      createdAt: new Date().toISOString()
    };
    suppliers.unshift(newSupplier);
  }

  saveSuppliersToStorage(suppliers);
  closeSupplierModal();
  renderSuppliersTable();
  populateCompareProductSelect();

  alert(editId ? "¡Proveedor actualizado con éxito!" : "¡Proveedor registrado exitosamente!");
}

// Modal eliminar proveedor
function openDeleteSupplierModal(supplierId) {
  supplierPendingDeleteId = supplierId;
  const modal = document.getElementById("modal-confirm-delete-supplier");
  if (modal) modal.classList.remove("hidden");
}

function closeDeleteSupplierModal() {
  const modal = document.getElementById("modal-confirm-delete-supplier");
  if (modal) modal.classList.add("hidden");
  supplierPendingDeleteId = null;
}

function executeDeleteSupplier() {
  if (!supplierPendingDeleteId) return;
  const suppliers = getStoredSuppliers();
  const updated = suppliers.filter((s) => String(s.id) !== String(supplierPendingDeleteId));
  saveSuppliersToStorage(updated);
  closeDeleteSupplierModal();
  renderSuppliersTable();
  populateCompareProductSelect();
  handleCompareProductChange();
  alert("¡Proveedor eliminado correctamente!");
}

// ============================================================
// PERFIL DEL PROVEEDOR, COSTOS Y CALCULADORA COMPARATIVA
// ============================================================
function openSupplierProfileModal(supplierId) {
  const suppliers = getStoredSuppliers();
  const supplier = suppliers.find((s) => String(s.id) === String(supplierId));
  if (!supplier) return;

  currentActiveSupplierId = supplierId;

  const modal = document.getElementById("modal-supplier-profile");
  const nameEl = document.getElementById("prof-supplier-name");
  const locEl = document.getElementById("prof-supplier-location");
  const phoneEl = document.getElementById("prof-supplier-phone");
  const methodsEl = document.getElementById("prof-supplier-methods");
  const notesEl = document.getElementById("prof-supplier-notes");

  if (nameEl) nameEl.textContent = supplier.name;
  if (locEl) locEl.textContent = `📍 ${supplier.location || "Sin ubicación"}`;
  if (phoneEl) phoneEl.textContent = supplier.phone ? `📞 ${supplier.phone}` : "";
  if (notesEl) notesEl.textContent = supplier.notes ? `Notas: ${supplier.notes}` : "Sin notas u observaciones.";

  if (methodsEl) {
    methodsEl.innerHTML = Array.isArray(supplier.paymentMethods) && supplier.paymentMethods.length > 0
      ? supplier.paymentMethods.map((m) => `<span class="badge-supplier-method">${escapeHtml(m)}</span>`).join("")
      : '<span style="color: var(--color-text-muted); font-size: 0.8rem;">Sin métodos especificados</span>';
  }

  // Renderizar tabla de costos del proveedor
  renderSupplierCostsTable();

  // Reset calculadora comparativa
  const calcCmpBs = document.getElementById("calc-cmp-bs");
  const calcCmpUsd = document.getElementById("calc-cmp-usd");
  const calcCmpRate = document.getElementById("calc-cmp-rate");
  const calcCmpDiscount = document.getElementById("calc-cmp-usd-discount");
  if (calcCmpBs) calcCmpBs.value = "";
  if (calcCmpUsd) calcCmpUsd.value = "";
  if (calcCmpRate) calcCmpRate.value = "";
  if (calcCmpDiscount) calcCmpDiscount.value = "0";
  updateCurrencyComparisonResult();

  if (modal) modal.classList.remove("hidden");
}

function closeSupplierProfileModal() {
  const modal = document.getElementById("modal-supplier-profile");
  if (modal) modal.classList.add("hidden");
  currentActiveSupplierId = null;
}

// Renderizar tabla de costos por producto asignados al proveedor actual
function renderSupplierCostsTable() {
  const tbody = document.getElementById("supplier-costs-tbody");
  const emptyMsg = document.getElementById("empty-supplier-costs-msg");
  if (!tbody || !emptyMsg) return;

  const suppliers = getStoredSuppliers();
  const supplier = suppliers.find((s) => String(s.id) === String(currentActiveSupplierId));
  if (!supplier) return;

  const costs = supplier.productsCost || [];

  if (costs.length === 0) {
    tbody.innerHTML = "";
    emptyMsg.classList.remove("hidden");
    return;
  }

  emptyMsg.classList.add("hidden");

  tbody.innerHTML = costs.map((c) => {
    const listUSD = parseFloat(c.costPriceUSD) || 0;
    const saleUSD = parseFloat(c.salePriceUSD) || 0;
    const discountPct = parseFloat(c.supplierDiscount !== undefined ? c.supplierDiscount : c.discountPercent) || 0;
    const discountMethod = c.supplierDiscountMethod || "Divisas efectivo";
    const realCostUSD = listUSD * (1 - discountPct / 100);
    const marginUSD = saleUSD - realCostUSD;
    const marginPct = saleUSD > 0 ? (marginUSD / saleUSD) * 100 : 0;

    const marginClass = marginUSD >= 0 ? "margin-positive" : "margin-negative";
    const marginIcon = marginUSD >= 0 ? "↑" : "↓";

    const costBsNote = c.currency === "BS" && c.amountBs > 0
      ? `<small style="display:block; color: #1e40af; font-size:0.75rem;">Bs. ${formatBs(c.amountBs)}</small>`
      : "";

    const discountBadge = discountPct > 0
      ? `<span style="font-weight: 700; background: #fef3c7; color: #92400e; padding: 2px 8px; border-radius: 4px; font-size: 0.8rem; display: inline-block;">${discountPct}% en ${escapeHtml(discountMethod)}</span>`
      : '<span style="color: var(--color-text-muted); font-size: 0.8rem;">Sin descuento</span>';

    return `
      <tr>
        <td><strong>${escapeHtml(c.productName)}</strong></td>
        <td>
          <strong>$${listUSD.toFixed(2)} USD</strong>
          ${costBsNote}
        </td>
        <td>${discountBadge}</td>
        <td>
          <strong style="color: #15803d; font-size: 0.95rem;">$${realCostUSD.toFixed(2)} USD</strong>
        </td>
        <td><strong style="color: var(--color-primary);">$${saleUSD.toFixed(2)} USD</strong></td>
        <td>
          <span class="${marginClass}">
            ${marginIcon} $${marginUSD.toFixed(2)} (${marginPct.toFixed(1)}%)
          </span>
        </td>
        <td>
          <div style="display: flex; gap: 4px;">
            <button type="button" class="btn-action-edit-cost btn-action-edit-supplier" data-product-id="${c.productId}" title="Editar costo">✏️</button>
            <button type="button" class="btn-action-delete-cost btn-action-delete-supplier" data-product-id="${c.productId}" title="Quitar producto de este proveedor">✕</button>
          </div>
        </td>
      </tr>
    `;
  }).join("");
}

// Modal Asignar / Editar Costo
function openAddCostModal(editProductId = null) {
  currentCostEditingProductId = editProductId;
  const modal = document.getElementById("modal-supplier-cost-form");
  const form = document.getElementById("cost-form");
  const title = document.getElementById("cost-modal-title");
  const editIdInput = document.getElementById("cost-edit-product-id");
  const errorMsg = document.getElementById("cost-form-error");

  if (form) form.reset();
  if (editIdInput) editIdInput.value = editProductId || "";
  if (title) title.textContent = editProductId ? "Editar Costo de Producto" : "Asignar Costo de Producto";
  if (errorMsg) {
    errorMsg.style.display = "none";
    errorMsg.textContent = "";
  }

  // Poblar select de productos
  const select = document.getElementById("cost-product-select");
  const products = getStoredProducts();
  if (select) {
    select.innerHTML = '<option value="">-- Seleccionar producto del catálogo --</option>' +
      products.map((p) => `<option value="${p.id}" data-price="${p.price}" data-name="${escapeHtml(p.name)}">${escapeHtml(p.name)} (Precio venta: $${parseFloat(p.price).toFixed(2)})</option>`).join("");
  }

  const bsBox = document.getElementById("cost-bs-fields-box");
  if (bsBox) bsBox.classList.add("hidden");

  const discountInput = document.getElementById("cost-supplier-discount");
  const discountMethodSelect = document.getElementById("cost-supplier-discount-method");

  if (editProductId) {
    const suppliers = getStoredSuppliers();
    const supplier = suppliers.find((s) => String(s.id) === String(currentActiveSupplierId));
    const costObj = supplier ? (supplier.productsCost || []).find((c) => String(c.productId) === String(editProductId)) : null;

    if (costObj) {
      if (select) {
        select.value = costObj.productId;
        select.disabled = true; // No cambiar producto en edición de costo
      }
      document.getElementById("cost-currency").value = costObj.currency || "USD";
      if (costObj.currency === "BS") {
        if (bsBox) bsBox.classList.remove("hidden");
        document.getElementById("cost-amount-bs").value = costObj.amountBs || "";
        document.getElementById("cost-rate-bcv").value = costObj.rateBCV || "";
      }
      document.getElementById("cost-price-usd").value = costObj.costPriceUSD || "";
      document.getElementById("cost-sale-price-usd").value = costObj.salePriceUSD || "";
      const disc = costObj.supplierDiscount !== undefined ? costObj.supplierDiscount : (costObj.discountPercent !== undefined ? costObj.discountPercent : 0);
      if (discountInput) discountInput.value = disc;
      if (discountMethodSelect) discountMethodSelect.value = costObj.supplierDiscountMethod || "Divisas efectivo";
    }
  } else {
    if (select) select.disabled = false;
    if (discountInput) discountInput.value = "0";
    if (discountMethodSelect) discountMethodSelect.value = "Divisas efectivo";
  }

  updateCostCalculations();

  if (modal) modal.classList.remove("hidden");
}

function closeCostModal() {
  const modal = document.getElementById("modal-supplier-cost-form");
  if (modal) modal.classList.add("hidden");
  currentCostEditingProductId = null;
}

function updateCostBsConversion() {
  const curr = document.getElementById("cost-currency").value;
  const costPriceUsdInput = document.getElementById("cost-price-usd");
  const costAmountBsInput = document.getElementById("cost-amount-bs");
  const costRateBcvInput = document.getElementById("cost-rate-bcv");

  if (curr === "BS") {
    const bsVal = parseFloat(costAmountBsInput ? costAmountBsInput.value : 0) || 0;
    const rateVal = parseFloat(costRateBcvInput ? costRateBcvInput.value : 0) || 0;
    if (rateVal > 0 && bsVal > 0 && costPriceUsdInput) {
      costPriceUsdInput.value = (bsVal / rateVal).toFixed(2);
    }
  }
  updateCostCalculations();
}

function updateCostCalculations() {
  const costPriceUsdInput = document.getElementById("cost-price-usd");
  const costSalePriceUsdInput = document.getElementById("cost-sale-price-usd");
  const costSupplierDiscountInput = document.getElementById("cost-supplier-discount");
  const costSupplierDiscountMethod = document.getElementById("cost-supplier-discount-method");

  const listUSD = parseFloat(costPriceUsdInput ? costPriceUsdInput.value : 0) || 0;
  const saleUSD = parseFloat(costSalePriceUsdInput ? costSalePriceUsdInput.value : 0) || 0;
  const discountPct = Math.min(100, Math.max(0, parseFloat(costSupplierDiscountInput ? costSupplierDiscountInput.value : 0) || 0));
  const method = costSupplierDiscountMethod ? costSupplierDiscountMethod.value : "Divisas efectivo";

  // Precio real pagado con descuento del proveedor aplicado
  const realCostUSD = listUSD * (1 - discountPct / 100);
  const realMarginUSD = saleUSD - realCostUSD;
  const realMarginPct = saleUSD > 0 ? (realMarginUSD / saleUSD) * 100 : 0;

  const realCostEl = document.getElementById("calc-cost-real-usd");
  const realExampleEl = document.getElementById("calc-cost-real-example");
  const realMarginEl = document.getElementById("calc-cost-real-margin");

  if (realCostEl) {
    realCostEl.textContent = `$${realCostUSD.toFixed(2)} USD`;
  }

  if (realExampleEl) {
    if (discountPct > 0) {
      realExampleEl.innerHTML = `Precio lista: <strong>$${listUSD.toFixed(2)}</strong> → con <strong>${discountPct}%</strong> descuento en <strong>${escapeHtml(method)}</strong> = <strong style="color: #15803d;">$${realCostUSD.toFixed(2)} USD</strong>`;
    } else {
      realExampleEl.innerHTML = `Precio lista: <strong>$${listUSD.toFixed(2)} USD</strong> (Sin descuento del proveedor)`;
    }
  }

  if (realMarginEl) {
    realMarginEl.textContent = `$${realMarginUSD.toFixed(2)} USD (${realMarginPct.toFixed(1)}%)`;
    realMarginEl.style.color = realMarginUSD >= 0 ? "#15803d" : "#dc2626";
  }
}

// Guardar costo de producto para el proveedor
function handleCostFormSubmit(e) {
  e.preventDefault();

  const select = document.getElementById("cost-product-select");
  const currencySelect = document.getElementById("cost-currency");
  const costPriceInput = document.getElementById("cost-price-usd");
  const salePriceInput = document.getElementById("cost-sale-price-usd");
  const discountInput = document.getElementById("cost-supplier-discount");
  const discountMethodSelect = document.getElementById("cost-supplier-discount-method");
  const bsAmountInput = document.getElementById("cost-amount-bs");
  const rateInput = document.getElementById("cost-rate-bcv");
  const errorMsg = document.getElementById("cost-form-error");

  const productId = select.value;
  if (!productId) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor selecciona un producto.";
      errorMsg.style.display = "block";
    }
    return;
  }

  const costPriceUSD = parseFloat(costPriceInput.value);
  if (isNaN(costPriceUSD) || costPriceUSD <= 0) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor ingresa un precio de costo de lista válido mayor a cero.";
      errorMsg.style.display = "block";
    }
    costPriceInput.focus();
    return;
  }

  const salePriceUSD = parseFloat(salePriceInput.value);
  if (isNaN(salePriceUSD) || salePriceUSD <= 0) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor ingresa un precio de venta válido mayor a cero.";
      errorMsg.style.display = "block";
    }
    salePriceInput.focus();
    return;
  }

  const currency = currencySelect.value;
  const amountBs = currency === "BS" ? (parseFloat(bsAmountInput ? bsAmountInput.value : 0) || 0) : 0;
  const rateBCV = currency === "BS" ? (parseFloat(rateInput ? rateInput.value : 0) || 0) : null;
  const supplierDiscount = Math.min(100, Math.max(0, parseFloat(discountInput ? discountInput.value : 0) || 0));
  const supplierDiscountMethod = discountMethodSelect ? discountMethodSelect.value : "Divisas efectivo";
  const realCostUSD = costPriceUSD * (1 - supplierDiscount / 100);

  const selectedOption = select.options[select.selectedIndex];
  const productName = selectedOption ? selectedOption.getAttribute("data-name") : "Producto";

  const suppliers = getStoredSuppliers();
  const supplier = suppliers.find((s) => String(s.id) === String(currentActiveSupplierId));
  if (!supplier) return;

  supplier.productsCost = supplier.productsCost || [];

  const existingIdx = supplier.productsCost.findIndex((c) => String(c.productId) === String(productId));
  const costData = {
    productId,
    productName,
    currency,
    costPriceUSD,
    salePriceUSD,
    supplierDiscount,
    supplierDiscountMethod,
    realCostUSD,
    discountPercent: supplierDiscount, // Compatibilidad hacia atrás
    amountBs,
    rateBCV,
    updatedAt: new Date().toISOString()
  };

  if (existingIdx !== -1) {
    supplier.productsCost[existingIdx] = costData;
  } else {
    supplier.productsCost.push(costData);
  }

  saveSuppliersToStorage(suppliers);
  closeCostModal();
  renderSupplierCostsTable();
  renderSuppliersTable();
  populateCompareProductSelect();
  handleCompareProductChange();

  alert("¡Costo de producto guardado con éxito para este proveedor!");
}

// Quitar costo de producto del proveedor
function removeCostFromSupplier(productId) {
  const suppliers = getStoredSuppliers();
  const supplier = suppliers.find((s) => String(s.id) === String(currentActiveSupplierId));
  if (!supplier) return;

  supplier.productsCost = (supplier.productsCost || []).filter((c) => String(c.productId) !== String(productId));
  saveSuppliersToStorage(suppliers);
  renderSupplierCostsTable();
  renderSuppliersTable();
  populateCompareProductSelect();
  handleCompareProductChange();
}

// Calculadora Comparativa Divisas vs Bolívares en perfil
function updateCurrencyComparisonResult() {
  const usdInput = document.getElementById("calc-cmp-usd");
  const bsInput = document.getElementById("calc-cmp-bs");
  const rateInput = document.getElementById("calc-cmp-rate");
  const discountInput = document.getElementById("calc-cmp-usd-discount");
  const resultBox = document.getElementById("calc-cmp-result-box");
  const resultText = document.getElementById("calc-cmp-result-text");

  if (!usdInput || !bsInput || !rateInput || !resultText || !resultBox) return;

  const priceUSD = parseFloat(usdInput.value) || 0;
  const priceBs = parseFloat(bsInput.value) || 0;
  const fxRate = parseFloat(rateInput.value) || 0;
  const discountPct = Math.min(100, Math.max(0, parseFloat(discountInput ? discountInput.value : 0) || 0));

  if (priceUSD <= 0 || priceBs <= 0 || fxRate <= 0) {
    resultText.innerHTML = "Ingresa los precios del proveedor y la tasa a la que consigues divisas arriba para calcular cuál opción es más económica y cuánto te ahorras.";
    resultBox.style.background = "#ffffff";
    resultBox.style.borderColor = "#93c5fd";
    return;
  }

  // Cuánto pago en USD si aplica descuento por pagar en divisas
  const effectiveUSD = priceUSD * (1 - discountPct / 100);

  // Opción 1: Cuánto me costaría en Bs si compro divisas para pagar
  const costBsViaDivisas = effectiveUSD * fxRate;

  // Opción 2: Cuánto me costaría pagando directo en Bs
  const costBsDirect = priceBs;

  const diffBs = Math.abs(costBsViaDivisas - costBsDirect);
  const diffUSD = diffBs / fxRate;

  const discountNote = discountPct > 0
    ? ` <span style="color: #92400e; font-weight: 600;">(con ${discountPct}% desc. en divisas: $${effectiveUSD.toFixed(2)} USD)</span>`
    : "";

  if (diffBs < 0.01) {
    resultText.innerHTML = `
      <div style="display: flex; align-items: center; gap: 8px;">
        <span style="font-size: 1.3rem;">⚖️</span>
        <div>
          <strong style="color: #1e3a8a; font-size: 0.98rem;">Ambas opciones tienen exactamente el mismo costo</strong>
          <div style="font-size: 0.88rem; color: #1e40af; margin-top: 4px;">
            Pagar directo en Bs: <strong>Bs. ${formatBs(costBsDirect)}</strong> | Comprar divisas: <strong>Bs. ${formatBs(costBsViaDivisas)}</strong> ($${effectiveUSD.toFixed(2)} USD a ${fxRate.toFixed(2)} Bs/$).
          </div>
        </div>
      </div>
    `;
    resultBox.style.background = "#f8fafc";
    resultBox.style.borderColor = "#cbd5e1";
  } else if (costBsDirect < costBsViaDivisas) {
    // Conviene pagar en Bolívares directamente
    const savingPct = ((costBsViaDivisas - costBsDirect) / costBsViaDivisas) * 100;
    resultText.innerHTML = `
      <div style="display: flex; flex-direction: column; gap: 10px;">
        <div style="display: flex; align-items: flex-start; gap: 10px;">
          <span style="font-size: 1.5rem; line-height: 1;">🟢</span>
          <div>
            <div style="color: #15803d; font-size: 1.05rem; font-weight: 800;">
              ¡Te conviene pagar directo en Bolívares!
            </div>
            <div style="font-size: 0.9rem; color: #166534; margin-top: 2px;">
              Ahorro exacto: <strong style="font-size: 1rem; color: #15803d;">Bs. ${formatBs(diffBs)}</strong> (~<strong style="color: #15803d;">$${diffUSD.toFixed(2)} USD</strong>) — <strong>${savingPct.toFixed(1)}% más barato</strong>.
            </div>
          </div>
        </div>

        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 10px; background: #ffffff; padding: 12px; border-radius: 8px; border: 1px solid #86efac;">
          <div style="border-right: 1px solid #e2e8f0; padding-right: 10px;">
            <div style="color: #15803d; font-weight: 700; font-size: 0.82rem; text-transform: uppercase;">✓ Pagando directo en Bs. (Mejor opción)</div>
            <div style="font-size: 1.15rem; font-weight: 800; color: #15803d; margin-top: 4px;">Bs. ${formatBs(costBsDirect)}</div>
            <small style="color: #64748b; font-size: 0.78rem;">Cobro del proveedor en Bolívares</small>
          </div>
          <div>
            <div style="color: #dc2626; font-weight: 700; font-size: 0.82rem; text-transform: uppercase;">✗ Comprando divisas para pagar</div>
            <div style="font-size: 1.15rem; font-weight: 800; color: #dc2626; margin-top: 4px;">Bs. ${formatBs(costBsViaDivisas)}</div>
            <small style="color: #64748b; font-size: 0.78rem;">$${effectiveUSD.toFixed(2)} USD × ${fxRate.toFixed(2)} Bs/$ ${discountNote}</small>
          </div>
        </div>
      </div>
    `;
    resultBox.style.background = "#f0fdf4";
    resultBox.style.borderColor = "#86efac";
  } else {
    // Conviene comprar divisas y pagar en USD
    const savingPct = ((costBsDirect - costBsViaDivisas) / costBsDirect) * 100;
    resultText.innerHTML = `
      <div style="display: flex; flex-direction: column; gap: 10px;">
        <div style="display: flex; align-items: flex-start; gap: 10px;">
          <span style="font-size: 1.5rem; line-height: 1;">🟢</span>
          <div>
            <div style="color: #1e40af; font-size: 1.05rem; font-weight: 800;">
              ¡Te conviene comprar divisas y pagar en USD!
            </div>
            <div style="font-size: 0.9rem; color: #1e3a8a; margin-top: 2px;">
              Ahorro exacto: <strong style="font-size: 1rem; color: #1e40af;">Bs. ${formatBs(diffBs)}</strong> (~<strong style="color: #1e40af;">$${diffUSD.toFixed(2)} USD</strong>) — <strong>${savingPct.toFixed(1)}% más barato</strong>.
            </div>
          </div>
        </div>

        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 10px; background: #ffffff; padding: 12px; border-radius: 8px; border: 1px solid #93c5fd;">
          <div style="border-right: 1px solid #e2e8f0; padding-right: 10px;">
            <div style="color: #1e40af; font-weight: 700; font-size: 0.82rem; text-transform: uppercase;">✓ Comprando divisas (Mejor opción)</div>
            <div style="font-size: 1.15rem; font-weight: 800; color: #1e40af; margin-top: 4px;">Bs. ${formatBs(costBsViaDivisas)}</div>
            <small style="color: #64748b; font-size: 0.78rem;">$${effectiveUSD.toFixed(2)} USD × ${fxRate.toFixed(2)} Bs/$ ${discountNote}</small>
          </div>
          <div>
            <div style="color: #dc2626; font-weight: 700; font-size: 0.82rem; text-transform: uppercase;">✗ Pagando directo en Bs.</div>
            <div style="font-size: 1.15rem; font-weight: 800; color: #dc2626; margin-top: 4px;">Bs. ${formatBs(costBsDirect)}</div>
            <small style="color: #64748b; font-size: 0.78rem;">Cobro del proveedor en Bolívares</small>
          </div>
        </div>
      </div>
    `;
    resultBox.style.background = "#eff6ff";
    resultBox.style.borderColor = "#93c5fd";
  }
}

// ============================================================
// COMPARATIVA ENTRE PROVEEDORES (VISTA DE COMPARACIÓN)
// ============================================================
function populateCompareProductSelect() {
  const select = document.getElementById("compare-product-select");
  if (!select) return;

  const currentVal = select.value;
  const products = getStoredProducts();

  select.innerHTML = '<option value="">-- Selecciona un producto para comparar proveedores --</option>' +
    products.map((p) => `<option value="${p.id}">${escapeHtml(p.name)} (Catálogo: $${parseFloat(p.price).toFixed(2)})</option>`).join("");

  if (currentVal && products.some((p) => String(p.id) === String(currentVal))) {
    select.value = currentVal;
  }
}

function handleCompareProductChange() {
  const select = document.getElementById("compare-product-select");
  const container = document.getElementById("compare-results-container");
  const promptMsg = document.getElementById("prompt-select-product-msg");
  const tbody = document.getElementById("compare-suppliers-tbody");
  const emptyMsg = document.getElementById("empty-compare-suppliers-msg");
  const prodNameEl = document.getElementById("compare-product-name");
  const prodPriceEl = document.getElementById("compare-product-price");
  const prodCatInfoEl = document.getElementById("compare-product-cat-info");

  if (!select || !container || !promptMsg || !tbody || !emptyMsg) return;

  const productId = select.value;
  if (!productId) {
    container.classList.add("hidden");
    promptMsg.classList.remove("hidden");
    return;
  }

  promptMsg.classList.add("hidden");
  container.classList.remove("hidden");

  const products = getStoredProducts();
  const product = products.find((p) => String(p.id) === String(productId));

  if (prodNameEl) prodNameEl.textContent = product ? product.name : "Producto";
  if (prodPriceEl) prodPriceEl.textContent = product ? `$${parseFloat(product.price).toFixed(2)} USD` : "$0.00";
  if (prodCatInfoEl) prodCatInfoEl.textContent = product ? `Categoría: ${product.category || 'General'} | Ref catálogo: #${product.id}` : "";

  const suppliers = getStoredSuppliers();
  const comparisonList = [];

  suppliers.forEach((s) => {
    const costItem = (s.productsCost || []).find((c) => String(c.productId) === String(productId));
    if (costItem) {
      const listPriceUSD = parseFloat(costItem.costPriceUSD) || 0;
      const discountPct = parseFloat(costItem.supplierDiscount !== undefined ? costItem.supplierDiscount : costItem.discountPercent) || 0;
      const discountMethod = costItem.supplierDiscountMethod || "Divisas efectivo";
      const realCostUSD = listPriceUSD * (1 - discountPct / 100);

      comparisonList.push({
        supplierId: s.id,
        supplierName: s.name,
        location: s.location,
        paymentMethods: s.paymentMethods || [],
        listPriceUSD,
        discountPct,
        discountMethod,
        realCostUSD,
        salePriceUSD: parseFloat(costItem.salePriceUSD) || parseFloat(product ? product.price : 0) || 0,
        currency: costItem.currency,
        amountBs: costItem.amountBs
      });
    }
  });

  if (comparisonList.length === 0) {
    tbody.innerHTML = "";
    emptyMsg.classList.remove("hidden");
    return;
  }

  emptyMsg.classList.add("hidden");

  // Ordenar de menor a mayor por COSTO REAL (el más económico en costo real primero)
  comparisonList.sort((a, b) => a.realCostUSD - b.realCostUSD);

  const minRealCost = comparisonList[0].realCostUSD;
  const maxRealCost = comparisonList[comparisonList.length - 1].realCostUSD;

  tbody.innerHTML = comparisonList.map((item, idx) => {
    const marginUSD = item.salePriceUSD - item.realCostUSD;
    const marginPct = item.salePriceUSD > 0 ? (marginUSD / item.salePriceUSD) * 100 : 0;
    const isBest = idx === 0 && comparisonList.length > 1;
    const diffVsMax = maxRealCost - item.realCostUSD;

    let evalBadge = "";
    if (isBest) {
      evalBadge = `<span class="badge-best-price">🏆 Mejor Precio (Ahorras $${diffVsMax.toFixed(2)} USD)</span>`;
    } else if (idx === 0) {
      evalBadge = '<span class="badge-best-price">🏆 Mejor Precio</span>';
    } else {
      const extraCost = item.realCostUSD - minRealCost;
      evalBadge = `<span style="font-size: 0.78rem; color: #dc2626; font-weight: 600;">+$${extraCost.toFixed(2)} USD vs el más barato</span>`;
    }

    const methodsBadges = item.paymentMethods.map((m) => `<span class="badge-supplier-method">${escapeHtml(m)}</span>`).join(" ");

    const discountBadge = item.discountPct > 0
      ? `<span style="font-weight: 700; background: #fef3c7; color: #92400e; padding: 2px 8px; border-radius: 4px; font-size: 0.82rem;">${item.discountPct}%</span>`
      : '<span style="color: var(--color-text-muted); font-size: 0.82rem;">0%</span>';

    return `
      <tr style="${isBest ? 'background: #f0fdf4;' : ''}">
        <td>
          <div style="font-weight: 700; color: var(--color-primary);">${escapeHtml(item.supplierName)}</div>
        </td>
        <td>📍 ${escapeHtml(item.location || "-")}</td>
        <td>
          <strong style="color: #475569; font-size: 0.95rem;">$${item.listPriceUSD.toFixed(2)} USD</strong>
        </td>
        <td>${discountBadge}</td>
        <td>
          <strong style="color: #15803d; font-size: 1.05rem;">$${item.realCostUSD.toFixed(2)} USD</strong>
        </td>
        <td>
          <strong style="color: ${marginUSD >= 0 ? '#15803d' : '#dc2626'};">$${marginUSD.toFixed(2)} USD</strong>
        </td>
        <td>
          <strong style="color: ${marginUSD >= 0 ? '#15803d' : '#dc2626'};">${marginPct.toFixed(1)}%</strong>
        </td>
        <td>
          <div style="display: flex; gap: 4px; flex-wrap: wrap;">${methodsBadges}</div>
        </td>
        <td>${evalBadge}</td>
      </tr>
    `;
  }).join("");
}

// ============================================================
// REGISTRO DE GASTOS OPERATIVOS
// ============================================================
function renderExpensesSection() {
  const tbody = document.getElementById("expenses-tbody");
  const emptyMsg = document.getElementById("empty-expenses-msg");
  const monthTotalUsdEl = document.getElementById("expenses-month-total-usd");
  const monthTotalBsEl = document.getElementById("expenses-month-total-bs");
  const monthLabelEl = document.getElementById("expenses-month-label");

  if (!tbody || !emptyMsg) return;

  const expenses = getStoredExpenses();

  // Ordenar por fecha cronológica (más recientes primero)
  expenses.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  // Calcular total del mes actual
  const now = new Date();
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth();

  let monthTotalUSD = 0;
  let monthTotalBs = 0;

  expenses.forEach((exp) => {
    const expDate = new Date(exp.date + (String(exp.date).includes("T") ? "" : "T00:00:00"));
    if (expDate.getFullYear() === currentYear && expDate.getMonth() === currentMonth) {
      if (exp.currency === "BS") {
        monthTotalBs += parseFloat(exp.amount) || 0;
        if (exp.rateBCV && exp.rateBCV > 0) {
          monthTotalUSD += (parseFloat(exp.amount) || 0) / parseFloat(exp.rateBCV);
        }
      } else {
        monthTotalUSD += parseFloat(exp.amount) || 0;
      }
    }
  });

  const monthNames = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];
  if (monthLabelEl) monthLabelEl.textContent = `${monthNames[currentMonth]} ${currentYear}`;
  if (monthTotalUsdEl) monthTotalUsdEl.textContent = `$${monthTotalUSD.toFixed(2)} USD`;
  if (monthTotalBsEl) monthTotalBsEl.textContent = `Bs. ${formatBs(monthTotalBs)}`;

  // Filtrar según búsqueda
  const filtered = expenses.filter((e) => {
    if (!currentExpenseSearchQuery) return true;
    const desc = (e.description || "").toLowerCase();
    const type = (e.type || "").toLowerCase();
    return desc.includes(currentExpenseSearchQuery) || type.includes(currentExpenseSearchQuery);
  });

  if (filtered.length === 0) {
    tbody.innerHTML = "";
    emptyMsg.classList.remove("hidden");
    return;
  }

  emptyMsg.classList.add("hidden");

  tbody.innerHTML = filtered.map((e) => {
    const dateObj = new Date(e.date + (String(e.date).includes("T") ? "" : "T00:00:00"));
    const dateStr = formatDateDisplay(dateObj);

    let typeBadge = "";
    if (e.type === "Flete") {
      typeBadge = '<span class="badge-expense-flete">🚚 Flete</span>';
    } else if (e.type === "Emergencia") {
      typeBadge = '<span class="badge-expense-emergencia">🚨 Emergencia</span>';
    } else {
      typeBadge = '<span class="badge-expense-otro">📦 Otro</span>';
    }

    const amountStr = e.currency === "BS"
      ? `<strong>Bs. ${formatBs(e.amount)}</strong>`
      : `<strong style="color: #15803d; font-size: 0.98rem;">$${parseFloat(e.amount).toFixed(2)} USD</strong>`;

    const rateStr = e.currency === "BS" && e.rateBCV
      ? `<span style="font-size: 0.82rem; color: var(--color-text-muted); display: block;">Tasa: ${parseFloat(e.rateBCV).toFixed(2)} Bs/$ (Ref: ~$${(e.amount / e.rateBCV).toFixed(2)} USD)</span>`
      : "—";

    return `
      <tr>
        <td><strong>${dateStr}</strong></td>
        <td>${typeBadge}</td>
        <td>
          <div style="font-weight: 600; color: var(--color-text);">${escapeHtml(e.description)}</div>
          ${e.notes ? `<small style="color: var(--color-text-muted);">${escapeHtml(e.notes)}</small>` : ''}
        </td>
        <td>${amountStr}</td>
        <td>${rateStr}</td>
        <td>
          <div style="display: flex; gap: 4px;">
            <button type="button" class="btn-action-edit-expense btn-action-edit-supplier" data-id="${e.id}" title="Editar gasto">✏️</button>
            <button type="button" class="btn-action-delete-expense btn-action-delete-supplier" data-id="${e.id}" title="Eliminar gasto">🗑️</button>
          </div>
        </td>
      </tr>
    `;
  }).join("");
}

// Abrir modal registrar gasto
function openAddExpenseModal() {
  const modal = document.getElementById("modal-expense");
  const form = document.getElementById("expense-form");
  const title = document.getElementById("expense-modal-title");
  const editIdInput = document.getElementById("expense-edit-id");
  const errorMsg = document.getElementById("expense-form-error");

  if (form) form.reset();
  if (editIdInput) editIdInput.value = "";
  if (title) title.textContent = "Registrar Gasto Operativo";
  if (errorMsg) {
    errorMsg.style.display = "none";
    errorMsg.textContent = "";
  }

  const dateInput = document.getElementById("expense-date");
  if (dateInput) dateInput.value = new Date().toISOString().split("T")[0];

  const bsBox = document.getElementById("expense-bs-box");
  if (bsBox) bsBox.classList.add("hidden");
  const sym = document.getElementById("expense-currency-symbol");
  if (sym) sym.textContent = "$";

  if (modal) modal.classList.remove("hidden");
}

// Abrir modal editar gasto
function openEditExpenseModal(expenseId) {
  const expenses = getStoredExpenses();
  const expense = expenses.find((e) => String(e.id) === String(expenseId));
  if (!expense) return;

  const modal = document.getElementById("modal-expense");
  const form = document.getElementById("expense-form");
  const title = document.getElementById("expense-modal-title");
  const editIdInput = document.getElementById("expense-edit-id");
  const errorMsg = document.getElementById("expense-form-error");

  if (form) form.reset();
  if (editIdInput) editIdInput.value = expense.id;
  if (title) title.textContent = "Editar Gasto Operativo";
  if (errorMsg) {
    errorMsg.style.display = "none";
    errorMsg.textContent = "";
  }

  document.getElementById("expense-type").value = expense.type || "Flete";
  document.getElementById("expense-desc").value = expense.description || "";
  document.getElementById("expense-currency").value = expense.currency || "USD";
  document.getElementById("expense-amount").value = expense.amount || "";

  const bsBox = document.getElementById("expense-bs-box");
  const sym = document.getElementById("expense-currency-symbol");
  if (expense.currency === "BS") {
    if (bsBox) bsBox.classList.remove("hidden");
    if (sym) sym.textContent = "Bs.";
    document.getElementById("expense-rate-bcv").value = expense.rateBCV || "";
  } else {
    if (bsBox) bsBox.classList.add("hidden");
    if (sym) sym.textContent = "$";
  }

  document.getElementById("expense-date").value = expense.date ? String(expense.date).split("T")[0] : new Date().toISOString().split("T")[0];
  document.getElementById("expense-notes").value = expense.notes || "";

  if (modal) modal.classList.remove("hidden");
}

function closeExpenseModal() {
  const modal = document.getElementById("modal-expense");
  if (modal) modal.classList.add("hidden");
}

// Guardar gasto
function handleExpenseFormSubmit(e) {
  e.preventDefault();

  const type = document.getElementById("expense-type").value;
  const desc = document.getElementById("expense-desc").value.trim();
  const currency = document.getElementById("expense-currency").value;
  const amount = parseFloat(document.getElementById("expense-amount").value);
  const rateBCV = currency === "BS" ? (parseFloat(document.getElementById("expense-rate-bcv").value) || null) : null;
  const date = document.getElementById("expense-date").value;
  const notes = document.getElementById("expense-notes").value.trim();
  const editId = document.getElementById("expense-edit-id").value;
  const errorMsg = document.getElementById("expense-form-error");

  if (!desc) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor ingresa una descripción del gasto.";
      errorMsg.style.display = "block";
    }
    return;
  }
  if (isNaN(amount) || amount <= 0) {
    if (errorMsg) {
      errorMsg.textContent = "Por favor ingresa un monto válido mayor a cero.";
      errorMsg.style.display = "block";
    }
    return;
  }

  const expenses = getStoredExpenses();

  if (editId) {
    const idx = expenses.findIndex((ex) => String(ex.id) === String(editId));
    if (idx !== -1) {
      expenses[idx] = {
        ...expenses[idx],
        type,
        description: desc,
        currency,
        amount,
        rateBCV,
        date,
        notes,
        updatedAt: new Date().toISOString()
      };
    }
  } else {
    const newExpense = {
      id: "exp_" + Date.now(),
      type,
      description: desc,
      currency,
      amount,
      rateBCV,
      date: date || new Date().toISOString().split("T")[0],
      notes,
      createdAt: new Date().toISOString()
    };
    expenses.unshift(newExpense);
  }

  saveExpensesToStorage(expenses);
  closeExpenseModal();
  renderExpensesSection();

  alert(editId ? "¡Gasto operativo actualizado con éxito!" : "¡Gasto operativo registrado exitosamente!");
}

// Confirmar eliminar gasto
function openDeleteExpenseModal(expenseId) {
  expensePendingDeleteId = expenseId;
  const modal = document.getElementById("modal-confirm-delete-expense");
  if (modal) modal.classList.remove("hidden");
}

function closeDeleteExpenseModal() {
  const modal = document.getElementById("modal-confirm-delete-expense");
  if (modal) modal.classList.add("hidden");
  expensePendingDeleteId = null;
}

function executeDeleteExpense() {
  if (!expensePendingDeleteId) return;
  const expenses = getStoredExpenses();
  const updated = expenses.filter((e) => String(e.id) !== String(expensePendingDeleteId));
  saveExpensesToStorage(updated);
  closeDeleteExpenseModal();
  renderExpensesSection();
  alert("¡Gasto operativo eliminado correctamente!");
}

