// FASE 8: DASHBOARD FINANCIERO (LÓGICA)
// ============================================================
const DASHBOARD_MONTH_NAMES_SHORT = ["Ene", "Feb", "Mar", "Abr", "May", "Jun", "Jul", "Ago", "Sep", "Oct", "Nov", "Dic"];
const DASHBOARD_MONTH_NAMES_FULL = [
  "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
  "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
];

function parseDashboardDate(dateVal) {
  if (!dateVal) return null;
  const str = String(dateVal);
  const normalized = str.includes("T") ? str : str + "T00:00:00";
  const d = new Date(normalized);
  return isNaN(d.getTime()) ? null : d;
}

// Generador de gráficos de barras en SVG puro (sin librerías externas)
function generateBarChartSVG(items, options = {}) {
  const width = options.width || 460;
  const height = options.height || 210;
  const padLeft = 45;
  const padRight = 20;
  const padTop = 32;
  const padBottom = 42;

  const chartW = width - padLeft - padRight;
  const chartH = height - padTop - padBottom;

  const values = items.map((i) => (typeof i.value === "number" ? i.value : 0));
  const maxVal = Math.max(...values, 0);

  // Escala máxima limpia y redondeada
  let scaleMax = maxVal > 0 ? maxVal * 1.25 : 100;
  if (scaleMax > 100) scaleMax = Math.ceil(scaleMax / 50) * 50;
  else if (scaleMax > 20) scaleMax = Math.ceil(scaleMax / 10) * 10;
  else scaleMax = 20;

  const count = items.length;
  const slotW = chartW / count;
  const barW = Math.min(options.barWidth || 48, slotW * 0.65);

  let gridSvg = "";
  const gridSteps = 3;
  for (let s = 0; s <= gridSteps; s++) {
    const valAtStep = (scaleMax / gridSteps) * s;
    const yPos = padTop + chartH - (s / gridSteps) * chartH;
    gridSvg += `
      <line x1="${padLeft}" y1="${yPos}" x2="${width - padRight}" y2="${yPos}" stroke="#e2e8f0" stroke-width="1" stroke-dasharray="${s === 0 ? 'none' : '3,3'}" />
      <text x="${padLeft - 6}" y="${yPos + 4}" font-size="9" fill="#94a3b8" text-anchor="end" font-family="Inter, sans-serif">$${Math.round(valAtStep)}</text>
    `;
  }

  let barsSvg = "";
  items.forEach((item, idx) => {
    const xSlotCenter = padLeft + (idx + 0.5) * slotW;
    const barX = xSlotCenter - barW / 2;
    const barH = scaleMax > 0 ? (item.value / scaleMax) * chartH : 0;
    const barY = padTop + chartH - barH;

    const isCurrent = !!item.isCurrent;
    const barColor = isCurrent ? "#f5c400" : (options.defaultColor || "#1a3a6b");
    const textColor = isCurrent ? "#b45309" : "#1a3a6b";

    const valueLabel = item.value > 0 ? `$${item.value.toFixed(0)}` : "$0";
    const labelY = Math.max(padTop - 8, barY - 6);

    barsSvg += `
      <g class="chart-bar-group" style="cursor: pointer;">
        <title>${item.label}: $${item.value.toFixed(2)} USD</title>
        <rect x="${barX}" y="${barY}" width="${barW}" height="${Math.max(barH, 2)}" rx="5" ry="5" fill="${barColor}">
          <animate attributeName="height" from="0" to="${Math.max(barH, 2)}" dur="0.45s" fill="freeze" />
          <animate attributeName="y" from="${padTop + chartH}" to="${barY}" dur="0.45s" fill="freeze" />
        </rect>
        <text x="${xSlotCenter}" y="${labelY}" font-size="10" font-weight="700" fill="${textColor}" text-anchor="middle" font-family="Inter, sans-serif">${valueLabel}</text>
        <text x="${xSlotCenter}" y="${padTop + chartH + 16}" font-size="11" font-weight="${isCurrent ? '800' : '600'}" fill="${isCurrent ? '#1a3a6b' : '#475569'}" text-anchor="middle" font-family="Inter, sans-serif">${item.label}</text>
        ${item.sublabel ? `<text x="${xSlotCenter}" y="${padTop + chartH + 28}" font-size="9" fill="#94a3b8" text-anchor="middle" font-family="Inter, sans-serif">${item.sublabel}</text>` : ''}
      </g>
    `;
  });

  return `
    <svg viewBox="0 0 ${width} ${height}" width="100%" height="100%" preserveAspectRatio="xMidYMid meet" style="overflow: visible;">
      ${gridSvg}
      ${barsSvg}
    </svg>
  `;
}

// Render principal de la sección Dashboard Financiero
function renderDashboardSection() {
  const credits = getStoredCredits();
  const sales = getStoredSales();

  const now = new Date();
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth();
  const daysInCurrentMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

  // 1. Recolectar todas las transacciones de ingresos (Pagos de Créditos + Ventas Directas)
  let totalCobradoMesUSD = 0;
  let creditTxMesCount = 0;
  let salesTxMesCount = 0;

  // Semanas del mes actual (4 barras)
  const weeksData = [
    { label: "Sem 1", sublabel: "1-7", startDay: 1, endDay: 7, value: 0 },
    { label: "Sem 2", sublabel: "8-14", startDay: 8, endDay: 14, value: 0 },
    { label: "Sem 3", sublabel: "15-21", startDay: 15, endDay: 21, value: 0 },
    { label: "Sem 4+", sublabel: `22-${daysInCurrentMonth}`, startDay: 22, endDay: daysInCurrentMonth, value: 0 }
  ];

  // 6 últimos meses terminando en el actual
  const monthsData = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(currentYear, currentMonth - i, 1);
    monthsData.push({
      year: d.getFullYear(),
      month: d.getMonth(),
      label: DASHBOARD_MONTH_NAMES_SHORT[d.getMonth()],
      fullLabel: `${DASHBOARD_MONTH_NAMES_FULL[d.getMonth()]} ${d.getFullYear()}`,
      isCurrent: i === 0,
      value: 0
    });
  }

  // Procesar pagos de créditos
  credits.forEach((credit) => {
    const payments = credit.payments || [];
    payments.forEach((p) => {
      const amt = parseFloat(p.amountUSD) || 0;
      if (amt <= 0) return;
      const d = parseDashboardDate(p.date || p.createdAt);
      if (!d) return;

      const pYear = d.getFullYear();
      const pMonth = d.getMonth();
      const pDay = d.getDate();

      // Mes actual
      if (pYear === currentYear && pMonth === currentMonth) {
        totalCobradoMesUSD += amt;
        creditTxMesCount++;

        // Asignar a semana
        const w = weeksData.find((wk) => pDay >= wk.startDay && pDay <= wk.endDay);
        if (w) w.value += amt;
      }

      // Asignar a histórico de 6 meses
      const m = monthsData.find((mo) => mo.year === pYear && mo.month === pMonth);
      if (m) m.value += amt;
    });
  });

  // Procesar ventas directas
  sales.forEach((s) => {
    const amt = parseFloat(s.salePriceUSD) || 0;
    if (amt <= 0) return;
    const d = parseDashboardDate(s.date || s.createdAt);
    if (!d) return;

    const sYear = d.getFullYear();
    const sMonth = d.getMonth();
    const sDay = d.getDate();

    // Mes actual
    if (sYear === currentYear && sMonth === currentMonth) {
      totalCobradoMesUSD += amt;
      salesTxMesCount++;

      // Asignar a semana
      const w = weeksData.find((wk) => sDay >= wk.startDay && sDay <= wk.endDay);
      if (w) w.value += amt;
    }

    // Asignar a histórico de 6 meses
    const m = monthsData.find((mo) => mo.year === sYear && mo.month === sMonth);
    if (m) m.value += amt;
  });

  // 2. Total pendiente por cobrar (suma de saldos restantes de créditos activos)
  let totalPendienteUSD = 0;
  let activeCreditsWithBalanceCount = 0;

  credits.forEach((credit) => {
    if (credit.status !== "pagado") {
      let bal = parseFloat(credit.remainingBalance);
      if (isNaN(bal) || bal < 0) {
        bal = 0;
        if (Array.isArray(credit.installments)) {
          credit.installments.forEach((inst) => {
            if (inst.status !== "Pagada") {
              const instAmt = inst.remainingUSD !== undefined ? parseFloat(inst.remainingUSD) : parseFloat(inst.amountUSD);
              bal += (instAmt || 0);
            }
          });
        }
      }
      if (bal > 0.01) {
        totalPendienteUSD += bal;
        activeCreditsWithBalanceCount++;
      }
    }
  });

  // 3. Clientes activos con crédito (número de clientes con al menos un crédito activo)
  const activeClientsSet = new Set();
  credits.forEach((credit) => {
    if (credit.status !== "pagado") {
      const bal = parseFloat(credit.remainingBalance);
      const hasBalance = !isNaN(bal) ? bal > 0.01 : true;
      if (hasBalance) {
        const clientKey = credit.clientId || (credit.client ? credit.client.id || credit.client.cedula : null) || credit.clientCedula || credit.clientName;
        if (clientKey) activeClientsSet.add(String(clientKey).trim());
      }
    }
  });
  const activeClientsCount = activeClientsSet.size;

  // 4. Créditos vencidos y construcción de la tabla de morosos
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  const overdueCreditsList = [];

  credits.forEach((credit) => {
    if (credit.status === "pagado") return;
    const installments = credit.installments || [];

    const overdueInsts = [];
    let creditOverdueAmount = 0;
    let maxDelayDays = 0;

    installments.forEach((inst) => {
      if (inst.status !== "Pagada") {
        const dueDate = parseDashboardDate(inst.dueDate);
        if (dueDate) {
          dueDate.setHours(0, 0, 0, 0);
          const diffMs = today.getTime() - dueDate.getTime();
          const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
          if (diffDays > 0) {
            const instUnpaidUSD = inst.remainingUSD !== undefined ? parseFloat(inst.remainingUSD) : (parseFloat(inst.amountUSD) || 0);
            overdueInsts.push({
              number: inst.number || 1,
              dueDate: inst.dueDate,
              delayDays: diffDays,
              amountUSD: instUnpaidUSD
            });
            creditOverdueAmount += instUnpaidUSD;
            if (diffDays > maxDelayDays) {
              maxDelayDays = diffDays;
            }
          }
        }
      }
    });

    if (overdueInsts.length > 0) {
      const clientName = credit.clientName || (credit.client ? credit.client.name : "Cliente");
      const clientCedula = credit.clientCedula || (credit.client ? credit.client.cedula : "");
      const clientPhone = credit.clientPhone || (credit.client ? credit.client.phone : "");

      overdueCreditsList.push({
        creditId: credit.id,
        clientId: credit.clientId,
        clientName,
        clientCedula,
        clientPhone,
        overdueCount: overdueInsts.length,
        overdueInstallments: overdueInsts,
        totalOverdueUSD: creditOverdueAmount,
        maxDelayDays
      });
    }
  });

  // Ordenar por días de retraso (mayor primero)
  overdueCreditsList.sort((a, b) => b.maxDelayDays - a.maxDelayDays);
  const overdueCreditsCount = overdueCreditsList.length;

  // ==========================
  // ACTUALIZAR EL DOM
  // ==========================

  // KPI 1: Cobrado este mes
  const kpiCobradoVal = document.getElementById("kpi-total-cobrado-mes");
  const kpiCobradoSub = document.getElementById("kpi-sub-cobrado");
  if (kpiCobradoVal) kpiCobradoVal.textContent = `$${totalCobradoMesUSD.toFixed(2)} USD`;
  if (kpiCobradoSub) {
    const totalTx = creditTxMesCount + salesTxMesCount;
    kpiCobradoSub.textContent = totalTx > 0
      ? `${totalTx} ingreso(s) (${creditTxMesCount} créditos + ${salesTxMesCount} ventas)`
      : "0 transacciones este mes";
  }

  // KPI 2: Pendiente por cobrar
  const kpiPendienteVal = document.getElementById("kpi-total-pendiente");
  const kpiPendienteSub = document.getElementById("kpi-sub-pendiente");
  if (kpiPendienteVal) kpiPendienteVal.textContent = `$${totalPendienteUSD.toFixed(2)} USD`;
  if (kpiPendienteSub) kpiPendienteSub.textContent = `En ${activeCreditsWithBalanceCount} crédito(s) por pagar`;

  // KPI 3: Clientes activos con crédito
  const kpiClientesVal = document.getElementById("kpi-clientes-activos");
  const kpiClientesSub = document.getElementById("kpi-sub-clientes");
  if (kpiClientesVal) kpiClientesVal.textContent = String(activeClientsCount);
  if (kpiClientesSub) kpiClientesSub.textContent = activeClientsCount === 1 ? "1 cliente con deuda activa" : `${activeClientsCount} clientes con deuda activa`;

  // KPI 4: Créditos vencidos
  const kpiVencidosVal = document.getElementById("kpi-creditos-vencidos");
  const kpiVencidosSub = document.getElementById("kpi-sub-vencidos");
  if (kpiVencidosVal) kpiVencidosVal.textContent = String(overdueCreditsCount);
  if (kpiVencidosSub) {
    if (overdueCreditsCount === 0) {
      kpiVencidosSub.textContent = "¡Todo al día! Sin mora";
      kpiVencidosSub.style.color = "#15803d";
      if (kpiVencidosVal) kpiVencidosVal.style.color = "#15803d";
    } else {
      kpiVencidosSub.textContent = `${overdueCreditsCount} crédito(s) con retraso`;
      kpiVencidosSub.style.color = "#b91c1c";
      if (kpiVencidosVal) kpiVencidosVal.style.color = "#dc2626";
    }
  }

  // Gráfico 1: Semanas del mes actual
  const chartWeeksContainer = document.getElementById("chart-weeks-container");
  const chartWeekTotalEl = document.getElementById("chart-week-total");
  const chartWeekSubtitleEl = document.getElementById("chart-week-subtitle");
  if (chartWeekSubtitleEl) chartWeekSubtitleEl.textContent = `${DASHBOARD_MONTH_NAMES_FULL[currentMonth]} ${currentYear} (Créditos + Ventas directas)`;
  if (chartWeekTotalEl) chartWeekTotalEl.textContent = `$${totalCobradoMesUSD.toFixed(2)} USD`;
  if (chartWeeksContainer) {
    chartWeeksContainer.innerHTML = generateBarChartSVG(weeksData, {
      width: 460,
      height: 200,
      barWidth: 50,
      defaultColor: "#1a3a6b"
    });
  }

  // Gráfico 2: Últimos 6 meses
  const chartMonthsContainer = document.getElementById("chart-months-container");
  const chartMonthsTotalEl = document.getElementById("chart-months-total");
  const chartMonthsSubtitleEl = document.getElementById("chart-months-subtitle");
  const total6MesesUSD = monthsData.reduce((acc, m) => acc + m.value, 0);
  if (chartMonthsSubtitleEl && monthsData.length > 0) {
    chartMonthsSubtitleEl.textContent = `${monthsData[0].label} ${monthsData[0].year} – ${monthsData[monthsData.length - 1].label} ${monthsData[monthsData.length - 1].year}`;
  }
  if (chartMonthsTotalEl) chartMonthsTotalEl.textContent = `$${total6MesesUSD.toFixed(2)} USD`;
  if (chartMonthsContainer) {
    chartMonthsContainer.innerHTML = generateBarChartSVG(monthsData, {
      width: 480,
      height: 200,
      barWidth: 42,
      defaultColor: "#1a3a6b"
    });
  }

  // Tabla de Créditos Vencidos
  const overdueTbody = document.getElementById("dashboard-overdue-tbody");
  const overdueTable = document.getElementById("dashboard-overdue-table");
  const noOverdueCard = document.getElementById("no-overdue-credits-card");
  const overdueBadge = document.getElementById("overdue-credits-badge");

  if (overdueCreditsCount === 0) {
    if (overdueTable) overdueTable.classList.add("hidden");
    if (noOverdueCard) noOverdueCard.classList.remove("hidden");
    if (overdueBadge) overdueBadge.classList.add("hidden");
    if (overdueTbody) overdueTbody.innerHTML = "";
  } else {
    if (overdueTable) overdueTable.classList.remove("hidden");
    if (noOverdueCard) noOverdueCard.classList.add("hidden");
    if (overdueBadge) {
      overdueBadge.classList.remove("hidden");
      overdueBadge.textContent = `${overdueCreditsCount} crédito(s) en mora`;
    }

    if (overdueTbody) {
      overdueTbody.innerHTML = overdueCreditsList.map((c) => {
        const cuotasListStr = c.overdueInstallments.map((i) => `#${i.number}`).join(", ");
        return `
          <tr>
            <td>
              <div style="font-weight: 700; color: var(--color-primary);">${escapeHtml(c.clientName)}</div>
              <small style="color: var(--color-text-muted);">${c.clientCedula ? 'C.I: ' + escapeHtml(c.clientCedula) : ''} ${c.clientPhone ? '• 📞 ' + escapeHtml(c.clientPhone) : ''}</small>
            </td>
            <td>
              <span class="badge-overdue-tag">${c.overdueCount} cuota(s)</span>
              <small style="color: #64748b; font-size: 0.8rem; display: block; margin-top: 3px;">
                Cuotas: ${cuotasListStr}
              </small>
            </td>
            <td>
              <strong style="color: #dc2626; font-size: 1.05rem;">$${c.totalOverdueUSD.toFixed(2)} USD</strong>
            </td>
            <td>
              <span class="badge-delay-days">⚠️ ${c.maxDelayDays} día(s)</span>
            </td>
            <td>
              <div style="display: flex; gap: 6px; flex-wrap: wrap;">
                <button type="button" class="btn-primary-action btn-sm" onclick="openCreditPaymentModal('${c.creditId}')" style="padding: 4px 10px; font-size: 0.8rem;" title="Registrar pago a este crédito">💵 Cobrar</button>
                <button type="button" class="btn-action-history btn-sm" onclick="openCreditPaymentsHistoryModal('${c.creditId}')" style="padding: 4px 10px; font-size: 0.8rem;" title="Ver historial de pagos">📜 Historial</button>
              </div>
            </td>
          </tr>
        `;
      }).join("");
    }
  }
}

