const INVOICES_STORAGE_KEY = "hogarflex_invoices";

let currentPreviewDoc = null;
let currentInvoicesSearchQuery = "";
let currentInvoicesTypeFilter = "all";

// Obtener documentos de facturación guardados en localStorage con auto-recuperación de precios numéricos
function getStoredInvoices() {
  try {
    const data = localStorage.getItem(INVOICES_STORAGE_KEY);
    if (!data) return [];
    const list = JSON.parse(data);
    if (!Array.isArray(list)) return [];

    let modified = false;
    list.forEach((inv) => {
      if (inv && inv.data && Array.isArray(inv.data.items)) {
        inv.data.items.forEach((it) => {
          const qty = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
          let p = parseFloat(it.precioUnitario !== undefined ? it.precioUnitario : (it.price !== undefined ? it.price : (it.priceUSD !== undefined ? it.priceUSD : it.unitPrice))) || 0;
          let sub = parseFloat(it.totalLinea !== undefined ? it.totalLinea : it.subtotal) || parseFloat((p * qty).toFixed(2));

          if (p <= 0) {
            // Auto-recuperar precio desde catálogo de productos
            const catalog = typeof getStoredProducts === "function" ? getStoredProducts() : [];
            const itemName = String(it.nombre || it.name || "").trim();
            const cat = catalog.find(cp => (it.productId && String(cp.id) === String(it.productId)) || (cp.name && itemName && cp.name.trim().toLowerCase() === itemName.toLowerCase()));
            if (cat && parseFloat(cat.price) > 0) {
              p = parseFloat(cat.price);
              sub = parseFloat((p * qty).toFixed(2));
              modified = true;
            } else if (sub > 0 && qty > 0) {
              p = parseFloat((sub / qty).toFixed(2));
              modified = true;
            } else if (inv.totalAmountUSD && inv.data.items.length > 0) {
              p = parseFloat((parseFloat(inv.totalAmountUSD) / inv.data.items.length / qty).toFixed(2));
              sub = parseFloat((p * qty).toFixed(2));
              modified = true;
            }
          }

          if (it.precioUnitario === undefined || it.price === undefined || it.totalLinea === undefined) {
            modified = true;
          }

          const n = it.nombre || it.name || "Producto";
          it.name = n;
          it.nombre = n;
          it.quantity = qty;
          it.qty = qty;
          it.cantidad = qty;
          it.price = p;
          it.priceUSD = p;
          it.precioUnitario = p;
          it.unitPrice = p;
          it.subtotal = sub;
          it.totalLinea = sub;
        });
      }
    });

    if (modified) {
      try {
        localStorage.setItem(INVOICES_STORAGE_KEY, JSON.stringify(list));
      } catch (_) {}
    }
    return list;
  } catch (e) {
    console.error("Error al leer facturas de localStorage:", e);
    return [];
  }
}

// Guardar documentos de facturación en localStorage
function saveInvoicesToStorage(invoices) {
  try {
    localStorage.setItem(INVOICES_STORAGE_KEY, JSON.stringify(invoices));
    triggerAutoCloudBackup("facturación");
  } catch (e) {
    console.error("Error al guardar facturas en localStorage:", e);
  }
}

// Obtener tasa de cambio registrada para un crédito
function getCreditExchangeRate(credit) {
  if (!credit) return null;
  if (credit.rateBCV && parseFloat(credit.rateBCV) > 0) return parseFloat(credit.rateBCV);
  if (credit.initialRateBCV && parseFloat(credit.initialRateBCV) > 0) return parseFloat(credit.initialRateBCV);
  if (credit.payments && credit.payments.length > 0) {
    const pWithRate = credit.payments.find((p) => p.rateBCVToday && parseFloat(p.rateBCVToday) > 0);
    if (pWithRate) return parseFloat(pWithRate.rateBCVToday);
  }
  if (credit.downpaymentPaidBs > 0 && credit.downpaymentAmount > 0) {
    return credit.downpaymentPaidBs / credit.downpaymentAmount;
  }
  return null;
}

// Formatear número de teléfono para enlace de WhatsApp (wa.me)
function formatPhoneForWhatsApp(rawPhone) {
  if (!rawPhone) return "";
  let digits = String(rawPhone).replace(/\D/g, "");
  if (!digits) return "";
  if (digits.startsWith("0")) {
    digits = "58" + digits.substring(1);
  } else if (digits.length === 10 && (digits.startsWith("414") || digits.startsWith("424") || digits.startsWith("412") || digits.startsWith("416") || digits.startsWith("426"))) {
    digits = "58" + digits;
  }
  return digits;
}

// Inicializar módulo de Facturación
function initFacturacionModule() {
  const btnRefresh = document.getElementById("btn-refresh-invoices");
  if (btnRefresh) {
    btnRefresh.addEventListener("click", () => {
      renderFacturacionSection();
    });
  }

  const inputSearch = document.getElementById("input-search-invoices");
  if (inputSearch) {
    inputSearch.addEventListener("input", (e) => {
      currentInvoicesSearchQuery = (e.target.value || "").trim().toLowerCase();
      renderFacturacionSection();
    });
  }

  const selectFilter = document.getElementById("select-filter-invoice-type");
  if (selectFilter) {
    selectFilter.addEventListener("change", (e) => {
      currentInvoicesTypeFilter = e.target.value || "all";
      renderFacturacionSection();
    });
  }

  const btnCloseModal = document.getElementById("btn-close-invoice-preview");
  const btnCloseFooter = document.getElementById("btn-close-invoice-footer");
  if (btnCloseModal) btnCloseModal.addEventListener("click", closeInvoicePreviewModal);
  if (btnCloseFooter) btnCloseFooter.addEventListener("click", closeInvoicePreviewModal);

  const btnPrint = document.getElementById("btn-print-invoice-pdf");
  if (btnPrint) {
    btnPrint.addEventListener("click", () => {
      printInvoiceDoc();
    });
  }

  const btnShareWA = document.getElementById("btn-share-invoice-whatsapp");
  if (btnShareWA) {
    btnShareWA.addEventListener("click", () => {
      if (currentPreviewDoc) {
        shareDocViaWhatsApp(currentPreviewDoc);
      }
    });
  }

  // Delegación de eventos para la tabla de facturación
  const tbody = document.getElementById("invoices-tbody");
  if (tbody) {
    tbody.addEventListener("click", (e) => {
      const viewBtn = e.target.closest(".btn-action-view-inv");
      if (viewBtn) {
        e.preventDefault();
        const docId = viewBtn.getAttribute("data-id");
        const invoices = getStoredInvoices();
        const doc = invoices.find((d) => String(d.id) === String(docId));
        if (doc) openInvoicePreviewModal(doc);
        return;
      }

      const waBtn = e.target.closest(".btn-action-wa-inv");
      if (waBtn) {
        e.preventDefault();
        const docId = waBtn.getAttribute("data-id");
        const invoices = getStoredInvoices();
        const doc = invoices.find((d) => String(d.id) === String(docId));
        if (doc) shareDocViaWhatsApp(doc);
        return;
      }
    });
  }
}

// Generar y abrir Factura de Crédito con precios numéricos incrustados de forma permanente
function generateAndOpenCreditInvoice(creditId) {
  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(creditId));
  if (!credit) {
    alert("Crédito no encontrado.");
    return;
  }

  // Fallback para datos completos del cliente si no estuvieran en el crédito
  const clients = getStoredClients();
  const clientObj = clients.find((cl) => String(cl.id) === String(credit.clientId) || (cl.dni && credit.client && cl.dni === credit.client.dni)) || credit.client || {};

  const invoices = getStoredInvoices();
  // Verificar si ya existe una factura generada para este crédito
  let existingDoc = invoices.find((d) => d.type === "factura_credito" && String(d.creditId) === String(credit.id));

  const facturasCount = invoices.filter((d) => d.type === "factura_credito").length;
  const docNumber = existingDoc ? existingDoc.docNumber : `FAC-${String(facturasCount + 1).padStart(4, "0")}`;

  const rate = getCreditExchangeRate(credit);
  const totalSaleUSD = credit.totalSaleUSD || 0;
  const totalSaleBs = rate ? totalSaleUSD * rate : null;

  // Catálogo de productos para resolver precios faltantes en créditos antiguos
  const catalogProducts = typeof getStoredProducts === "function" ? getStoredProducts() : [];
  const rawItems = Array.isArray(credit.items) && credit.items.length > 0 ? credit.items : [];

  // Incrustar precios reales y totales directamente en el array de items de la factura
  const embeddedItems = rawItems.map((it, idx) => {
    const qty = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
    let unitPrice = parseFloat(
      it.precioUnitario !== undefined ? it.precioUnitario :
      (it.price !== undefined ? it.price :
      (it.priceUSD !== undefined ? it.priceUSD :
      it.unitPrice))
    ) || 0;

    const itemName = String(it.nombre || it.name || "Producto").trim();

    // Si el precio unitario es 0 o indefinido, resolver del catálogo en este momento
    if (unitPrice <= 0 && catalogProducts.length > 0) {
      const match = catalogProducts.find((p) =>
        (it.productId && String(p.id) === String(it.productId)) ||
        (it.id && String(p.id) === String(it.id)) ||
        (p.name && itemName && p.name.trim().toLowerCase() === itemName.toLowerCase())
      );
      if (match && parseFloat(match.price) > 0) {
        unitPrice = parseFloat(match.price);
      }
    }

    // Si aún es 0, intentar calcular desde subtotal o totalLinea
    if (unitPrice <= 0) {
      const lineSub = parseFloat(it.totalLinea !== undefined ? it.totalLinea : it.subtotal) || 0;
      if (lineSub > 0 && qty > 0) {
        unitPrice = parseFloat((lineSub / qty).toFixed(2));
      }
    }

    // Si aún es 0, distribuir proporcionalmente del total
    if (unitPrice <= 0 && totalSaleUSD > 0 && rawItems.length > 0) {
      const pTotal = parseFloat(credit.productsTotal) || (totalSaleUSD - (parseFloat(credit.shippingAmount) || 0));
      if (pTotal > 0) {
        unitPrice = parseFloat((pTotal / rawItems.length / qty).toFixed(2));
      }
    }

    const lineTotal = parseFloat((qty * unitPrice).toFixed(2));

    return {
      id: it.id || it.productId || `item_${Date.now()}_${idx}`,
      productId: it.productId || it.id || "",
      name: itemName,
      nombre: itemName,
      quantity: qty,
      qty: qty,
      cantidad: qty,
      price: unitPrice,
      priceUSD: unitPrice,
      precioUnitario: unitPrice,
      unitPrice: unitPrice,
      subtotal: lineTotal,
      totalLinea: lineTotal
    };
  });

  const invoiceDoc = {
    id: existingDoc ? existingDoc.id : `inv_fac_${Date.now()}_${Math.random().toString(36).substr(2, 4)}`,
    type: "factura_credito",
    docNumber,
    date: credit.createdAt ? new Date(credit.createdAt).toISOString() : new Date().toISOString(),
    creditId: credit.id,
    paymentId: null,
    client: {
      name: clientObj.name || (credit.client ? credit.client.name : "Cliente"),
      dni: clientObj.dni || (credit.client ? credit.client.dni : "-"),
      phone: clientObj.phone || (credit.client ? credit.client.phone : ""),
      address: clientObj.address || (credit.client ? credit.client.address : "No especificada")
    },
    totalAmountUSD: totalSaleUSD,
    totalAmountBs: totalSaleBs,
    rateBCV: rate,
    data: {
      items: embeddedItems,
      hasShipping: !!credit.hasShipping,
      shippingAmount: credit.shippingAmount || 0,
      productsTotal: credit.productsTotal || (totalSaleUSD - (credit.shippingAmount || 0)),
      totalSaleUSD: totalSaleUSD,
      downpaymentAmount: credit.downpaymentAmount || 0,
      downpaymentPercent: credit.downpaymentPercent || 0,
      downpaymentPaidUSD: credit.downpaymentPaidUSD || 0,
      downpaymentPaidBs: credit.downpaymentPaidBs || 0,
      downpaymentRefText: credit.downpaymentRefText || "",
      remainingBalance: credit.remainingBalance || 0,
      installmentsCount: credit.installmentsCount || (credit.installments ? credit.installments.length : 0),
      paymentFrequencyLabel: credit.paymentFrequencyLabel || "Mensual (cada 30 días)",
      installments: (credit.installments || []).map((inst) => ({
        number: inst.number,
        dueDate: inst.dueDate,
        amountUSD: inst.amountUSD,
        amountBs: rate ? inst.amountUSD * rate : null,
        status: inst.status || "Pendiente"
      }))
    },
    createdAt: existingDoc ? existingDoc.createdAt : Date.now()
  };

  if (existingDoc) {
    const idx = invoices.findIndex((d) => d.id === existingDoc.id);
    if (idx !== -1) invoices[idx] = invoiceDoc;
  } else {
    invoices.unshift(invoiceDoc);
  }

  saveInvoicesToStorage(invoices);
  renderFacturacionSection();
  openInvoicePreviewModal(invoiceDoc);
}

// Generar y abrir Recibo de Pago
function generateAndOpenPaymentReceipt(creditId, paymentId) {
  const credits = getStoredCredits();
  const credit = credits.find((c) => String(c.id) === String(creditId));
  if (!credit) return;

  const payments = credit.payments || [];
  const payment = payments.find((p) => String(p.id) === String(paymentId)) || payments[payments.length - 1];
  if (!payment) return;

  const clients = getStoredClients();
  const clientObj = clients.find((cl) => String(cl.id) === String(credit.clientId) || (cl.dni && credit.client && cl.dni === credit.client.dni)) || credit.client || {};

  const invoices = getStoredInvoices();
  let existingDoc = invoices.find((d) => d.type === "recibo_pago" && String(d.paymentId) === String(payment.id));

  const receiptsCount = invoices.filter((d) => d.type === "recibo_pago").length;
  const docNumber = existingDoc ? existingDoc.docNumber : `REC-${String(receiptsCount + 1).padStart(4, "0")}`;

  const pendingCount = (credit.installments || []).filter((inst) => inst.status !== "Pagada").length;
  const amountUSD = parseFloat(payment.amountUSD) || 0;
  const amountBs = parseFloat(payment.amountBs) || 0;
  const rateBCV = payment.rateBCVToday ? parseFloat(payment.rateBCVToday) : (payment.currency === "BS" && amountUSD > 0 && amountBs > 0 ? (amountBs / amountUSD) : null);

  const receiptDoc = {
    id: existingDoc ? existingDoc.id : `inv_rec_${Date.now()}_${Math.random().toString(36).substr(2, 4)}`,
    type: "recibo_pago",
    docNumber,
    date: payment.date || new Date().toISOString(),
    creditId: credit.id,
    paymentId: payment.id,
    client: {
      name: clientObj.name || (credit.client ? credit.client.name : "Cliente"),
      dni: clientObj.dni || (credit.client ? credit.client.dni : "-"),
      phone: clientObj.phone || (credit.client ? credit.client.phone : ""),
      address: clientObj.address || (credit.client ? credit.client.address : "")
    },
    totalAmountUSD: amountUSD,
    totalAmountBs: amountBs > 0 ? amountBs : (rateBCV ? amountUSD * rateBCV : null),
    rateBCV: rateBCV,
    data: {
      paymentType: payment.type, // "cuota" o "abono"
      installmentNumber: payment.installmentNumber || null,
      description: payment.description || (payment.type === "cuota" ? `Pago Cuota ${payment.installmentNumber || ""}` : "Abono libre a capital"),
      currency: payment.currency,
      referenceNumber: payment.referenceNumber || "",
      remainingBalanceAfter: payment.remainingBalanceAfter !== undefined ? payment.remainingBalanceAfter : credit.remainingBalance,
      pendingInstallmentsCount: pendingCount
    },
    createdAt: existingDoc ? existingDoc.createdAt : Date.now()
  };

  if (existingDoc) {
    const idx = invoices.findIndex((d) => d.id === existingDoc.id);
    if (idx !== -1) invoices[idx] = receiptDoc;
  } else {
    invoices.unshift(receiptDoc);
  }

  saveInvoicesToStorage(invoices);
  renderFacturacionSection();
  openInvoicePreviewModal(receiptDoc);
}

// Abrir modal de vista previa
function openInvoicePreviewModal(doc) {
  if (!doc) return;
  currentPreviewDoc = doc;

  const modal = document.getElementById("modal-invoice-preview");
  const sheet = document.getElementById("invoice-printable-sheet");
  const titleEl = document.getElementById("invoice-preview-modal-title");
  const iconEl = document.getElementById("invoice-preview-type-icon");

  if (titleEl) {
    titleEl.textContent = doc.type === "factura_credito"
      ? `Vista Previa — Factura de Crédito ${doc.docNumber}`
      : `Vista Previa — Recibo de Pago ${doc.docNumber}`;
  }

  if (iconEl) {
    iconEl.textContent = doc.type === "factura_credito" ? "📄" : "🧾";
  }

  if (sheet) {
    sheet.innerHTML = renderInvoiceDocumentHTML(doc);
  }

  if (modal) {
    modal.classList.remove("hidden");
  }
}

// Cerrar modal de vista previa
function closeInvoicePreviewModal() {
  const modal = document.getElementById("modal-invoice-preview");
  if (modal) modal.classList.add("hidden");
  currentPreviewDoc = null;
}

// Renderizar HTML del documento de Factura o Recibo para la vista previa e impresión
function renderInvoiceDocumentHTML(doc) {
  if (!doc) return "";

  const dateObj = new Date(doc.date || Date.now());
  const dateStr = formatDateDisplay(dateObj);
  const timeStr = (!isNaN(dateObj.getTime()) && String(doc.date).includes("T"))
    ? " " + dateObj.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
    : "";

  if (doc.type === "factura_credito") {
    // ---------------- FACTURA DE CRÉDITO ----------------
    const items = (doc.data && Array.isArray(doc.data.items)) ? doc.data.items : [];
    const installments = (doc.data && Array.isArray(doc.data.installments)) ? doc.data.installments : [];

    const productsRows = items.map((it) => {
      const qty = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
      let price = parseFloat(
        it.precioUnitario !== undefined ? it.precioUnitario :
        (it.price !== undefined ? it.price :
        (it.priceUSD !== undefined ? it.priceUSD :
        it.unitPrice))
      ) || 0;
      let sub = parseFloat(it.totalLinea !== undefined ? it.totalLinea : it.subtotal) || parseFloat((price * qty).toFixed(2));

      // Respaldo de emergencia si el documento histórico no traía precios incrustados
      if (price <= 0) {
        if (sub > 0 && qty > 0) {
          price = parseFloat((sub / qty).toFixed(2));
        } else if (doc.totalAmountUSD && items.length > 0) {
          price = parseFloat((parseFloat(doc.totalAmountUSD) / items.length / qty).toFixed(2));
          sub = parseFloat((price * qty).toFixed(2));
        }
      }

      const itemName = it.nombre || it.name || "Producto";

      return `
        <tr>
          <td style="text-align: center; width: 60px;"><strong>${qty}</strong></td>
          <td><strong>${escapeHtml(itemName)}</strong></td>
          <td style="text-align: right; width: 120px;">$${price.toFixed(2)} USD</td>
          <td style="text-align: right; width: 130px; font-weight: 700; color: var(--color-primary);">$${sub.toFixed(2)} USD</td>
        </tr>
      `;
    }).join("");

    const totalInstallmentsCount = installments.length;
    const paidInstallmentsCount = installments.filter((inst) => inst.status === "Pagada").length;
    const pendingInstallmentsCount = installments.filter((inst) => inst.status !== "Pagada").length;
    const downpaymentPaidVal = parseFloat(
      doc.data.downpaymentPaidUSD !== undefined && doc.data.downpaymentPaidUSD > 0
        ? doc.data.downpaymentPaidUSD
        : (doc.data.downpaymentAmount || 0)
    ).toFixed(2);

    const installmentsRows = installments.map((inst, index) => {
      const num = inst.number !== undefined ? inst.number : (index + 1);
      const dueDateStr = inst.dueDate ? formatDateDisplay(new Date(inst.dueDate + "T00:00:00")) : "-";
      const bsStr = inst.amountBs ? `Bs. ${formatBs(inst.amountBs)}` : (doc.rateBCV ? `Bs. ${formatBs(inst.amountUSD * doc.rateBCV)}` : "");
      const bsSubtext = bsStr ? `<br><small style="color: #64748b; font-weight: normal;">${bsStr}</small>` : "";

      let statusBadge = '<span class="status-badge-pending">Pendiente</span>';
      if (inst.status === "Pagada") {
        statusBadge = '<span class="status-badge-paid">Pagada</span>';
      } else if (inst.status === "Parcialmente pagada") {
        statusBadge = '<span class="status-badge-partial">Parcialmente pagada</span>';
      }

      return `
        <tr>
          <td style="text-align: center; font-weight: 700; width: 60px;">${num}</td>
          <td>${dueDateStr}</td>
          <td style="text-align: right; font-weight: 700;">$${parseFloat(inst.amountUSD).toFixed(2)} USD${bsSubtext}</td>
          <td style="text-align: center;">${statusBadge}</td>
        </tr>
      `;
    }).join("");

    const downpaymentDisplay = doc.data.downpaymentAmount > 0
      ? `$${parseFloat(doc.data.downpaymentAmount).toFixed(2)} USD`
      : "$0.00";

    const downpaymentBsDetail = doc.data.downpaymentPaidBs > 0
      ? `<div style="font-size: 0.74rem; color: #64748b;">(Eq. Bs. ${formatBs(doc.data.downpaymentPaidBs)})</div>`
      : "";

    const shippingText = doc.data.hasShipping && doc.data.shippingAmount > 0
      ? `$${parseFloat(doc.data.shippingAmount).toFixed(2)} USD`
      : "No aplica";

    const rateNote = doc.rateBCV
      ? `Tasa BCV del día: <strong>${parseFloat(doc.rateBCV).toFixed(2)} Bs/$</strong>`
      : "Tasa variable al momento del pago";

    return `
      <!-- Encabezado de Factura -->
      <div class="doc-top-bar">
        <div>
          <h1 class="doc-brand-title">HOGARFLEX NOELUIS</h1>
          <p class="doc-brand-subtitle">Muebles, Electrodomésticos y Financiamiento Flexible</p>
          <div style="font-size: 0.8rem; color: #64748b; margin-top: 4px;">Atención al Cliente · Garantía y Calidad</div>
        </div>
        <div class="doc-number-box">
          <span class="doc-type-badge">NOTA DE ENTREGA / FACTURA DE CRÉDITO</span>
          <div class="doc-number-text">${escapeHtml(doc.docNumber)}</div>
          <div class="doc-date-text">Fecha de emisión: <strong>${dateStr}${timeStr}</strong></div>
        </div>
      </div>

      <!-- Datos del Cliente -->
      <div class="doc-meta-card">
        <div class="doc-meta-item">
          <label>Cliente</label>
          <div class="val">${escapeHtml(doc.client.name)}</div>
        </div>
        <div class="doc-meta-item">
          <label>Cédula de Identidad</label>
          <div class="val">${escapeHtml(doc.client.dni)}</div>
        </div>
        <div class="doc-meta-item">
          <label>Teléfono</label>
          <div class="val">${escapeHtml(doc.client.phone || "No registrado")}</div>
        </div>
        <div class="doc-meta-item" style="grid-column: 1 / -1;">
          <label>Dirección de Habitación / Entrega</label>
          <div class="val">${escapeHtml(doc.client.address || "No especificada")}</div>
        </div>
      </div>

      <!-- Detalle de Productos -->
      <div class="doc-section-title">
        <svg fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" style="width:18px;height:18px;">
          <path stroke-linecap="round" stroke-linejoin="round" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
        </svg>
        <span>Detalle de Producto(s)</span>
      </div>
      <table class="doc-table">
        <thead>
          <tr>
            <th style="text-align: center; width: 60px;">Cant.</th>
            <th>Descripción del Producto</th>
            <th style="text-align: right; width: 120px;">Precio Unit.</th>
            <th style="text-align: right; width: 130px;">Subtotal USD</th>
          </tr>
        </thead>
        <tbody>
          ${productsRows || '<tr><td colspan="4" style="text-align:center;color:#94a3b8;">Sin productos especificados</td></tr>'}
        </tbody>
      </table>

      <!-- Resumen Financiero -->
      <div class="doc-summary-grid">
        <div class="doc-summary-box">
          <label>Subtotal Productos</label>
          <div class="amount" style="font-size: 1rem;">$${parseFloat(doc.data.productsTotal || doc.totalAmountUSD).toFixed(2)}</div>
          <div class="subtext">Flete: ${shippingText}</div>
        </div>
        <div class="doc-summary-box highlight-primary">
          <label>Total en USD</label>
          <div class="amount" style="color: var(--color-primary);">$${parseFloat(doc.totalAmountUSD).toFixed(2)}</div>
          <div class="subtext">Monto total de venta</div>
        </div>
        <div class="doc-summary-box highlight-gold">
          <label>Total en Bolívares</label>
          <div class="amount" style="font-size: 1.05rem; color: #92400e;">${doc.totalAmountBs ? `Bs. ${formatBs(doc.totalAmountBs)}` : 'Según Tasa BCV'}</div>
          <div class="subtext">${rateNote}</div>
        </div>
        <div class="doc-summary-box highlight-green">
          <label>Inicial Pagada</label>
          <div class="amount" style="color: #15803d;">${downpaymentDisplay}</div>
          ${downpaymentBsDetail || `<div class="subtext">${doc.data.downpaymentPercent}% del total</div>`}
        </div>
        <div class="doc-summary-box">
          <label>Saldo Pendiente</label>
          <div class="amount" style="color: #dc2626;">$${parseFloat(doc.data.remainingBalance).toFixed(2)}</div>
          <div class="subtext">${installments.length} cuotas pactadas</div>
        </div>
      </div>

      <!-- Plan de Cuotas -->
      <div class="doc-section-title">
        <svg fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" style="width:18px;height:18px;">
          <path stroke-linecap="round" stroke-linejoin="round" d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
        </svg>
        <span>PLAN DE CUOTAS</span>
      </div>

      <div class="doc-plan-summary-grid">
        <div class="doc-plan-stat-box highlight-green">
          <span class="plan-stat-lbl">Cuota inicial pagada</span>
          <span class="plan-stat-val text-green">$${downpaymentPaidVal} USD</span>
        </div>
        <div class="doc-plan-stat-box">
          <span class="plan-stat-lbl">Total de cuotas</span>
          <span class="plan-stat-val">${totalInstallmentsCount}</span>
        </div>
        <div class="doc-plan-stat-box highlight-primary">
          <span class="plan-stat-lbl">Cuotas pagadas</span>
          <span class="plan-stat-val text-primary">${paidInstallmentsCount}</span>
        </div>
        <div class="doc-plan-stat-box highlight-red">
          <span class="plan-stat-lbl">Cuotas pendientes</span>
          <span class="plan-stat-val text-red">${pendingInstallmentsCount}</span>
        </div>
      </div>

      <table class="doc-table">
        <thead>
          <tr>
            <th style="text-align: center; width: 60px;">N°</th>
            <th>Fecha de Vencimiento</th>
            <th style="text-align: right; width: 140px;">Monto USD</th>
            <th style="text-align: center; width: 160px;">Estado</th>
          </tr>
        </thead>
        <tbody>
          ${installmentsRows || '<tr><td colspan="4" style="text-align:center;color:#94a3b8;">Sin cuotas programadas</td></tr>'}
        </tbody>
      </table>

      <!-- Cláusula al pie de la factura, al lado del QR -->
      <div class="doc-contract-clause-container">
        <div class="doc-clause-qr-col">
          <img src="assets/qr-contrato.png" alt="QR Contrato HogarFlex" class="doc-clause-qr-img" id="invoice-qr-contrato-img" width="80" height="80">
        </div>
        <div class="doc-clause-text-col">
          <p class="doc-clause-text">Al recibir esta nota de entrega / factura, usted acepta los términos y condiciones del contrato de financiamiento. En caso de fallar en el pago de alguna de las cuotas acordadas, se pondrá en ejercicio dicho contrato.</p>
        </div>
      </div>

      <!-- Firmas y Compromiso -->
      <div class="doc-signatures">
        <div class="doc-sign-line">
          <hr>
          <div class="doc-sign-label">HOGARFLEX NOELUIS<br><small>Firma y Sello Comercial</small></div>
        </div>
        <div class="doc-sign-line">
          <hr>
          <div class="doc-sign-label">${escapeHtml(doc.client.name)}<br><small>Conforme / Firma del Cliente</small></div>
        </div>
      </div>

      <div class="doc-footer-box">
        <div>
          <strong>Condición de financiamiento:</strong> El cliente se compromete a cancelar las cuotas según el calendario estipulado.
        </div>
        <div style="text-align: right; white-space: nowrap;">
          ¡Gracias por su preferencia!
        </div>
      </div>
    `;
  } else {
    // ---------------- RECIBO DE PAGO ----------------
    const rateNote = doc.rateBCV
      ? `(Tasa BCV del día: Bs. ${parseFloat(doc.rateBCV).toFixed(2)}/$)`
      : "";

    const bsDisplay = doc.totalAmountBs > 0
      ? `Bs. ${formatBs(doc.totalAmountBs)} <small style="color:#64748b;display:block;">${rateNote}</small>`
      : "—";

    const conceptText = doc.data.paymentType === "cuota"
      ? `Cancelación de Cuota #${doc.data.installmentNumber || ''}`
      : "Abono Libre a Capital (reducción cuota a cuota)";

    const currencyText = doc.data.currency === "BS" ? "Bolívares (Bs.)" : "Divisas ($ USD)";

    return `
      <!-- Encabezado de Recibo -->
      <div class="doc-top-bar">
        <div>
          <h1 class="doc-brand-title">HOGARFLEX NOELUIS</h1>
          <p class="doc-brand-subtitle">Comprobante Oficial de Recaudación y Cobranzas</p>
        </div>
        <div class="doc-number-box">
          <span class="doc-type-badge" style="background:#0f766e;">RECIBO DE PAGO</span>
          <div class="doc-number-text">${escapeHtml(doc.docNumber)}</div>
          <div class="doc-date-text">Fecha de pago: <strong>${dateStr}${timeStr}</strong></div>
        </div>
      </div>

      <!-- Datos del Cliente -->
      <div class="doc-meta-card">
        <div class="doc-meta-item">
          <label>Cliente</label>
          <div class="val">${escapeHtml(doc.client.name)}</div>
        </div>
        <div class="doc-meta-item">
          <label>Cédula de Identidad</label>
          <div class="val">${escapeHtml(doc.client.dni)}</div>
        </div>
        <div class="doc-meta-item">
          <label>Teléfono</label>
          <div class="val">${escapeHtml(doc.client.phone || "No registrado")}</div>
        </div>
      </div>

      <!-- Detalle del Pago Realizado -->
      <div class="doc-section-title">
        <svg fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" style="width:18px;height:18px;">
          <path stroke-linecap="round" stroke-linejoin="round" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
        <span>Detalle del Pago Recibido</span>
      </div>

      <div style="background: #ffffff; border: 2px solid #0f766e; border-radius: 10px; padding: 20px; margin-bottom: 20px;">
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px;">
          <div>
            <div style="font-size: 0.78rem; text-transform: uppercase; color: #64748b; font-weight: 700; margin-bottom: 2px;">Tipo de Pago</div>
            <div style="font-size: 1.05rem; font-weight: 800; color: #0f172a;">${escapeHtml(conceptText)}</div>
            <div style="font-size: 0.8rem; color: #0f766e; font-weight: 600; margin-top: 2px;">${currencyText}</div>
          </div>

          <div>
            <div style="font-size: 0.78rem; text-transform: uppercase; color: #64748b; font-weight: 700; margin-bottom: 2px;">Monto Pagado en USD</div>
            <div style="font-size: 1.4rem; font-weight: 800; color: #15803d;">$${parseFloat(doc.totalAmountUSD).toFixed(2)} USD</div>
          </div>

          <div>
            <div style="font-size: 0.78rem; text-transform: uppercase; color: #64748b; font-weight: 700; margin-bottom: 2px;">Monto Pagado en Bs.</div>
            <div style="font-size: 1.15rem; font-weight: 800; color: #0f172a;">${bsDisplay}</div>
          </div>

          <div>
            <div style="font-size: 0.78rem; text-transform: uppercase; color: #64748b; font-weight: 700; margin-bottom: 2px;">Nº de Referencia</div>
            <div style="font-size: 1rem; font-weight: 700; color: #0369a1;">
              ${doc.data.referenceNumber ? `<code>#${escapeHtml(doc.data.referenceNumber)}</code>` : '<span style="color:#64748b;">Efectivo / Sin referencia</span>'}
            </div>
          </div>
        </div>
      </div>

      <!-- Estado de Cuenta Posterior -->
      <div class="doc-section-title">
        <svg fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" style="width:18px;height:18px;">
          <path stroke-linecap="round" stroke-linejoin="round" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
        <span>Balance y Cuotas Pendientes</span>
      </div>

      <div class="doc-summary-grid">
        <div class="doc-summary-box highlight-primary">
          <label>Saldo Restante</label>
          <div class="amount" style="color: var(--color-primary); font-size: 1.3rem;">$${parseFloat(doc.data.remainingBalanceAfter).toFixed(2)} USD</div>
          <div class="subtext">Saldo del crédito tras este pago</div>
        </div>

        <div class="doc-summary-box highlight-gold">
          <label>Cuotas por Pagar</label>
          <div class="amount" style="color: #b45309; font-size: 1.3rem;">${doc.data.pendingInstallmentsCount} cuotas</div>
          <div class="subtext">
            ${doc.data.pendingInstallmentsCount === 0 ? "¡Crédito totalmente saldado!" : "Pendientes de vencimiento"}
          </div>
        </div>
      </div>

      <div class="doc-signatures" style="margin-top: 28px;">
        <div class="doc-sign-line">
          <hr>
          <div class="doc-sign-label">HOGARFLEX NOELUIS<br><small>Receptor / Cobranzas</small></div>
        </div>
      </div>

      <div class="doc-footer-box">
        <div>
          Este recibo certifica que el pago indicado ha sido abonado a la cuenta del crédito correspondiente.
        </div>
        <div style="text-align: right; white-space: nowrap;">
          ¡Gracias por su puntualidad!
        </div>
      </div>
    `;
  }
}

// Compartir resumen del documento vía WhatsApp
function shareDocViaWhatsApp(doc) {
  if (!doc) return;

  const clientPhone = formatPhoneForWhatsApp(doc.client ? doc.client.phone : "");
  const dateObj = new Date(doc.date || Date.now());
  const dateStr = formatDateDisplay(dateObj);
  const timeStr = (!isNaN(dateObj.getTime()) && String(doc.date).includes("T"))
    ? " " + dateObj.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
    : "";

  let message = "";

  if (doc.type === "factura_credito") {
    const items = (doc.data && Array.isArray(doc.data.items)) ? doc.data.items : [];
    const itemsList = items.map((it) => {
      const qty = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
      const price = parseFloat(it.precioUnitario !== undefined ? it.precioUnitario : (it.price !== undefined ? it.price : it.priceUSD)) || 0;
      const sub = parseFloat(it.totalLinea !== undefined ? it.totalLinea : it.subtotal) || (price * qty);
      const name = it.nombre || it.name || "Producto";
      return `• ${name} (x${qty}) - $${sub.toFixed(2)} USD ($${price.toFixed(2)} c/u)`;
    }).join("\n");
    const shippingLine = doc.data.hasShipping && doc.data.shippingAmount > 0 ? `\n🚚 *Flete:* $${parseFloat(doc.data.shippingAmount).toFixed(2)} USD` : "";
    const bsTotalLine = doc.totalAmountBs ? `\n🇻🇪 *Total Bs:* Bs. ${formatBs(doc.totalAmountBs)}` + (doc.rateBCV ? ` (Tasa: ${parseFloat(doc.rateBCV).toFixed(2)} Bs/$)` : "") : "";
    const downpaymentStr = doc.data.downpaymentAmount > 0 ? `$${parseFloat(doc.data.downpaymentAmount).toFixed(2)} USD` : "$0.00";

    const installments = doc.data.installments || [];
    const installmentsList = installments.map((inst) => {
      const dStr = inst.dueDate ? formatDateDisplay(new Date(inst.dueDate + "T00:00:00")) : "-";
      const bsVal = inst.amountBs ? ` (Bs. ${formatBs(inst.amountBs)})` : (doc.rateBCV ? ` (Bs. ${formatBs(inst.amountUSD * doc.rateBCV)})` : "");
      return `- Cuota ${inst.number}: ${dStr} -> $${parseFloat(inst.amountUSD).toFixed(2)} USD${bsVal} [${inst.status || "Pendiente"}]`;
    }).join("\n");

    message = `*HOGARFLEX NOELUIS* 📄\n*Factura de Crédito:* ${doc.docNumber}\n📅 *Fecha:* ${dateStr}\n\n👤 *Cliente:* ${doc.client.name} (C.I. ${doc.client.dni})\n📞 *Teléfono:* ${doc.client.phone || '-'}\n📍 *Dirección:* ${doc.client.address || '-'}\n\n🛍️ *Detalle de Compra:*\n${itemsList}${shippingLine}\n\n💰 *Total de Compra:* $${parseFloat(doc.totalAmountUSD).toFixed(2)} USD${bsTotalLine}\n💵 *Inicial Pagada:* ${downpaymentStr}\n📌 *Saldo Pendiente:* $${parseFloat(doc.data.remainingBalance).toFixed(2)} USD\n\n🗓️ *Plan de Cuotas:*\n${installmentsList}\n\n¡Muchas gracias por su preferencia! ✨\n*HOGARFLEX NOELUIS*`;
  } else {
    const conceptStr = doc.data.paymentType === "cuota"
      ? `Cuota #${doc.data.installmentNumber || ''}`
      : "Abono libre a capital";

    const bsPart = doc.totalAmountBs > 0
      ? `\n🇻🇪 *Monto en Bs:* Bs. ${formatBs(doc.totalAmountBs)}` + (doc.rateBCV ? ` (Tasa BCV: ${parseFloat(doc.rateBCV).toFixed(2)} Bs/$)` : "")
      : "";

    const refPart = doc.data.referenceNumber ? `\n📲 *Nº de Referencia:* #${doc.data.referenceNumber}` : "";

    message = `*HOGARFLEX NOELUIS* 🧾\n*Recibo Oficial de Pago:* ${doc.docNumber}\n📅 *Fecha de Pago:* ${dateStr}${timeStr}\n\n👤 *Cliente:* ${doc.client.name} (C.I. ${doc.client.dni})\n📞 *Teléfono:* ${doc.client.phone || '-'}\n\n📝 *Concepto:* ${conceptStr}\n💵 *Monto Pagado:* $${parseFloat(doc.totalAmountUSD).toFixed(2)} USD${bsPart}${refPart}\n💳 *Saldo Restante:* $${parseFloat(doc.data.remainingBalanceAfter).toFixed(2)} USD\n⏳ *Cuotas Pendientes:* ${doc.data.pendingInstallmentsCount} cuotas\n\n¡Muchas gracias por su puntualidad! ✨\n*HOGARFLEX NOELUIS*`;
  }

  const url = clientPhone
    ? `https://wa.me/${clientPhone}?text=${encodeURIComponent(message)}`
    : `https://wa.me/?text=${encodeURIComponent(message)}`;

  window.open(url, "_blank");
}

// Descargar documento PDF usando jsPDF
function printInvoiceDoc() {
  const cur = currentPreviewDoc;
  if (!cur) {
    alert("No hay ningún comprobante seleccionado.");
    return;
  }

  if (!window.jspdf || !window.jspdf.jsPDF) {
    alert('Error: la librería PDF no está disponible. Recarga la página e intenta de nuevo.');
    return;
  }

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'mm', format: 'letter' });
  const pageW = 215.9;
  const pageH = 279.4;
  const margin = 15;
  let y = 0;

  const invoiceDateStr = cur.date ? formatDateDisplay(new Date(cur.date)) : new Date().toLocaleDateString('es-VE');

  const invoice = {
    invoiceNumber: cur.docNumber || 'FAC-0001',
    date: invoiceDateStr,
    clientName: (cur.client && cur.client.name) ? cur.client.name : '',
    clientCI: (cur.client && cur.client.dni) ? cur.client.dni : '',
    clientPhone: (cur.client && cur.client.phone) ? cur.client.phone : '',
    clientAddress: (cur.client && cur.client.address) ? cur.client.address : '',
    items: cur.type === "recibo_pago"
      ? [{
          name: cur.data?.description || (cur.data?.paymentType === "cuota" ? `Pago Cuota #${cur.data?.installmentNumber || ''}` : "Abono libre a capital"),
          nombre: cur.data?.description || (cur.data?.paymentType === "cuota" ? `Pago Cuota #${cur.data?.installmentNumber || ''}` : "Abono libre a capital"),
          qty: 1,
          cantidad: 1,
          price: parseFloat(cur.totalAmountUSD) || 0,
          precioUnitario: parseFloat(cur.totalAmountUSD) || 0,
          subtotal: parseFloat(cur.totalAmountUSD) || 0,
          totalLinea: parseFloat(cur.totalAmountUSD) || 0
        }]
      : (cur.data?.items || []).map((it) => {
          const qty = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
          let price = parseFloat(
            it.precioUnitario !== undefined ? it.precioUnitario :
            (it.price !== undefined ? it.price :
            (it.priceUSD !== undefined ? it.priceUSD :
            it.unitPrice))
          ) || 0;
          let lineTotal = parseFloat(it.totalLinea !== undefined ? it.totalLinea : it.subtotal) || parseFloat((qty * price).toFixed(2));
          if (price <= 0 && lineTotal > 0 && qty > 0) {
            price = parseFloat((lineTotal / qty).toFixed(2));
          } else if (price <= 0 && cur.totalAmountUSD && cur.data?.items?.length > 0) {
            price = parseFloat((parseFloat(cur.totalAmountUSD) / cur.data.items.length / qty).toFixed(2));
            lineTotal = parseFloat((qty * price).toFixed(2));
          }
          const itemName = it.nombre || it.name || "Producto";
          return {
            name: itemName,
            nombre: itemName,
            qty: qty,
            cantidad: qty,
            price: price,
            precioUnitario: price,
            totalLinea: lineTotal,
            subtotal: lineTotal
          };
        }),
    shipping: (cur.data?.hasShipping && cur.data?.shippingAmount > 0) ? parseFloat(cur.data.shippingAmount) : 0,
    totalUSD: parseFloat(cur.totalAmountUSD) || 0,
    bcvRate: parseFloat(cur.rateBCV) || 0,
    downPayment: parseFloat(cur.data?.downpaymentPaidUSD !== undefined && cur.data?.downpaymentPaidUSD > 0 ? cur.data.downpaymentPaidUSD : (cur.data?.downpaymentAmount || 0)) || 0,
    balance: parseFloat(cur.data?.remainingBalance !== undefined ? cur.data.remainingBalance : cur.data?.remainingBalanceAfter) || 0,
    installments: (cur.data?.installments || []).map((inst, idx) => ({
      number: inst.number !== undefined ? inst.number : (idx + 1),
      dueDate: inst.dueDate ? formatDateDisplay(new Date(inst.dueDate + "T00:00:00")) : '',
      amountUSD: parseFloat(inst.amountUSD) || 0,
      status: inst.status || 'Pendiente'
    }))
  };

  // ENCABEZADO — rectángulo navy
  doc.setFillColor(26, 58, 107); // #1a3a6b
  doc.rect(0, 0, pageW, 40, 'F');

  // LOGO — si existe como base64 o elemento imagen
  const headerLogoEl = document.querySelector('.header-logo') || document.querySelector('.login-logo');
  if (typeof LOGO_BASE64 !== 'undefined' && LOGO_BASE64) {
    try {
      const imgFormat = LOGO_BASE64.includes('image/png') ? 'PNG' : 'JPEG';
      doc.addImage(LOGO_BASE64, imgFormat, 10, 5, 25, 25);
    } catch (err) {
      console.warn("No se pudo cargar el logo en el PDF:", err);
    }
  } else if (headerLogoEl && headerLogoEl.complete && headerLogoEl.naturalWidth > 0) {
    try {
      doc.addImage(headerLogoEl, 'JPEG', 10, 5, 25, 25);
    } catch (err) {
      console.warn("No se pudo cargar headerLogoEl en el PDF:", err);
    }
  }

  // Texto del encabezado en blanco
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(18);
  doc.setFont('helvetica', 'bold');
  doc.text('HOGARFLEX NOELUIS', pageW / 2, 14, { align: 'center' });
  doc.setFontSize(11);
  doc.setFont('helvetica', 'normal');
  const docSubtitle = cur.type === 'recibo_pago' ? 'RECIBO OFICIAL DE PAGO' : 'NOTA DE ENTREGA / FACTURA DE CRÉDITO';
  doc.text(docSubtitle, pageW / 2, 22, { align: 'center' });
  doc.setFontSize(9);
  doc.text('0424.215.58.05    |    0412.048.11.57', pageW / 2, 29, { align: 'center' });

  // Número de factura y fecha en blanco (esquina derecha)
  doc.text('N°: ' + (invoice.invoiceNumber || 'FAC-0001'), pageW - margin, 16, { align: 'right' });
  doc.text('Fecha: ' + (invoice.date || new Date().toLocaleDateString('es-VE')), pageW - margin, 22, { align: 'right' });

  // Línea dorada bajo encabezado
  doc.setDrawColor(245, 196, 0); // #f5c400
  doc.setLineWidth(1.5);
  doc.line(0, 40, pageW, 40);

  y = 50;

  // DATOS DEL CLIENTE
  doc.setTextColor(26, 58, 107);
  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  doc.text('DATOS DEL CLIENTE', margin, y);
  y += 5;
  doc.setDrawColor(200, 200, 200);
  doc.setLineWidth(0.3);
  doc.line(margin, y, pageW - margin, y);
  y += 6;
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(0, 0, 0);
  doc.text('Cliente: ' + (invoice.clientName || ''), margin, y);
  y += 6;
  doc.text('C.I.: ' + (invoice.clientCI || '') + '    Teléfono: ' + (invoice.clientPhone || ''), margin, y);
  y += 6;
  doc.text('Dirección: ' + (invoice.clientAddress || ''), margin, y);
  y += 10;

  // TABLA DE PRODUCTOS
  doc.setFillColor(26, 58, 107);
  doc.rect(margin, y, pageW - margin * 2, 8, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.text('CANT.', margin + 2, y + 5.5);
  doc.text('DESCRIPCIÓN', margin + 20, y + 5.5);
  doc.text('P. UNIT. USD', margin + 110, y + 5.5);
  doc.text('TOTAL USD', margin + 145, y + 5.5);
  y += 8;
  doc.setTextColor(0, 0, 0);
  doc.setFont('helvetica', 'normal');

  // Iterar productos del invoice leyendo directamente del objeto factura
  (invoice.items || []).forEach((item, i) => {
    if (i % 2 === 0) { doc.setFillColor(245, 245, 245); doc.rect(margin, y, pageW - margin * 2, 7, 'F'); }
    const iQty = item.cantidad !== undefined ? item.cantidad : (item.qty || 1);
    const iPrice = item.precioUnitario !== undefined ? item.precioUnitario : (item.price || 0);
    const iTotal = item.totalLinea !== undefined ? item.totalLinea : ((item.subtotal !== undefined) ? item.subtotal : (iQty * iPrice));
    const iName = item.nombre || item.name || '';

    doc.text(String(iQty), margin + 2, y + 5);
    doc.text(String(iName), margin + 20, y + 5);
    doc.text('$' + iPrice.toFixed(2), margin + 110, y + 5);
    doc.text('$' + iTotal.toFixed(2), margin + 145, y + 5);
    y += 7;
  });

  // Flete si aplica
  if (invoice.shipping && invoice.shipping > 0) {
    doc.text('1', margin + 2, y + 5);
    doc.text('Flete / Envío', margin + 20, y + 5);
    doc.text('$' + invoice.shipping.toFixed(2), margin + 110, y + 5);
    doc.text('$' + invoice.shipping.toFixed(2), margin + 145, y + 5);
    y += 7;
  }
  y += 5;

  // TOTALES
  doc.setDrawColor(245, 196, 0);
  doc.setLineWidth(0.8);
  doc.line(margin, y, pageW - margin, y);
  y += 6;
  doc.setFont('helvetica', 'bold');
  doc.text('TOTAL: $' + (invoice.totalUSD || 0).toFixed(2) + ' USD', pageW - margin, y, { align: 'right' });
  y += 6;
  if (invoice.bcvRate && invoice.bcvRate > 0) {
    doc.setFont('helvetica', 'normal');
    doc.text('Tasa BCV: ' + invoice.bcvRate + ' Bs/$', pageW - margin, y, { align: 'right' });
    y += 6;
    doc.text('Equivalente: Bs. ' + ((invoice.totalUSD || 0) * invoice.bcvRate).toLocaleString('es-VE', {minimumFractionDigits: 2}), pageW - margin, y, { align: 'right' });
    y += 6;
  }
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(26, 58, 107);
  doc.text('Cuota Inicial Pagada: $' + (invoice.downPayment || 0).toFixed(2) + ' USD', margin, y);
  y += 6;
  doc.setTextColor(180, 0, 0);
  doc.text('Saldo Pendiente: $' + (invoice.balance || 0).toFixed(2) + ' USD', margin, y);
  y += 10;

  // PLAN DE CUOTAS
  if (invoice.installments && invoice.installments.length > 0) {
    if (y + 45 > pageH - 30) {
      doc.addPage();
      y = 20;
    }

    doc.setTextColor(26, 58, 107);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.text('PLAN DE CUOTAS', margin, y);
    y += 5;

    // Resumen de cuotas encima de la tabla
    const totalInst = invoice.installments.length;
    const paidInst = invoice.installments.filter((i) => i.status === 'Pagada').length;
    const pendingInst = invoice.installments.filter((i) => i.status !== 'Pagada').length;
    const downPaymentFormatted = (invoice.downPayment || 0).toFixed(2);

    doc.setFillColor(248, 250, 252);
    doc.setDrawColor(203, 213, 225);
    doc.setLineWidth(0.3);
    doc.roundedRect(margin, y, pageW - margin * 2, 8, 1.5, 1.5, 'FD');

    const statColW = (pageW - margin * 2) / 4;
    doc.setFontSize(7.5);

    // Cuota inicial pagada
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(71, 85, 105);
    doc.text('Inicial pagada:', margin + 3, y + 5.2);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(21, 128, 61);
    doc.text('$' + downPaymentFormatted + ' USD', margin + 22, y + 5.2);

    // Total de cuotas
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(71, 85, 105);
    doc.text('Total cuotas:', margin + statColW + 2, y + 5.2);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(15, 23, 42);
    doc.text(String(totalInst), margin + statColW + 20, y + 5.2);

    // Cuotas pagadas
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(71, 85, 105);
    doc.text('Cuotas pagadas:', margin + statColW * 2 + 2, y + 5.2);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(26, 58, 107);
    doc.text(String(paidInst), margin + statColW * 2 + 24, y + 5.2);

    // Cuotas pendientes
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(71, 85, 105);
    doc.text('Cuotas pendientes:', margin + statColW * 3 + 2, y + 5.2);
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(180, 0, 0);
    doc.text(String(pendingInst), margin + statColW * 3 + 28, y + 5.2);

    y += 11;

    // Tabla de cuotas
    doc.setFillColor(26, 58, 107);
    doc.rect(margin, y, pageW - margin * 2, 7, 'F');
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(8.5);
    doc.setFont('helvetica', 'bold');
    doc.text('N°', margin + 3, y + 5);
    doc.text('Fecha de Vencimiento', margin + 20, y + 5);
    doc.text('Monto USD', margin + 105, y + 5);
    doc.text('Estado', margin + 148, y + 5);
    y += 7;

    doc.setTextColor(0, 0, 0);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    invoice.installments.forEach((inst, i) => {
      if (y > pageH - 60) {
        doc.addPage();
        y = 20;
      }
      if (i % 2 === 0) {
        doc.setFillColor(245, 245, 245);
        doc.rect(margin, y, pageW - margin * 2, 6.5, 'F');
      }
      doc.text(String(inst.number || (i + 1)), margin + 3, y + 4.5);
      doc.text(inst.dueDate || '', margin + 20, y + 4.5);
      doc.text('$' + (inst.amountUSD || 0).toFixed(2) + ' USD', margin + 105, y + 4.5);

      const st = inst.status || 'Pendiente';
      if (st === 'Pagada') {
        doc.setTextColor(21, 128, 61);
        doc.setFont('helvetica', 'bold');
      } else if (st === 'Parcialmente pagada') {
        doc.setTextColor(180, 83, 9);
        doc.setFont('helvetica', 'bold');
      } else {
        doc.setTextColor(3, 105, 161);
        doc.setFont('helvetica', 'normal');
      }
      doc.text(st, margin + 148, y + 4.5);
      doc.setTextColor(0, 0, 0);
      doc.setFont('helvetica', 'normal');
      y += 6.5;
    });
    y += 6;
  }

  // CLÁUSULA AL PIE CON QR (Antes de firmas)
  if (cur.type !== 'recibo_pago') {
    if (y + 55 > pageH - 20) {
      doc.addPage();
      y = 20;
    }

    const clauseBoxY = y;
    const clauseBoxH = 26;
    const clauseBoxW = pageW - margin * 2;

    doc.setFillColor(248, 250, 252);
    doc.setDrawColor(203, 213, 225);
    doc.setLineWidth(0.4);
    doc.roundedRect(margin, clauseBoxY, clauseBoxW, clauseBoxH, 1.5, 1.5, 'FD');

    // Acento azul en borde izquierdo
    doc.setFillColor(26, 58, 107);
    doc.rect(margin, clauseBoxY, 1.5, clauseBoxH, 'F');

    // Columna izquierda: QR (aprox. 80x80px -> 21x21 mm)
    const qrSize = 21;
    const qrX = margin + 3.5;
    const qrY = clauseBoxY + (clauseBoxH - qrSize) / 2;

    doc.setFillColor(255, 255, 255);
    doc.rect(qrX - 0.5, qrY - 0.5, qrSize + 1, qrSize + 1, 'F');

    const qrImgEl = document.querySelector('.doc-clause-qr-img') || document.getElementById('invoice-qr-contrato-img');
    let qrRendered = false;
    if (qrImgEl && qrImgEl.complete && qrImgEl.naturalWidth > 0) {
      try {
        doc.addImage(qrImgEl, 'PNG', qrX, qrY, qrSize, qrSize);
        qrRendered = true;
      } catch (err) {
        console.warn("Error dibujando qrImgEl en PDF:", err);
      }
    }
    if (!qrRendered && typeof QR_CONTRATO_BASE64 !== 'undefined' && QR_CONTRATO_BASE64) {
      try {
        doc.addImage(QR_CONTRATO_BASE64, 'PNG', qrX, qrY, qrSize, qrSize);
        qrRendered = true;
      } catch (err) {
        console.warn("Error dibujando QR_CONTRATO_BASE64 en PDF:", err);
      }
    }

    // Columna derecha: Texto de la cláusula
    const textX = qrX + qrSize + 5;
    const textW = (margin + clauseBoxW) - textX - 4;
    doc.setFontSize(8);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(30, 41, 59);

    const clauseText = "Al recibir esta nota de entrega / factura, usted acepta los términos y condiciones del contrato de financiamiento. En caso de fallar en el pago de alguna de las cuotas acordadas, se pondrá en ejercicio dicho contrato.";
    const splitClause = doc.splitTextToSize(clauseText, textW);
    doc.text(splitClause, textX, clauseBoxY + 7);

    y = clauseBoxY + clauseBoxH + 4;
  }

  // FIRMAS
  if (y + 30 > pageH - 15) {
    doc.addPage();
    y = 20;
  }
  doc.setDrawColor(100, 100, 100);
  doc.setLineWidth(0.4);
  doc.line(margin, y + 12, margin + 70, y + 12);
  doc.line(pageW - margin - 70, y + 12, pageW - margin, y + 12);
  doc.setFontSize(9);
  doc.setTextColor(0, 0, 0);
  doc.text('HOGARFLEX NOELUIS', margin + 35, y + 17, { align: 'center' });
  doc.text('Firma y Sello Comercial', margin + 35, y + 22, { align: 'center' });
  doc.text((invoice.clientName || 'Cliente'), pageW - margin - 35, y + 17, { align: 'center' });
  doc.text('Conforme / Firma del Cliente', pageW - margin - 35, y + 22, { align: 'center' });

  // PIE — línea dorada (ajustada al alto de hoja carta 279.4mm)
  const footerLineY = pageH - 10;
  doc.setDrawColor(245, 196, 0);
  doc.setLineWidth(2);
  doc.line(0, footerLineY, pageW, footerLineY);
  doc.setFontSize(8);
  doc.setTextColor(100, 100, 100);
  doc.text('Condición de financiamiento: El cliente se compromete a cancelar las cuotas en las fechas acordadas.', pageW / 2, footerLineY + 5, { align: 'center' });

  // Forzar descarga con extensión .pdf correcta usando <a> element:
  const blob = doc.output('blob');
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'Factura_HOGARFLEX_' + (invoice.invoiceNumber || 'FAC') + '.pdf';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}


// Renderizar la sección completa de Facturación
function renderFacturacionSection() {
  const tbody = document.getElementById("invoices-tbody");
  const emptyMsg = document.getElementById("empty-invoices-msg");
  const table = document.getElementById("invoices-table");
  if (!tbody || !emptyMsg || !table) return;

  const invoices = getStoredInvoices();

  // Actualizar métricas KPI superiores
  const totalDocsEl = document.getElementById("kpi-inv-total-docs");
  const breakdownEl = document.getElementById("kpi-inv-docs-breakdown");
  const creditAmountEl = document.getElementById("kpi-inv-total-credit-amount");
  const receiptsAmountEl = document.getElementById("kpi-inv-total-receipts-amount");

  const totalFacturas = invoices.filter((d) => d.type === "factura_credito");
  const totalRecibos = invoices.filter((d) => d.type === "recibo_pago");

  const sumCreditUSD = totalFacturas.reduce((acc, d) => acc + (parseFloat(d.totalAmountUSD) || 0), 0);
  const sumReceiptsUSD = totalRecibos.reduce((acc, d) => acc + (parseFloat(d.totalAmountUSD) || 0), 0);

  if (totalDocsEl) totalDocsEl.textContent = invoices.length;
  if (breakdownEl) breakdownEl.textContent = `${totalFacturas.length} Facturas · ${totalRecibos.length} Recibos`;
  if (creditAmountEl) creditAmountEl.textContent = `$${sumCreditUSD.toFixed(2)}`;
  if (receiptsAmountEl) receiptsAmountEl.textContent = `$${sumReceiptsUSD.toFixed(2)}`;

  // Ordenar por fecha cronológicamente (más reciente primero)
  invoices.sort((a, b) => new Date(b.date || b.createdAt || 0).getTime() - new Date(a.date || a.createdAt || 0).getTime());

  // Filtrar según búsqueda y tipo
  const filtered = invoices.filter((doc) => {
    // Filtro por tipo
    if (currentInvoicesTypeFilter !== "all" && doc.type !== currentInvoicesTypeFilter) {
      return false;
    }

    // Filtro de búsqueda
    if (currentInvoicesSearchQuery) {
      const clientName = (doc.client && doc.client.name ? doc.client.name : "").toLowerCase();
      const clientDni = (doc.client && doc.client.dni ? doc.client.dni : "").toLowerCase();
      const docNum = (doc.docNumber || "").toLowerCase();
      if (!clientName.includes(currentInvoicesSearchQuery) && !clientDni.includes(currentInvoicesSearchQuery) && !docNum.includes(currentInvoicesSearchQuery)) {
        return false;
      }
    }

    return true;
  });

  if (filtered.length === 0) {
    tbody.innerHTML = "";
    table.classList.add("hidden");
    emptyMsg.classList.remove("hidden");
    return;
  }

  emptyMsg.classList.add("hidden");
  table.classList.remove("hidden");

  tbody.innerHTML = filtered.map((doc) => {
    const dateObj = new Date(doc.date || doc.createdAt || Date.now());
    const dateStr = formatDateDisplay(dateObj);
    const timeStr = (!isNaN(dateObj.getTime()) && String(doc.date).includes("T"))
      ? dateObj.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })
      : "";

    const typeBadge = doc.type === "factura_credito"
      ? '<span class="badge-factura">📄 Factura crédito</span>'
      : '<span class="badge-recibo">🧾 Recibo pago</span>';

    const bsStr = doc.totalAmountBs && doc.totalAmountBs > 0
      ? `<br><small style="color: #64748b;">(Bs. ${formatBs(doc.totalAmountBs)})</small>`
      : "";

    return `
      <tr>
        <td>
          <strong>${dateStr}</strong>
          ${timeStr ? `<small style="color: var(--color-text-muted); display: block;">${timeStr}</small>` : ''}
        </td>
        <td>
          <code style="font-weight: 700; font-size: 0.92rem; color: var(--color-primary);">${escapeHtml(doc.docNumber)}</code>
        </td>
        <td>
          <strong>${escapeHtml(doc.client.name)}</strong><br>
          <small style="color: var(--color-text-muted);">C.I. ${escapeHtml(doc.client.dni)} · ${escapeHtml(doc.client.phone || '-')}</small>
        </td>
        <td>
          ${typeBadge}
        </td>
        <td>
          <strong style="font-size: 0.95rem; color: #1e293b;">$${parseFloat(doc.totalAmountUSD).toFixed(2)} USD</strong>
          ${bsStr}
        </td>
        <td style="text-align: right;">
          <div style="display: flex; gap: 6px; justify-content: flex-end; flex-wrap: wrap;">
            <button type="button" class="btn-action-view btn-action-view-inv" data-id="${doc.id}" title="Ver documento">👁️ Ver</button>
            <button type="button" class="btn-action-receipt btn-action-wa-inv" data-id="${doc.id}" style="background: #25d366;" title="Compartir por WhatsApp">📲 WhatsApp</button>
          </div>
        </td>
      </tr>
    `;
  }).join("");
}

