// ============================================================
// FASE 11: MÓDULO DE RESPALDO (BACKUP GOOGLE DRIVE & SHEETS)
// ============================================================

// Variables de respaldo inicializadas arriba

// Inicializar módulo de Respaldo
function initBackupModule() {
  const btnExportSheets = document.getElementById("btn-export-sheets");
  const btnImportSheets = document.getElementById("btn-import-sheets");
  const btnCloudSaveHeader = document.getElementById("btn-cloud-save-header");
  const btnCloudReloadHeader = document.getElementById("btn-cloud-reload-header");
  const btnRetrySheets = document.getElementById("btn-retry-sheets");
  const btnExportReceipts = document.getElementById("btn-export-receipts");
  const toggleAutoBackup = document.getElementById("toggle-auto-backup");
  const btnSaveUrl = document.getElementById("btn-save-apps-script-url");
  const btnTestUrl = document.getElementById("btn-test-apps-script-url");
  const inputUrl = document.getElementById("input-apps-script-url");

  if (inputUrl) {
    inputUrl.value = getAppsScriptUrl();
  }

  if (btnSaveUrl && inputUrl) {
    btnSaveUrl.addEventListener("click", () => {
      const val = inputUrl.value.trim();
      if (!val) {
        alert("Por favor ingresa una URL válida de Google Apps Script.");
        return;
      }
      setAppsScriptUrl(val);
      updateBackendStatusUI(true, "URL guardada exitosamente");
      showCloudSyncToast("✅ URL de Apps Script guardada", "success");
    });
  }

  if (btnTestUrl && inputUrl) {
    btnTestUrl.addEventListener("click", async () => {
      const val = inputUrl.value.trim() || getAppsScriptUrl();
      if (!val) {
        alert("Ingresa una URL antes de probar.");
        return;
      }
      const feedback = document.getElementById("backend-url-feedback");
      if (feedback) {
        feedback.className = "";
        feedback.style.color = "#1d4ed8";
        feedback.textContent = "⏳ Conectando con Google Apps Script...";
        feedback.classList.remove("hidden");
      }
      try {
        const testUrl = val + (val.includes("?") ? "&" : "?") + "action=read";
        const res = await fetch(testUrl, { method: "GET" });
        const json = await res.json();
        const isSuccess = json && (json.status === "success" || json.success === true);
        if (isSuccess) {
          if (feedback) {
            feedback.style.color = "#15803d";
            feedback.textContent = "✅ Conexión exitosa con HogarFlex_DB en Google Apps Script!";
          }
          setAppsScriptUrl(val);
          updateBackendStatusUI(true);
        } else {
          throw new Error(json.message || json.error || "Respuesta no válida del Apps Script");
        }
      } catch (err) {
        if (feedback) {
          feedback.style.color = "#b91c1c";
          feedback.textContent = "❌ Error al conectar: " + err.message;
        }
      }
    });
  }

  if (btnExportSheets) {
    btnExportSheets.addEventListener("click", () => {
      exportToGoogleSheets();
    });
  }

  if (btnImportSheets) {
    btnImportSheets.addEventListener("click", () => {
      importFromGoogleSheets();
    });
  }

  if (btnCloudSaveHeader) {
    btnCloudSaveHeader.addEventListener("click", () => {
      exportToGoogleSheets();
    });
  }

  if (btnCloudReloadHeader) {
    btnCloudReloadHeader.addEventListener("click", () => {
      importFromGoogleSheets();
    });
  }

  if (btnRetrySheets) {
    btnRetrySheets.addEventListener("click", () => {
      exportToGoogleSheets();
    });
  }

  if (btnExportReceipts) {
    btnExportReceipts.addEventListener("click", () => {
      exportReceiptsToGoogleDrive();
    });
  }

  if (toggleAutoBackup) {
    toggleAutoBackup.checked = localStorage.getItem(BACKUP_AUTO_CLOSE_KEY) === "true";
    toggleAutoBackup.addEventListener("change", (e) => {
      localStorage.setItem(BACKUP_AUTO_CLOSE_KEY, e.target.checked ? "true" : "false");
    });
  }

  // Detectores de conectividad
  window.addEventListener("online", updateNetworkStatus);
  window.addEventListener("offline", updateNetworkStatus);

  // Respaldo automático al cerrar o recargar
  const handleAutoBackupBeforeUnload = () => {
    const isAutoEnabled = localStorage.getItem(BACKUP_AUTO_CLOSE_KEY) === "true";
    if (isAutoEnabled && navigator.onLine && getAppsScriptUrl()) {
      exportToGoogleSheets(true);
    }
  };

  window.addEventListener("beforeunload", handleAutoBackupBeforeUnload);
  window.addEventListener("pagehide", handleAutoBackupBeforeUnload);

  // Sincronización automática desde la nube al arrancar
  if (getAppsScriptUrl()) {
    updateBackendStatusUI(true);
    setTimeout(() => {
      importFromGoogleSheets(true);
    }, 600);
  }
}

// Actualizar bandera de conectividad
function updateNetworkStatus() {
  const banner = document.getElementById("backup-offline-banner");
  if (banner) {
    if (!navigator.onLine) {
      banner.classList.remove("hidden");
    } else {
      banner.classList.add("hidden");
    }
  }
}

// Renderizar sección de Respaldo al seleccionarla
function renderBackupSection() {
  updateNetworkStatus();

  // Actualizar UI del backend de Google Apps Script
  updateBackendStatusUI(!!getAppsScriptUrl());

  const inputUrl = document.getElementById("input-apps-script-url");
  if (inputUrl && !inputUrl.value) {
    inputUrl.value = getAppsScriptUrl();
  }

  // Actualizar fecha del último respaldo
  const lastSheetsBackup = localStorage.getItem(BACKUP_LAST_SHEETS_KEY);
  const lastSheetsEl = document.getElementById("sheets-last-backup-text");
  if (lastSheetsEl) {
    lastSheetsEl.textContent = lastSheetsBackup
      ? `Último respaldo: ${lastSheetsBackup}`
      : "Último respaldo: Nunca";
  }

  // Contar comprobantes y fotos de productos listos para subir a Drive
  const receiptsCountEl = document.getElementById("receipts-available-count-text");
  if (receiptsCountEl) {
    const credits = getStoredCredits();
    let totalReceipts = 0;
    credits.forEach((c) => {
      (c.payments || []).forEach((p) => {
        if (p.receiptUrl && p.receiptUrl.startsWith("data:image")) {
          totalReceipts++;
        }
      });
    });
    const products = getStoredProducts();
    let totalProdPhotos = 0;
    products.forEach((p) => {
      if (p.photo && p.photo.startsWith("data:image")) {
        totalProdPhotos++;
      }
    });
    receiptsCountEl.textContent = `Archivos listos para Drive: ${totalReceipts} comprobante(s) + ${totalProdPhotos} foto(s) de productos`;
  }
}

function updateBackendStatusUI(isConnected, message = "") {
  const badge = document.getElementById("backend-status-badge");
  const feedback = document.getElementById("backend-url-feedback");
  const btnCloudSave = document.getElementById("btn-cloud-save-header");
  const btnCloudReload = document.getElementById("btn-cloud-reload-header");

  if (isConnected && getAppsScriptUrl()) {
    if (badge) {
      badge.innerHTML = `<span class="badge" style="background:#dcfce7;color:#15803d;padding:6px 12px;border-radius:20px;font-size:0.84rem;font-weight:700;">🟢 Conectado</span>`;
    }
    if (btnCloudSave) {
      btnCloudSave.title = "Guardar en la nube (Google Sheets vía Apps Script)";
    }
    if (btnCloudReload) {
      btnCloudReload.title = "Recargar desde la nube (Google Sheets vía Apps Script)";
    }
    if (feedback && message) {
      feedback.style.color = "#15803d";
      feedback.textContent = message;
      feedback.classList.remove("hidden");
    }
  } else {
    if (badge) {
      badge.innerHTML = `<span class="badge" style="background:#fef3c7;color:#92400e;padding:6px 12px;border-radius:20px;font-size:0.84rem;font-weight:600;">🟡 Pendiente URL</span>`;
    }
  }
}

// EXPORTAR A GOOGLE SHEETS VÍA APPS SCRIPT
async function exportToGoogleSheets(isSilent = false) {
  console.log(`[HogarFlex Cloud Export] 🚀 Iniciando exportToGoogleSheets(isSilent = ${isSilent})...`);
  if (isExportingSheets) return;

  if (!navigator.onLine) {
    if (!isSilent) showSheetsStatus("Sin conexión. El respaldo se hará cuando vuelva el internet.", "error");
    return;
  }

  const scriptUrl = getAppsScriptUrl();
  if (!scriptUrl) {
    if (!isSilent) {
      showSheetsStatus("Por favor configura la URL de Google Apps Script en la sección de Respaldo.", "error");
    }
    return;
  }

  isExportingSheets = true;
  setCloudButtonsLoading(true, "export");
  const retryBtn = document.getElementById("btn-retry-sheets");
  const exportBtn = document.getElementById("btn-export-sheets");

  if (!isSilent) {
    showCloudSyncToast("⏳ Guardando datos en Google Sheets vía Apps Script...", "info");
    showSheetsStatus("⏳ Procesando sincronización con HogarFlex_DB...", "info");
    if (exportBtn) exportBtn.setAttribute("disabled", "true");
    if (retryBtn) retryBtn.classList.add("hidden");
  }

  try {
    // 1. Recopilar todos los datos desde localStorage
    const clients = getStoredClients();
    const credits = getStoredCredits();
    const sales = getStoredSales();
    const suppliers = getStoredSuppliers();
    const invoices = getStoredInvoices();
    const products = getStoredProducts();

    // Hoja 1: Clientes (cédula, nombre, teléfono, dirección)
    const clientsData = [
      ["Cédula", "Nombre", "Teléfono", "Dirección"],
      ...clients.map((c) => [
        c.dni || "",
        c.name || "",
        c.phone || "",
        c.address || ""
      ])
    ];

    // Hoja 2: Créditos (id, cliente, producto(s), total USD, cuota inicial, saldo, estado, fecha creación)
    const creditsData = [
      ["ID", "Cliente", "Producto(s)", "Total USD", "Cuota Inicial", "Saldo", "Estado", "Fecha Creación"],
      ...credits.map((cr) => {
        const clientName = cr.client?.name || "Cliente";
        const productsSummary = (cr.items || []).map((it) => {
          const p = parseFloat(it.precioUnitario !== undefined ? it.precioUnitario : (it.price !== undefined ? it.price : it.priceUSD)) || 0;
          const q = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
          const name = it.nombre || it.name || "Producto";
          return p > 0 ? `${name} (x${q} @ $${p.toFixed(2)})` : `${name} (x${q})`;
        }).join(", ");
        const dateStr = cr.createdAt ? formatDateDisplay(new Date(cr.createdAt)) : "";
        return [
          cr.id || "",
          clientName,
          productsSummary,
          parseFloat(cr.totalSaleUSD) || 0,
          parseFloat(cr.downpaymentAmount) || 0,
          parseFloat(cr.remainingBalance) || 0,
          cr.status || "Al día",
          dateStr
        ];
      })
    ];

    // Hoja 3: Pagos (id pago, id crédito, cliente, tipo (cuota/abono), monto USD, moneda, tasa BCV, monto Bs, fecha, referencia)
    const paymentsData = [
      ["ID Pago", "ID Crédito", "Cliente", "Tipo", "Monto USD", "Moneda", "Tasa BCV", "Monto Bs", "Fecha", "Referencia"]
    ];
    credits.forEach((cr) => {
      (cr.payments || []).forEach((p) => {
        const typeStr = p.type === "cuota" ? `Cuota ${p.installmentNumber ? '#' + p.installmentNumber : ''}` : "Abono libre";
        paymentsData.push([
          p.id || "",
          cr.id || "",
          cr.client?.name || "Cliente",
          typeStr,
          parseFloat(p.amountUSD) || 0,
          p.currency || "USD",
          p.rateBCVToday ? parseFloat(p.rateBCVToday) : "",
          p.amountBs ? parseFloat(p.amountBs) : "",
          p.date || "",
          p.referenceNumber || ""
        ]);
      });
    });

    // Hoja 4: Ventas_Directas (id, cliente, producto(s), precio USD, método pago, fecha)
    const salesData = [
      ["ID", "Cliente", "Producto(s)", "Precio USD", "Método Pago", "Fecha"],
      ...sales.map((s) => {
        const prods = (s.items || []).map((it) => {
          const p = parseFloat(it.precioUnitario !== undefined ? it.precioUnitario : (it.price !== undefined ? it.price : it.priceUSD)) || 0;
          const q = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
          const name = it.nombre || it.name || "Producto";
          return p > 0 ? `${name} (x${q} @ $${p.toFixed(2)})` : `${name} (x${q})`;
        }).join(", ");
        return [
          s.id || "",
          s.client?.name || "Cliente",
          prods,
          parseFloat(s.salePriceUSD) || 0,
          s.paymentMethod || "USD",
          s.date || ""
        ];
      })
    ];

    // Hoja 5: Proveedores (ID, Nombre, Teléfono, Dirección, Categoría, Notas)
    const suppliersData = [
      ["ID", "Nombre", "Teléfono", "Dirección", "Categoría", "Notas"],
      ...suppliers.map((s) => [
        s.id || "",
        s.name || "",
        s.phone || "",
        s.location || s.address || "",
        s.category || (Array.isArray(s.paymentMethods) ? s.paymentMethods.join(", ") : (s.paymentMethods || "General")),
        s.notes || ""
      ])
    ];

    // Hoja 6: Facturas (ID Factura, Cliente, Productos, Total USD, Fecha, Estado)
    const invoicesData = [
      ["ID Factura", "Cliente", "Productos", "Total USD", "Fecha", "Estado"],
      ...invoices.map((inv) => {
        const clientName = inv.client?.name || "Cliente";
        const prods = (inv.data?.items || []).map((it) => {
          const p = parseFloat(it.precioUnitario !== undefined ? it.precioUnitario : (it.price !== undefined ? it.price : it.priceUSD)) || 0;
          const q = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
          const name = it.nombre || it.name || "Producto";
          return p > 0 ? `${name} (x${q} @ $${p.toFixed(2)})` : `${name} (x${q})`;
        }).join(", ");
        const dateStr = inv.date ? formatDateDisplay(new Date(inv.date)) : "";
        const status = inv.status || (inv.data?.remainingBalance <= 0 ? "Pagada" : "Emitida");
        return [
          inv.docNumber || inv.id || "",
          clientName,
          prods,
          parseFloat(inv.totalAmountUSD) || 0,
          dateStr,
          status
        ];
      })
    ];

    // Hoja 7: Productos (ID, Nombre, Descripción, Precio USD, Categoría, Stock)
    // Las imágenes NO van a Sheets; se suben a Google Drive en HogarFlex_Productos
    const productsData = [
      ["ID", "Nombre", "Descripción", "Precio USD", "Categoría", "Stock"],
      ...products.map((p) => [
        p.id || "",
        p.name || "",
        p.description || "",
        parseFloat(p.price) || 0,
        p.category || "General",
        (p.quantity !== null && p.quantity !== undefined) ? p.quantity : (p.stock || "")
      ])
    ];

    // Calcular Métricas para Resumen/Dashboard (Config)
    const now = new Date();
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth();
    let totalCobradoMesUSD = 0;
    let totalPendienteUSD = 0;

    credits.forEach((cr) => {
      (cr.payments || []).forEach((p) => {
        const amt = parseFloat(p.amountUSD) || 0;
        if (amt > 0 && p.date) {
          const d = new Date(p.date);
          if (!isNaN(d.getTime()) && d.getFullYear() === currentYear && d.getMonth() === currentMonth) {
            totalCobradoMesUSD += amt;
          }
        }
      });
      if (cr.status !== "pagado" && cr.status !== "Pagado") {
        const bal = parseFloat(cr.remainingBalance);
        if (!isNaN(bal) && bal > 0.01) {
          totalPendienteUSD += bal;
        }
      }
    });

    sales.forEach((s) => {
      const amt = parseFloat(s.salePriceUSD) || 0;
      if (amt > 0 && (s.date || s.createdAt)) {
        const d = new Date(s.date || s.createdAt);
        if (!isNaN(d.getTime()) && d.getFullYear() === currentYear && d.getMonth() === currentMonth) {
          totalCobradoMesUSD += amt;
        }
      }
    });

    const nowStr = new Date().toLocaleString("es-VE");

    // Hoja 8: Config (fecha último respaldo, versión app, resumen y KPIs)
    const configData = [
      ["Parámetro", "Valor"],
      ["Fecha Último Respaldo", nowStr],
      ["Versión App", "1.0.0"],
      ["Total Clientes", String(clients.length)],
      ["Total Créditos", String(credits.length)],
      ["Total Pagos", String(paymentsData.length - 1)],
      ["Total Ventas Directas", String(sales.length)],
      ["Total Proveedores", String(suppliers.length)],
      ["Total Productos", String(products.length)],
      ["Total Facturas", String(invoices.length)],
      ["Total cobrado este mes", `$${totalCobradoMesUSD.toFixed(2)} USD`],
      ["Total pendiente por cobrar", `$${totalPendienteUSD.toFixed(2)} USD`]
    ];

    // 2. Enviar datos completos al Google Apps Script (POST)
    const payload = {
      action: "write",
      data: {
        Clientes: clientsData,
        "Créditos": creditsData,
        Pagos: paymentsData,
        "Ventas_Directas": salesData,
        Proveedores: suppliersData,
        Facturas: invoicesData,
        Productos: productsData,
        Config: configData
      }
    };

    const res = await fetch(scriptUrl, {
      method: "POST",
      body: JSON.stringify(payload)
    });

    if (!res.ok) {
      throw new Error(`Error en el servidor de Apps Script (${res.status})`);
    }

    const json = await res.json();
    const isSuccess = json && (json.status === "success" || json.success === true);
    if (!isSuccess) {
      throw new Error(json.message || json.error || "No se pudo escribir en el spreadsheet.");
    }

    localStorage.setItem(BACKUP_LAST_SHEETS_KEY, nowStr);
    renderBackupSection();

    // Sincronizar en segundo plano fotos de productos a Google Drive (HogarFlex_Productos)
    setTimeout(() => {
      exportProductImagesToGoogleDrive(true).catch(() => {});
    }, 100);

    if (!isSilent) {
      showSheetsStatus(`✅ Sincronización exitosa con HogarFlex_DB: ${nowStr}`, "success");
      showCloudSyncToast(`✅ Guardado con éxito en Google Sheets (${nowStr})`, "success");
    }
  } catch (err) {
    console.error("Error al exportar a Google Sheets vía Apps Script:", err);
    if (!isSilent) {
      showSheetsStatus(`Error: ${err.message || err}`, "error");
      showCloudSyncToast(`Error al guardar en la nube: ${err.message || err}`, "error");
      if (retryBtn) retryBtn.classList.remove("hidden");
    }
  } finally {
    isExportingSheets = false;
    setCloudButtonsLoading(false, "export");
    if (!isSilent && exportBtn) {
      exportBtn.removeAttribute("disabled");
    }
  }
}

// IMPORTAR DESDE GOOGLE SHEETS VÍA APPS SCRIPT
async function importFromGoogleSheets(isSilent = false) {
  if (isImportingSheets || isExportingSheets) return;

  if (!navigator.onLine) {
    if (!isSilent) {
      showCloudSyncToast("Sin conexión. No se pudo recargar desde la nube.", "error");
      showSheetsStatus("Sin conexión. No se pudo recargar desde la nube.", "error");
    }
    return;
  }

  const scriptUrl = getAppsScriptUrl();
  if (!scriptUrl) {
    if (!isSilent) {
      showSheetsStatus("Por favor configura la URL de Google Apps Script en la sección de Respaldo.", "error");
    }
    return;
  }

  isImportingSheets = true;
  setCloudButtonsLoading(true, "import");

  if (!isSilent) {
    showCloudSyncToast("⏳ Descargando base de datos desde HogarFlex_DB...", "info");
    showSheetsStatus("⏳ Descargando base de datos desde Google Sheets vía Apps Script...", "info");
  }

  try {
    const fetchUrl = scriptUrl + (scriptUrl.includes("?") ? "&" : "?") + "action=read";
    const res = await fetch(fetchUrl, { method: "GET" });

    if (!res.ok) {
      throw new Error(`Error al leer del Apps Script (${res.status})`);
    }

    const json = await res.json();
    const isSuccess = json && (json.status === "success" || json.success === true);
    if (!isSuccess) {
      throw new Error(json.message || json.error || "Error al obtener datos del spreadsheet.");
    }

    const sheetsData = json.data || {};
    const clientsRows = sheetsData["Clientes"] || [];
    const creditsRows = sheetsData["Créditos"] || [];
    const paymentsRows = sheetsData["Pagos"] || [];
    const salesRows = sheetsData["Ventas_Directas"] || [];
    const suppliersRows = sheetsData["Proveedores"] || [];
    const invoicesRows = sheetsData["Facturas"] || [];
    const productsRows = sheetsData["Productos"] || [];
    const configRows = sheetsData["Config"] || [];

    // Validar si las pestañas tienen filas con datos más allá del encabezado
    const hasData = clientsRows.length > 1 || creditsRows.length > 1 || salesRows.length > 1 ||
                    suppliersRows.length > 1 || invoicesRows.length > 1 || productsRows.length > 1;

    if (!hasData) {
      console.log("[HogarFlex Cloud Import] La base de datos en Google Sheets aún no contiene registros.");
      if (!isSilent) {
        showSheetsStatus("ℹ️ La hoja HogarFlex_DB está lista y esperando su primer respaldo.", "info");
      }
      return;
    }

    let hasUnsyncedLocal = false;

    // 1. Procesar CLIENTES (hoja Clientes) -> hogarflex_clients
    const existingClients = getStoredClients();
    const existingClientByDni = {};
    const existingClientByName = {};
    existingClients.forEach((c) => {
      if (c.dni) existingClientByDni[String(c.dni).trim().toLowerCase()] = c;
      if (c.name) existingClientByName[String(c.name).trim().toLowerCase()] = c;
    });

    const importedClients = [];
    for (let i = 1; i < clientsRows.length; i++) {
      const row = clientsRows[i];
      if (!row || row.length === 0) continue;
      const dni = String(row[0] || "").trim();
      const name = String(row[1] || "").trim();
      const phone = String(row[2] || "").trim();
      const address = String(row[3] || "").trim();

      if (!dni && !name) continue;

      const existing = existingClientByDni[dni.toLowerCase()] || existingClientByName[name.toLowerCase()];
      const clientId = existing ? existing.id : ("client_" + (Date.now() + i));
      const createdAt = existing && existing.createdAt ? existing.createdAt : (Date.now() - (clientsRows.length - i) * 60000);

      importedClients.push({
        id: clientId,
        dni,
        name,
        phone,
        address,
        createdAt,
        updatedAt: Date.now()
      });
    }

    // Preservar clientes locales no sincronizados en Sheets
    existingClients.forEach((locC) => {
      const alreadyInImported = importedClients.some((impC) =>
        (locC.dni && impC.dni && locC.dni.trim().toLowerCase() === impC.dni.trim().toLowerCase()) ||
        (locC.id && impC.id === locC.id)
      );
      if (!alreadyInImported && (locC.dni || locC.name)) {
        console.log(`[HogarFlex Cloud Import] 🛡️ Preservando cliente local no sincronizado en Sheets: "${locC.name}" (${locC.dni})`);
        importedClients.push(locC);
        hasUnsyncedLocal = true;
      }
    });

    // 2. Procesar PAGOS (hoja Pagos) -> indexados por ID Crédito y Nombre Cliente
    const paymentsByCreditId = {};
    const paymentsByClientName = {};

    for (let pIdx = 1; pIdx < paymentsRows.length; pIdx++) {
      const row = paymentsRows[pIdx];
      if (!row || row.length === 0) continue;
      const pId = String(row[0] || "").trim();
      const crId = String(row[1] || "").trim();
      const clientName = String(row[2] || "").trim();
      const typeStr = String(row[3] || "").trim();
      const amountUSD = parseFloat(row[4]) || 0;
      const currency = String(row[5] || "USD").trim().toUpperCase();
      const rateBCV = row[6] ? parseFloat(row[6]) : null;
      const amountBs = row[7] ? parseFloat(row[7]) : 0;
      const date = String(row[8] || "").trim();
      const reference = String(row[9] || "").trim();

      let instNum = null;
      const matchInst = typeStr.match(/(\d+)/);
      if (matchInst) instNum = parseInt(matchInst[1], 10);

      const paymentObj = {
        id: pId || ("pay_" + Date.now() + "_" + pIdx),
        date: date || new Date().toISOString(),
        type: typeStr.toLowerCase().includes("cuota") ? "cuota" : "abono",
        description: typeStr || "Pago",
        installmentNumber: instNum,
        amountUSD,
        currency: currency === "BS" ? "BS" : "USD",
        rateBCVToday: rateBCV,
        amountBs,
        referenceNumber: reference,
        receiptUrl: null,
        remainingBalanceAfter: null
      };

      if (crId) {
        if (!paymentsByCreditId[crId]) paymentsByCreditId[crId] = [];
        paymentsByCreditId[crId].push(paymentObj);
      }
      if (clientName) {
        const key = clientName.toLowerCase();
        if (!paymentsByClientName[key]) paymentsByClientName[key] = [];
        paymentsByClientName[key].push(paymentObj);
      }
    }

    // 3. Procesar CRÉDITOS (hoja Créditos) con PAGOS anidados -> hogarflex_credits
    const existingCredits = getStoredCredits();
    const existingCreditMap = {};
    existingCredits.forEach((c) => {
      if (c.id) existingCreditMap[String(c.id).trim()] = c;
    });

    const importedCredits = [];
    for (let cIdx = 1; cIdx < creditsRows.length; cIdx++) {
      const row = creditsRows[cIdx];
      if (!row || row.length === 0) continue;
      const crId = String(row[0] || "").trim();
      const clientName = String(row[1] || "").trim();
      const productsSummary = String(row[2] || "").trim();
      const totalSaleUSD = parseFloat(row[3]) || 0;
      const downpaymentAmount = parseFloat(row[4]) || 0;
      const remainingBalance = parseFloat(row[5]) || 0;
      const status = String(row[6] || "Al día").trim();
      const dateStr = String(row[7] || "").trim();

      if (!crId && !clientName) continue;

      const existingCr = existingCreditMap[crId];

      const matchingClient = importedClients.find((c) =>
        c.name.toLowerCase() === clientName.toLowerCase()
      ) || (existingCr ? existingCr.client : null) || {
        id: "client_" + Date.now(),
        name: clientName,
        dni: "",
        phone: "",
        address: ""
      };

      let items = existingCr && existingCr.items && existingCr.items.length > 0
        ? existingCr.items
        : parseProductsSummaryString(productsSummary, totalSaleUSD);

      let creditPayments = paymentsByCreditId[crId] || paymentsByClientName[clientName.toLowerCase()] || [];

      if (existingCr && Array.isArray(existingCr.payments)) {
        creditPayments.forEach((p) => {
          const matchP = existingCr.payments.find((lp) =>
            (lp.id && lp.id === p.id) ||
            (lp.referenceNumber && lp.referenceNumber === p.referenceNumber && lp.amountUSD === p.amountUSD)
          );
          if (matchP && matchP.receiptUrl) {
            p.receiptUrl = matchP.receiptUrl;
          }
        });
      }

      let createdAtTime = Date.now();
      if (existingCr && existingCr.createdAt) {
        createdAtTime = existingCr.createdAt;
      } else if (dateStr) {
        const parts = dateStr.split("/");
        if (parts.length === 3) {
          const d = parseInt(parts[0], 10);
          const m = parseInt(parts[1], 10) - 1;
          const y = parseInt(parts[2], 10);
          createdAtTime = new Date(y, m, d).getTime();
        } else {
          const parsed = Date.parse(dateStr);
          if (!isNaN(parsed)) createdAtTime = parsed;
        }
      }

      const creditObj = {
        id: crId || ("cred_" + (Date.now() + cIdx)),
        createdAt: createdAtTime,
        clientId: matchingClient.id,
        client: {
          id: matchingClient.id,
          name: matchingClient.name,
          dni: matchingClient.dni || "",
          phone: matchingClient.phone || "",
          address: matchingClient.address || ""
        },
        items,
        totalSaleUSD,
        downpaymentAmount,
        remainingBalance,
        status,
        downpaymentCurrency: existingCr ? existingCr.downpaymentCurrency : "USD",
        downpaymentPercent: totalSaleUSD > 0 ? Math.round((downpaymentAmount / totalSaleUSD) * 100) : 0,
        downpaymentPaidUSD: existingCr ? existingCr.downpaymentPaidUSD : downpaymentAmount,
        downpaymentPaidBs: existingCr ? existingCr.downpaymentPaidBs : 0,
        installmentsCount: existingCr && existingCr.installmentsCount ? existingCr.installmentsCount : (creditPayments.length > 0 ? creditPayments.length : 1),
        installments: existingCr && Array.isArray(existingCr.installments) && existingCr.installments.length > 0 ? existingCr.installments : [],
        payments: creditPayments
      };

      if (!creditObj.installments || creditObj.installments.length === 0) {
        const debt = Math.max(0, totalSaleUSD - downpaymentAmount);
        const count = creditObj.installmentsCount || 1;
        const perInst = count > 0 ? (debt / count) : debt;
        for (let num = 1; num <= count; num++) {
          creditObj.installments.push({
            number: num,
            dueDate: new Date(createdAtTime + num * 30 * 24 * 3600 * 1000).toISOString().split("T")[0],
            amountUSD: perInst,
            status: remainingBalance <= 0 ? "Pagada" : "Pendiente"
          });
        }
      }

      if (typeof recalculateCreditFinances === "function") {
        recalculateCreditFinances(creditObj);
      }

      importedCredits.push(creditObj);
    }

    // Preservar créditos locales no sincronizados en Sheets
    existingCredits.forEach((locCr) => {
      const alreadyInImported = importedCredits.some((impCr) => impCr.id === locCr.id);
      if (!alreadyInImported && locCr.id) {
        console.log(`[HogarFlex Cloud Import] 🛡️ Preservando crédito local no sincronizado en Sheets: "${locCr.id}"`);
        importedCredits.push(locCr);
        hasUnsyncedLocal = true;
      }
    });

    // 4. Procesar VENTAS DIRECTAS (hoja Ventas_Directas) -> hogarflex_ventas_directas
    const existingSales = getStoredSales();
    const existingSaleMap = {};
    existingSales.forEach((s) => {
      if (s.id) existingSaleMap[String(s.id).trim()] = s;
    });

    const importedSales = [];
    for (let sIdx = 1; sIdx < salesRows.length; sIdx++) {
      const row = salesRows[sIdx];
      if (!row || row.length === 0) continue;
      const sId = String(row[0] || "").trim();
      const clientName = String(row[1] || "").trim();
      const prodsSummary = String(row[2] || "").trim();
      const priceUSD = parseFloat(row[3]) || 0;
      const method = String(row[4] || "USD").trim();
      const dateStr = String(row[5] || "").trim();

      if (!sId && !clientName) continue;

      const existingSale = existingSaleMap[sId];
      const matchingClient = importedClients.find((c) =>
        c.name.toLowerCase() === clientName.toLowerCase()
      ) || (existingSale ? existingSale.client : null) || {
        id: "client_" + Date.now(),
        name: clientName,
        dni: "",
        phone: "",
        address: ""
      };

      importedSales.push({
        id: sId || ("sale_" + (Date.now() + sIdx)),
        clientId: matchingClient.id,
        client: {
          id: matchingClient.id,
          name: matchingClient.name,
          dni: matchingClient.dni || "",
          phone: matchingClient.phone || "",
          address: matchingClient.address || ""
        },
        items: existingSale && existingSale.items ? existingSale.items : parseProductsSummaryString(prodsSummary, priceUSD),
        salePriceUSD: priceUSD,
        catalogTotalUSD: existingSale ? existingSale.catalogTotalUSD : priceUSD,
        paymentMethod: method,
        rateBCVToday: existingSale ? existingSale.rateBCVToday : null,
        amountBs: existingSale ? existingSale.amountBs : 0,
        date: dateStr || (existingSale ? existingSale.date : new Date().toISOString().split("T")[0]),
        referenceNumber: existingSale ? existingSale.referenceNumber : "",
        receiptUrl: existingSale ? existingSale.receiptUrl : null,
        notes: existingSale ? existingSale.notes : "",
        createdAt: existingSale ? existingSale.createdAt : (dateStr || new Date().toISOString())
      });
    }

    // Preservar ventas directas locales no sincronizadas en Sheets
    existingSales.forEach((locS) => {
      const alreadyInImported = importedSales.some((impS) => impS.id === locS.id);
      if (!alreadyInImported && locS.id) {
        console.log(`[HogarFlex Cloud Import] 🛡️ Preservando venta directa local no sincronizada: "${locS.id}"`);
        importedSales.push(locS);
        hasUnsyncedLocal = true;
      }
    });

    // 5. Procesar PROVEEDORES (hoja Proveedores) -> hogarflex_suppliers
    const existingSuppliers = getStoredSuppliers();
    const existingSupplierMap = {};
    existingSuppliers.forEach((s) => {
      if (s.id) existingSupplierMap[String(s.id).trim()] = s;
      if (s.name) existingSupplierMap[String(s.name).trim().toLowerCase()] = s;
    });

    const importedSuppliers = [];
    for (let supIdx = 1; supIdx < suppliersRows.length; supIdx++) {
      const row = suppliersRows[supIdx];
      if (!row || row.length === 0) continue;
      const sId = String(row[0] || "").trim();
      const sName = String(row[1] || "").trim();
      const sPhone = String(row[2] || "").trim();
      const sLocation = String(row[3] || "").trim();
      const sCategory = String(row[4] || "").trim();
      const sNotes = String(row[5] || "").trim();

      if (!sId && !sName) continue;

      const existingSup = existingSupplierMap[sId] || existingSupplierMap[sName.toLowerCase()];
      importedSuppliers.push({
        id: sId || ("sup_" + (Date.now() + supIdx)),
        name: sName,
        phone: sPhone,
        location: sLocation,
        category: sCategory || "General",
        notes: sNotes,
        paymentMethods: existingSup && existingSup.paymentMethods ? existingSup.paymentMethods : (sCategory ? [sCategory] : []),
        productsCost: existingSup && existingSup.productsCost ? existingSup.productsCost : [],
        createdAt: existingSup && existingSup.createdAt ? existingSup.createdAt : new Date().toISOString()
      });
    }

    // Preservar proveedores locales no sincronizados en Sheets
    existingSuppliers.forEach((locSup) => {
      const alreadyInImported = importedSuppliers.some((impSup) =>
        (locSup.id && impSup.id === locSup.id) ||
        (locSup.name && impSup.name && locSup.name.trim().toLowerCase() === impSup.name.trim().toLowerCase())
      );
      if (!alreadyInImported && (locSup.id || locSup.name)) {
        console.log(`[HogarFlex Cloud Import] 🛡️ Preservando proveedor local no sincronizado en Sheets: "${locSup.name}"`);
        importedSuppliers.push(locSup);
        hasUnsyncedLocal = true;
      }
    });

    // 6. Procesar FACTURAS (hoja Facturas) -> hogarflex_invoices
    const existingInvoices = getStoredInvoices();
    const existingInvoiceMap = {};
    existingInvoices.forEach((inv) => {
      if (inv.id) existingInvoiceMap[String(inv.id).trim()] = inv;
      if (inv.docNumber) existingInvoiceMap[String(inv.docNumber).trim()] = inv;
    });

    const importedInvoices = [];
    for (let invIdx = 1; invIdx < invoicesRows.length; invIdx++) {
      const row = invoicesRows[invIdx];
      if (!row || row.length === 0) continue;
      const docNum = String(row[0] || "").trim();
      const clientName = String(row[1] || "").trim();
      const prodsSummary = String(row[2] || "").trim();
      const totalUSD = parseFloat(row[3]) || 0;
      const dateStr = String(row[4] || "").trim();
      const status = String(row[5] || "Emitida").trim();

      if (!docNum && !clientName) continue;

      const existingInv = existingInvoiceMap[docNum];
      const matchingClient = importedClients.find((c) => c.name.toLowerCase() === clientName.toLowerCase()) ||
        (existingInv ? existingInv.client : null) || { name: clientName, dni: "-", phone: "", address: "" };

      let invDataItems = (existingInv && existingInv.data && Array.isArray(existingInv.data.items) && existingInv.data.items.length > 0)
        ? existingInv.data.items
        : parseProductsSummaryString(prodsSummary, totalUSD);

      // Normalizar e incrustar precios reales en cada ítem de la factura importada
      invDataItems = invDataItems.map((it, itIdx) => {
        const qty = parseInt(it.cantidad !== undefined ? it.cantidad : (it.quantity !== undefined ? it.quantity : it.qty), 10) || 1;
        let p = parseFloat(it.precioUnitario !== undefined ? it.precioUnitario : (it.price !== undefined ? it.price : (it.priceUSD !== undefined ? it.priceUSD : it.unitPrice))) || 0;
        let tot = parseFloat(it.totalLinea !== undefined ? it.totalLinea : it.subtotal) || 0;

        if (p <= 0) {
          const cat = importedProducts.find(cp => (it.productId && String(cp.id) === String(it.productId)) || (cp.name && (it.name || it.nombre) && cp.name.trim().toLowerCase() === (it.name || it.nombre).trim().toLowerCase()));
          if (cat && parseFloat(cat.price) > 0) p = parseFloat(cat.price);
          else if (tot > 0) p = parseFloat((tot / qty).toFixed(2));
          else if (totalUSD > 0) p = parseFloat((totalUSD / invDataItems.length / qty).toFixed(2));
        }
        if (tot <= 0) tot = parseFloat((qty * p).toFixed(2));

        const n = it.nombre || it.name || "Producto";
        return {
          id: it.id || `item_inv_${invIdx}_${itIdx}`,
          productId: it.productId || "",
          name: n,
          nombre: n,
          quantity: qty,
          qty: qty,
          cantidad: qty,
          price: p,
          priceUSD: p,
          precioUnitario: p,
          unitPrice: p,
          subtotal: tot,
          totalLinea: tot
        };
      });

      importedInvoices.push({
        id: existingInv ? existingInv.id : `inv_fac_${Date.now()}_${invIdx}`,
        type: existingInv ? existingInv.type : "factura_credito",
        docNumber: docNum || `FAC-${String(invIdx).padStart(4, "0")}`,
        date: dateStr || (existingInv ? existingInv.date : new Date().toISOString()),
        creditId: existingInv ? existingInv.creditId : null,
        paymentId: existingInv ? existingInv.paymentId : null,
        client: matchingClient,
        totalAmountUSD: totalUSD,
        totalAmountBs: existingInv ? existingInv.totalAmountBs : null,
        rateBCV: existingInv ? existingInv.rateBCV : null,
        status: status,
        data: {
          ...(existingInv && existingInv.data ? existingInv.data : {}),
          items: invDataItems,
          totalSaleUSD: totalUSD,
          remainingBalance: status.toLowerCase() === "pagada" ? 0 : (existingInv && existingInv.data && existingInv.data.remainingBalance !== undefined ? existingInv.data.remainingBalance : totalUSD)
        },
        createdAt: existingInv ? existingInv.createdAt : Date.now()
      });
    }

    // Preservar facturas locales no sincronizadas en Sheets
    existingInvoices.forEach((locInv) => {
      const alreadyInImported = importedInvoices.some((impInv) =>
        (locInv.docNumber && impInv.docNumber === locInv.docNumber) ||
        (locInv.id && impInv.id === locInv.id)
      );
      if (!alreadyInImported && (locInv.id || locInv.docNumber)) {
        console.log(`[HogarFlex Cloud Import] 🛡️ Preservando factura local no sincronizada: "${locInv.docNumber || locInv.id}"`);
        importedInvoices.push(locInv);
        hasUnsyncedLocal = true;
      }
    });

    // 7. Procesar PRODUCTOS (hoja Productos) -> hogarflex_products
    const existingProducts = getStoredProducts();
    const existingProductMap = {};
    existingProducts.forEach((p) => {
      if (p.id) existingProductMap[String(p.id).trim()] = p;
      if (p.name) existingProductMap[String(p.name).trim().toLowerCase()] = p;
    });

    const importedProducts = [];
    for (let prodIdx = 1; prodIdx < productsRows.length; prodIdx++) {
      const row = productsRows[prodIdx];
      if (!row || row.length === 0) continue;
      const pId = String(row[0] || "").trim();
      const pName = String(row[1] || "").trim();
      const pDesc = String(row[2] || "").trim();
      const pPrice = parseFloat(row[3]) || 0;
      const pCategory = String(row[4] || "General").trim();
      const pStock = row[5] !== "" && row[5] !== undefined && row[5] !== null ? parseInt(row[5], 10) : null;

      if (!pId && !pName) continue;

      const existingProd = existingProductMap[pId] || existingProductMap[pName.toLowerCase()];
      importedProducts.push({
        id: pId || ("prod_" + (Date.now() + prodIdx)),
        name: pName,
        description: pDesc,
        price: pPrice.toFixed(2),
        category: pCategory,
        quantity: !isNaN(pStock) ? pStock : null,
        photo: existingProd && existingProd.photo ? existingProd.photo : "",
        createdAt: existingProd && existingProd.createdAt ? existingProd.createdAt : Date.now()
      });
    }

    // Preservar productos locales no sincronizados en Sheets
    existingProducts.forEach((locProd) => {
      const alreadyInImported = importedProducts.some((impProd) =>
        (locProd.id && impProd.id === locProd.id) ||
        (locProd.name && impProd.name && locProd.name.trim().toLowerCase() === impProd.name.trim().toLowerCase())
      );
      if (!alreadyInImported && (locProd.id || locProd.name)) {
        console.log(`[HogarFlex Cloud Import] 🛡️ Preservando producto local no sincronizado: "${locProd.name}"`);
        importedProducts.push(locProd);
        hasUnsyncedLocal = true;
      }
    });

    // 8. Procesar CONFIGURACIÓN (hoja Config) -> hogarflex_config
    const importedConfig = {};
    for (let cfgIdx = 1; cfgIdx < configRows.length; cfgIdx++) {
      const row = configRows[cfgIdx];
      if (row && row[0]) {
        importedConfig[String(row[0]).trim()] = String(row[1] || "").trim();
      }
    }

    // 9. Sobrescribir localStorage únicamente tras validar y parsear con éxito
    if (importedClients.length > 0) {
      localStorage.setItem(CLIENTS_STORAGE_KEY, JSON.stringify(importedClients));
    }
    if (importedCredits.length > 0) {
      localStorage.setItem(CREDITS_STORAGE_KEY, JSON.stringify(importedCredits));
    }
    if (importedSales.length > 0) {
      localStorage.setItem(SALES_STORAGE_KEY, JSON.stringify(importedSales));
    }
    if (importedSuppliers.length > 0) {
      localStorage.setItem(SUPPLIERS_STORAGE_KEY, JSON.stringify(importedSuppliers));
    }
    if (importedInvoices.length > 0) {
      localStorage.setItem(INVOICES_STORAGE_KEY, JSON.stringify(importedInvoices));
    }
    if (importedProducts.length > 0) {
      localStorage.setItem(PRODUCTS_STORAGE_KEY, JSON.stringify(importedProducts));
    }
    if (Object.keys(importedConfig).length > 0) {
      localStorage.setItem("hogarflex_config", JSON.stringify(importedConfig));
      if (importedConfig["Fecha Último Respaldo"]) {
        localStorage.setItem(BACKUP_LAST_SHEETS_KEY, importedConfig["Fecha Último Respaldo"]);
      }
    }

    // Si se detectaron registros locales no sincronizados, disparar subida automática para persistirlos en Sheets
    if (hasUnsyncedLocal) {
      console.log("[HogarFlex Cloud Import] ⚡ Detectados registros locales pendientes de subir a Sheets. Ejecutando auto-backup inmediato...");
      triggerAutoCloudBackup("registros-locales-recientes");
    }

    // 10. Actualizar todas las vistas activas
    if (typeof renderClients === "function") renderClients();
    if (typeof renderCredits === "function") renderCredits();
    if (typeof renderPagosSection === "function") renderPagosSection();
    if (typeof renderVentasSection === "function") renderVentasSection();
    if (typeof renderProducts === "function") renderProducts();
    if (typeof renderSuppliersTable === "function") renderSuppliersTable();
    if (typeof renderFacturacionSection === "function") renderFacturacionSection();
    if (typeof renderDashboardSection === "function") renderDashboardSection();
    if (typeof renderBackupSection === "function") renderBackupSection();

    const successSummary = `✅ Sincronizado: ${importedClients.length} clientes, ${importedCredits.length} créditos, ${importedSales.length} ventas, ${importedProducts.length} productos, ${importedSuppliers.length} proveedores, ${importedInvoices.length} facturas.`;
    showSheetsStatus(successSummary, "success");
    if (!isSilent) {
      showCloudSyncToast(successSummary, "success");
    }
  } catch (err) {
    console.error("Error al importar desde Google Sheets vía Apps Script:", err);
    if (!isSilent) {
      showSheetsStatus(`Error al recargar desde la nube: ${err.message || err}`, "error");
      showCloudSyncToast(`Error al recargar: ${err.message || err}`, "error");
    }
  } finally {
    isImportingSheets = false;
    setCloudButtonsLoading(false, "import");
  }
}

// Utilidad auxiliar para reconstruir array de items desde resumen de texto de Google Sheets con precios reales
function parseProductsSummaryString(summary, fallbackPrice = 0) {
  const catalogProducts = typeof getStoredProducts === "function" ? getStoredProducts() : [];

  if (!summary || typeof summary !== "string" || !summary.trim()) {
    const fPrice = parseFloat(fallbackPrice) || 0;
    return [{
      id: "item_gen",
      productId: "",
      name: "Producto",
      nombre: "Producto",
      quantity: 1,
      qty: 1,
      cantidad: 1,
      price: fPrice,
      priceUSD: fPrice,
      precioUnitario: fPrice,
      unitPrice: fPrice,
      subtotal: fPrice,
      totalLinea: fPrice
    }];
  }

  const parts = summary.split(",");
  const items = [];

  parts.forEach((p, idx) => {
    const trimmed = p.trim();
    if (!trimmed) return;

    let qty = 1;
    let explicitPrice = null;
    let name = trimmed;

    // Detectar formato combinado: (x2 @ $350.00) o (x1 @ 350)
    const combinedMatch = name.match(/\(x(\d+)\s*(?:@\s*\$?([0-9]+(?:\.[0-9]+)?))?\)/i);
    if (combinedMatch) {
      qty = parseInt(combinedMatch[1], 10) || 1;
      if (combinedMatch[2]) explicitPrice = parseFloat(combinedMatch[2]);
      name = name.replace(/\(x\d+\s*(?:@\s*\$?[0-9]+(?:\.[0-9]+)?)?\)/i, "").trim();
    }

    // Detectar precio explícito standalone si aún no se extrajo: @ $XX.XX o @ XX.XX
    if (explicitPrice === null) {
      const atPriceMatch = name.match(/@\s*\$?([0-9]+(?:\.[0-9]+)?)/i);
      if (atPriceMatch) {
        explicitPrice = parseFloat(atPriceMatch[1]);
        name = name.replace(/@\s*\$?[0-9]+(?:\.[0-9]+)?/i, "").trim();
      }
    }

    // Detectar cantidad standalone si aún no se extrajo: (xN)
    const qtyMatch = name.match(/\(x(\d+)\s*\)/i);
    if (qtyMatch) {
      qty = parseInt(qtyMatch[1], 10) || qty;
      name = name.replace(/\(x\d+\s*\)/i, "").trim();
    }

    name = name.replace(/\(\s*\)/g, "").trim();

    // Determinar precio unitario numérico
    let unitPrice = 0;
    if (explicitPrice !== null && !isNaN(explicitPrice) && explicitPrice > 0) {
      unitPrice = explicitPrice;
    } else {
      // Buscar en el catálogo de productos por nombre
      const catMatch = catalogProducts.find(cp => cp.name && name && cp.name.trim().toLowerCase() === name.toLowerCase());
      if (catMatch && parseFloat(catMatch.price) > 0) {
        unitPrice = parseFloat(catMatch.price);
      } else if (fallbackPrice > 0) {
        unitPrice = parseFloat((fallbackPrice / (parts.length || 1) / qty).toFixed(2));
      }
    }

    const lineTotal = parseFloat((qty * unitPrice).toFixed(2));

    items.push({
      id: "prod_import_" + idx + "_" + Date.now(),
      productId: "",
      name: name || "Producto",
      nombre: name || "Producto",
      quantity: qty,
      qty: qty,
      cantidad: qty,
      price: unitPrice,
      priceUSD: unitPrice,
      precioUnitario: unitPrice,
      unitPrice: unitPrice,
      subtotal: lineTotal,
      totalLinea: lineTotal
    });
  });

  return items.length > 0 ? items : [{
    id: "item_gen",
    productId: "",
    name: "Producto",
    nombre: "Producto",
    quantity: 1,
    qty: 1,
    cantidad: 1,
    price: parseFloat(fallbackPrice) || 0,
    priceUSD: parseFloat(fallbackPrice) || 0,
    precioUnitario: parseFloat(fallbackPrice) || 0,
    unitPrice: parseFloat(fallbackPrice) || 0,
    subtotal: parseFloat(fallbackPrice) || 0,
    totalLinea: parseFloat(fallbackPrice) || 0
  }];
}

// Feedback visual de botones de nube (spinners y estados)
function setCloudButtonsLoading(isLoading, action = "export") {
  const btnExport = document.getElementById("btn-export-sheets");
  const btnImport = document.getElementById("btn-import-sheets");
  const btnSaveHdr = document.getElementById("btn-cloud-save-header");
  const btnReloadHdr = document.getElementById("btn-cloud-reload-header");

  if (action === "export") {
    if (btnExport) {
      if (isLoading) {
        btnExport.setAttribute("disabled", "true");
        btnExport.innerHTML = `<span class="spinner-icon">🔄</span> <span>Guardando en la nube...</span>`;
      } else {
        btnExport.removeAttribute("disabled");
        btnExport.innerHTML = `<span class="btn-icon">☁️⬆️</span> <span class="btn-text">Guardar en la nube</span>`;
      }
    }
    if (btnSaveHdr) {
      if (isLoading) {
        btnSaveHdr.classList.add("loading");
        btnSaveHdr.innerHTML = `<span class="spinner-icon">🔄</span> <span class="cloud-label">Guardando...</span>`;
      } else {
        btnSaveHdr.classList.remove("loading");
        btnSaveHdr.innerHTML = `<span class="cloud-icon">☁️⬆️</span> <span class="cloud-label">Guardar en nube</span>`;
      }
    }
  } else if (action === "import") {
    if (btnImport) {
      if (isLoading) {
        btnImport.setAttribute("disabled", "true");
        btnImport.innerHTML = `<span class="spinner-icon">🔄</span> <span>Recargando de la nube...</span>`;
      } else {
        btnImport.removeAttribute("disabled");
        btnImport.innerHTML = `<span class="btn-icon">☁️⬇️</span> <span class="btn-text">Recargar desde la nube</span>`;
      }
    }
    if (btnReloadHdr) {
      if (isLoading) {
        btnReloadHdr.classList.add("loading");
        btnReloadHdr.innerHTML = `<span class="spinner-icon">🔄</span> <span class="cloud-label">Recargando...</span>`;
      } else {
        btnReloadHdr.classList.remove("loading");
        btnReloadHdr.innerHTML = `<span class="cloud-icon">☁️⬇️</span> <span class="cloud-label">Recargar de nube</span>`;
      }
    }
  }
}

// Toast flotante para feedback de sincronización en cualquier pantalla
let cloudToastTimer = null;
function showCloudSyncToast(message, type = "info") {
  const toast = document.getElementById("cloud-sync-toast");
  const toastText = document.getElementById("cloud-sync-toast-text");
  const toastIcon = document.getElementById("cloud-sync-toast-icon");
  if (!toast || !toastText) return;

  if (cloudToastTimer) {
    clearTimeout(cloudToastTimer);
    cloudToastTimer = null;
  }

  toastText.textContent = message;
  toast.className = "cloud-toast show";

  if (type === "success") {
    toast.style.background = "#f0fdf4";
    toast.style.border = "1px solid #86efac";
    toast.style.color = "#15803d";
    if (toastIcon) toastIcon.textContent = "✅";
  } else if (type === "error") {
    toast.style.background = "#fef2f2";
    toast.style.border = "1px solid #fca5a5";
    toast.style.color = "#b91c1c";
    if (toastIcon) toastIcon.textContent = "❌";
  } else {
    toast.style.background = "#eff6ff";
    toast.style.border = "1px solid #93c5fd";
    toast.style.color = "#1d4ed8";
    if (toastIcon) toastIcon.textContent = "⏳";
  }

  if (type !== "info") {
    cloudToastTimer = setTimeout(() => {
      toast.classList.remove("show");
    }, 4500);
  }
}

// EXPORTAR FOTOS DE PRODUCTOS A GOOGLE DRIVE VÍA APPS SCRIPT (HogarFlex_Productos)
async function exportProductImagesToGoogleDrive(isSilent = true) {
  const scriptUrl = getAppsScriptUrl();
  if (!scriptUrl || !navigator.onLine) return 0;

  try {
    const products = getStoredProducts();
    const productsWithPhoto = products.filter((p) => p.photo && p.photo.startsWith("data:image"));
    if (productsWithPhoto.length === 0) return 0;

    let uploadedCount = 0;
    for (const prod of productsWithPhoto) {
      try {
        const res = await fetch(scriptUrl, {
          method: "POST",
          body: JSON.stringify({
            action: "upload_product_image",
            productId: prod.id,
            fileName: `producto_${prod.id}.jpg`,
            base64: prod.photo
          })
        });
        if (res.ok) {
          const json = await res.json();
          const isSuccess = json && (json.status === "success" || json.success === true);
          if (isSuccess && !json.alreadyExists) {
            uploadedCount++;
          }
        }
      } catch (err) {
        console.warn("Error al subir foto de producto a Drive:", prod.id, err);
      }
    }
    if (uploadedCount > 0) {
      console.log(`[HogarFlex Drive] ✅ ${uploadedCount} fotos de productos sincronizadas en HogarFlex_Productos.`);
    }
    return uploadedCount;
  } catch (err) {
    console.error("Error al exportar fotos de productos a Drive:", err);
    return 0;
  }
}

// EXPORTAR ARCHIVOS A GOOGLE DRIVE VÍA APPS SCRIPT (Comprobantes y Fotos)
async function exportReceiptsToGoogleDrive() {
  if (isExportingReceipts) return;

  if (!navigator.onLine) {
    showReceiptsStatus("Sin conexión. El respaldo se hará cuando vuelva el internet.", "error");
    return;
  }

  const scriptUrl = getAppsScriptUrl();
  if (!scriptUrl) {
    alert("Por favor configura la URL de Google Apps Script antes de exportar.");
    return;
  }

  isExportingReceipts = true;
  const exportBtn = document.getElementById("btn-export-receipts");

  showReceiptsStatus("⏳ Sincronizando comprobantes y fotos de productos en Google Drive...", "info");
  if (exportBtn) exportBtn.setAttribute("disabled", "true");

  try {
    const credits = getStoredCredits();
    const receiptsToUpload = [];

    const monthNames = [
      "01_Enero", "02_Febrero", "03_Marzo", "04_Abril",
      "05_Mayo", "06_Junio", "07_Julio", "08_Agosto",
      "09_Septiembre", "10_Octubre", "11_Noviembre", "12_Diciembre"
    ];

    credits.forEach((cr) => {
      const clientDni = (cr.client?.dni || "V0").replace(/[^a-zA-Z0-9]/g, "");
      const clientName = (cr.client?.name || "Cliente").replace(/\s+/g, "_").replace(/[^a-zA-Z0-9_]/g, "");
      (cr.payments || []).forEach((p) => {
        if (p.receiptUrl && p.receiptUrl.startsWith("data:image")) {
          const dateObj = new Date(p.date || Date.now());
          const mIndex = dateObj.getMonth();
          const monthFolder = monthNames[mIndex] || "00_Varios";
          const dateStr = p.date ? String(p.date).split("T")[0] : "fecha";
          const fileName = `PAGO_${clientDni}_${clientName}_${dateStr}.jpg`;

          receiptsToUpload.push({
            fileName,
            monthFolder,
            base64: p.receiptUrl
          });
        }
      });
    });

    let uploadedReceiptsCount = 0;
    for (const item of receiptsToUpload) {
      try {
        const res = await fetch(scriptUrl, {
          method: "POST",
          body: JSON.stringify({
            action: "upload_receipt",
            fileName: item.fileName,
            monthFolder: item.monthFolder,
            base64: item.base64
          })
        });
        if (res.ok) {
          const json = await res.json();
          const isSuccess = json && (json.status === "success" || json.success === true);
          if (isSuccess && !json.alreadyExists) {
            uploadedReceiptsCount++;
          }
        }
      } catch (uploadErr) {
        console.warn("Error subiendo comprobante individual:", item.fileName, uploadErr);
      }
    }

    // Sincronizar también fotos de productos a HogarFlex_Productos
    const uploadedPhotosCount = await exportProductImagesToGoogleDrive(false);

    if (uploadedReceiptsCount > 0 || uploadedPhotosCount > 0) {
      showReceiptsStatus(`✅ Sincronizados en Drive: ${uploadedReceiptsCount} comprobante(s) y ${uploadedPhotosCount} foto(s) de productos.`, "success");
    } else {
      showReceiptsStatus(`✅ Todos los comprobantes y fotos ya estaban sincronizados en Google Drive.`, "success");
    }
  } catch (err) {
    console.error("Error al exportar archivos a Drive vía Apps Script:", err);
    showReceiptsStatus(`Error: ${err.message || err}`, "error");
  } finally {
    isExportingReceipts = false;
    if (exportBtn) exportBtn.removeAttribute("disabled");
  }
}

// Auxiliares de interfaz para mostrar mensajes de estado
function showSheetsStatus(message, type) {
  const el = document.getElementById("sheets-status-msg");
  if (!el) return;
  el.textContent = message;
  el.className = "";
  if (type === "success") {
    el.style.background = "#f0fdf4";
    el.style.border = "1px solid #bbf7d0";
    el.style.color = "#15803d";
  } else if (type === "error") {
    el.style.background = "#fef2f2";
    el.style.border = "1px solid #fecaca";
    el.style.color = "#b91c1c";
  } else {
    el.style.background = "#eff6ff";
    el.style.border = "1px solid #bfdbfe";
    el.style.color = "#1d4ed8";
  }
  el.classList.remove("hidden");
}

function showReceiptsStatus(message, type) {
  const el = document.getElementById("receipts-status-msg");
  if (!el) return;
  el.textContent = message;
  el.className = "";
  if (type === "success") {
    el.style.background = "#f0fdf4";
    el.style.border = "1px solid #bbf7d0";
    el.style.color = "#15803d";
  } else if (type === "error") {
    el.style.background = "#fef2f2";
    el.style.border = "1px solid #fecaca";
    el.style.color = "#b91c1c";
  } else {
    el.style.background = "#eff6ff";
    el.style.border = "1px solid #bfdbfe";
    el.style.color = "#1d4ed8";
  }
  el.classList.remove("hidden");
}

